INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a5a5f7f-3f3d-4471-b883-9f8ab80cd1a7', '鄭國夫人挽歌詞', '鄭国夫人挽歌词', '14e59a33-174c-4ab6-917b-a867358e203a', '唐', '["淑德延公胄，宜家接帝姻。","桂宮男掌僕，蘭殿女昇嬪。","恩澤昭前命，盈虛變此辰。","萬年今已矣，彤管列何人。"]', '["淑德延公胄，宜家接帝姻。","桂宮男掌僕，蘭殿女昇嬪。","恩澤昭前命，盈虛变此辰。","万年今已矣，彤管列何人。"]', '诗', 'shi', '', NULL, '鄭國夫人挽歌詞 趙良器 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ae441bd-4ec8-460e-853f-f367e2e2fa05', '郡中客舍', '郡中客舍', '20141972-6377-4e40-8c24-338cd0db23bd', '唐', '["蟲響亂啾啾，更人正數籌。","魂歸洞庭夜，霜臥洛陽秋。","微月有時隱，長河到曉流。","起來還囑雁，鄉信在吳洲。"]', '["蟲响亂啾啾，更人正數籌。","魂归洞庭夜，霜臥洛陽秋。","微月有时隐，长河到晓流。","起来還囑雁，乡信在吳洲。"]', '诗', 'shi', '', NULL, '郡中客舍 黃麟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32898701-8d9c-4b4d-b192-510564f63b2f', '途中口號', '途中口號', '8ef12693-0f19-4444-b4ec-2d4f04bb0b6b', '唐', '["抱玉三朝楚，懷書十上秦。","年年洛陽陌，花鳥弄歸人。"]', '["抱玉三朝楚，懷书十上秦。","年年洛陽陌，花鸟弄归人。"]', '诗', 'shi', '', NULL, '途中口號 郭向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee36aa5a-c3d0-4875-8ff8-e1807a7ce622', '題李將軍山亭', '題李將軍山亭', 'cd7788e3-949a-41be-8a14-0769ca1ccec6', '唐', '["鳳轄將軍位，龍門司隸家。","衣冠爲隱逸，山水作繁華。","徑出重林草，池搖兩岸花。","誰知貴公第，亭院有煙霞。"]', '["鳳轄將軍位，龙门司隸家。","衣冠爲隐逸，山水作繁华。","徑出重林草，池搖兩岸花。","誰知貴公第，亭院有煙霞。"]', '诗', 'shi', '', NULL, '題李將軍山亭 郭良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('736323fa-2b48-48cc-9d86-16f2c914eedb', '早行', '早行', 'cd7788e3-949a-41be-8a14-0769ca1ccec6', '唐', '["早行星尚在，數里未天明。","不辨雲林色，空聞風水聲。","月從山上落，河入斗間橫。","漸至重門外，依稀見洛城。"]', '["早行星尚在，數里未天明。","不辨云林色，空闻风水声。","月從山上落，河入斗间橫。","漸至重门外，依稀见洛城。"]', '诗', 'shi', '', NULL, '早行 郭良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40dbb564-d86b-4616-882c-4dbbd9ac9335', '過故人舊宅', '過故人旧宅', '29b773b2-f9b2-43db-a6a1-bffc96f753db', '唐', '["故人軒騎罷歸來，舊宅園林閑不開。","唯餘挾瑟樓中婦，哭向平生歌舞臺。"]', '["故人軒騎罷归来，旧宅园林闲不开。","唯餘挾瑟楼中婦，哭向平生歌舞台。"]', '诗', 'shi', '', NULL, '過故人舊宅 王喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5a4ede4-70dc-4bb3-95ab-e113f83a0a85', '關山月', '关山月', '0822ab2a-0223-457d-a409-3eca678fbc76', '唐', '["玉塞抵長城，金徽暎高闕。","遙心萬餘里，直望三邊月。","霜靜影逾懸，露晞光漸沒。","思君不可見，空歎將焉歇。"]', '["玉塞抵长城，金徽暎高闕。","遙心万餘里，直望三邊月。","霜静影逾懸，露晞光漸沒。","思君不可见，空歎將焉歇。"]', '诗', 'shi', '', NULL, '關山月 徐九臯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f37ab92-d8ed-43f3-ba85-eff243e94cc9', '戰城南', '戰城南', '0822ab2a-0223-457d-a409-3eca678fbc76', '唐', '["塞北狂胡旅，城南敵漢圍。","巉巖一鼓氣，拔利五兵威。","虜騎瞻山哭，王師拓地飛。","不應須寵戰，當遂勒金徽。"]', '["塞北狂胡旅，城南敵漢圍。","巉巖一鼓氣，拔利五兵威。","虜騎瞻山哭，王師拓地飞。","不應須寵戰，當遂勒金徽。"]', '诗', 'shi', '', NULL, '戰城南 徐九臯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ab1c514-5415-4e59-9139-bf6b53c4ae54', '詠史', '詠史', '0822ab2a-0223-457d-a409-3eca678fbc76', '唐', '["亡國秦韓代，榮身劉項年。","金槌擊政後，玉斗碎增前。","聖主稱三傑，明離保四賢。","已申黃石祭，方慕赤松仙。"]', '["亡国秦韓代，榮身劉項年。","金槌擊政後，玉斗碎增前。","聖主稱三傑，明離保四賢。","已申黄石祭，方慕赤松仙。"]', '诗', 'shi', '', NULL, '詠史 徐九臯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8c23174-925f-4a29-8972-f182a6cfc7e6', '途中覽鏡', '途中覽镜', '0822ab2a-0223-457d-a409-3eca678fbc76', '唐', '["四海遊長倦，百年愁半侵。","賴窺明鏡裏，時見丈夫心。"]', '["四海游长倦，百年愁半侵。","賴窺明镜裏，时见丈夫心。"]', '诗', 'shi', '', NULL, '途中覽鏡 徐九臯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('618f5d33-d89f-4ada-9ed0-46e0ae1f0045', '送部四鎮人往單于別知故', '送部四鎮人往單于別知故', '0822ab2a-0223-457d-a409-3eca678fbc76', '唐', '["天下今無事，雲中獨未寧。","忝驅更戍卒，方遠送邊庭。","馬飲長城水，軍占太白星。","國恩行可報，何必守經營。"]', '["天下今無事，云中独未寧。","忝驱更戍卒，方远送邊庭。","马饮长城水，軍占太白星。","国恩行可報，何必守經營。"]', '诗', 'shi', '', NULL, '送部四鎮人往單于別知故 徐九臯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b15a6f1f-1730-49e2-8f50-a0a5f7e51e26', '松滋江北阻風', '松滋江北阻风', '4c0c5151-91d4-430d-b5e9-ccd42d97dd88', '唐', '["江風久未歇，山雨復相仍。","巨浪天涯起，餘寒川上凝。","憂人勞夕惕，鄉事憊晨興。","遠聽知音駭，誠哉不可陵。"]', '["江风久未歇，山雨复相仍。","巨浪天涯起，餘寒川上凝。","憂人勞夕惕，乡事憊晨兴。","远听知音駭，誠哉不可陵。"]', '诗', 'shi', '', NULL, '松滋江北阻風 閻寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a1d375c-cd38-43f0-beb5-2e5312d155e7', '曉入宜都渚', '晓入宜都渚', '4c0c5151-91d4-430d-b5e9-ccd42d97dd88', '唐', '["問俗周楚甸，川行眇江潯。","興隨曉光發，道會春言深。","回眺佳氣象，遠懷得山林。","佇應舟楫用，曷務歸閑心。"]', '["问俗周楚甸，川行眇江潯。","兴隨晓光發，道會春言深。","回眺佳氣象，远懷得山林。","佇應舟楫用，曷務归闲心。"]', '诗', 'shi', '', NULL, '曉入宜都渚 閻寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('745f033f-4e88-4bd1-beba-ad28de1e2e47', '古意', '古意', '4c0c5151-91d4-430d-b5e9-ccd42d97dd88', '唐', '["庭樹發華滋，瑤草復葳蕤。","好鳥飛相從，愁人深此時。","天中有靈匹，日夕嚬蛾眉。","願逐飄風花，千里入遙帷。","心逝愛不見，空歌悲莫悲。"]', '["庭樹發华滋，瑤草复葳蕤。","好鸟飞相從，愁人深此时。","天中有靈匹，日夕嚬蛾眉。","願逐飄风花，千里入遙帷。","心逝愛不见，空歌悲莫悲。"]', '诗', 'shi', '', NULL, '古意 閻寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24c9a5d0-71a0-4a42-98d5-7dab45839b1f', '春宵覽月', '春宵覽月', '4c0c5151-91d4-430d-b5e9-ccd42d97dd88', '唐', '["月生東荒外，天雲收夕陰。","愛見澄清景，象吾虛白心。","耳目靜無譁，神超道性深。","乘興得至樂，寓言因永吟。"]', '["月生东荒外，天云收夕陰。","愛见澄清景，象吾虛白心。","耳目静無譁，神超道性深。","乘兴得至乐，寓言因永吟。"]', '诗', 'shi', '', NULL, '春宵覽月 閻寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d2083db-5ccc-416b-be4c-375ef271acc0', '秋懷', '秋懷', '4c0c5151-91d4-430d-b5e9-ccd42d97dd88', '唐', '["下帷長日盡，虛館早涼生。","芳草猶未薦，如何蜻蛚鳴。","秋風已振衣，客去何時歸。","爲問當途者，寧知心有違。"]', '["下帷长日尽，虛館早涼生。","芳草猶未薦，如何蜻蛚鳴。","秋风已振衣，客去何时归。","爲问當途者，寧知心有違。"]', '诗', 'shi', '', NULL, '秋懷 閻寬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eb98284-b6e8-4232-acf1-47cc896293d1', '和中書侍郎院壁畫雲', '和中书侍郎院壁畫云', 'a5cc015f-9284-43ae-8bae-bf56d8454fc4', '唐', '["粉壁畫雲成，如能上太清。","影從霄漢發，光照掖垣明。","暎篠多幽趣，臨軒得野情。","獨思作霖雨，流潤及生靈。"]', '["粉壁畫云成，如能上太清。","影從霄漢發，光照掖垣明。","暎篠多幽趣，臨軒得野情。","独思作霖雨，流潤及生靈。"]', '诗', 'shi', '', NULL, '和中書侍郎院壁畫雲 李收 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2badd5e-3ef1-45e1-a80c-7a520b185952', '幽情', '幽情', 'a5cc015f-9284-43ae-8bae-bf56d8454fc4', '唐', '["幽人惜春暮，潭上折芳草。","佳期何時還，欲寄千里道。"]', '["幽人惜春暮，潭上折芳草。","佳期何时還，欲寄千里道。"]', '诗', 'shi', '', NULL, '幽情 李收 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c6094fa-74b2-4226-b42d-d06cc51fb646', '懷魯', '懷魯', 'ced62071-cc17-420e-a195-261b84358903', '唐', '["曲阜國，尼丘山。","周公邈難問，夫子猶啓關。","履風雩兮若見，游夏興兮魯顏。","天孫天孫，何爲今兮學且難，負星明而東遊閑閑。"]', '["曲阜国，尼丘山。","周公邈难问，夫子猶啓关。","履风雩兮若见，游夏兴兮魯顏。","天孫天孫，何爲今兮学且难，負星明而东游闲闲。"]', '诗', 'shi', '', NULL, '懷魯 程彌綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7715e2f7-4e7e-4794-942e-bfbad57f953d', '燕歌行', '燕歌行', '1f6ba682-264a-4f73-9660-a71d29205c33', '唐', '["君不見漁陽八月塞草腓，征人相對併思歸。","雲和朔氣連天黑，蓬雜驚沙散野飛。","是時天地陰埃遍，瀚海龍城皆習戰。","兩軍鼓角暗相聞，四面旌旗看不見。","昭君遠嫁已年多，戎狄無厭不復和。","漢兵候月秋防塞，胡騎乘冰夜渡河。","河塞東西萬餘里，地與京華不相似。","燕支山下少春暉，黃沙磧裏無流水。","金戈玉劍十年征，紅粉青樓多怨情。","厭向殊鄉久離別，秋來愁聽擣衣聲。"]', '["君不见漁陽八月塞草腓，征人相对併思归。","云和朔氣連天黑，蓬杂驚沙散野飞。","是时天地陰埃遍，瀚海龙城皆習戰。","兩軍鼓角暗相闻，四面旌旗看不见。","昭君远嫁已年多，戎狄無厭不复和。","漢兵候月秋防塞，胡騎乘冰夜渡河。","河塞东西万餘里，地與京华不相似。","燕支山下少春暉，黄沙磧裏無流水。","金戈玉劍十年征，紅粉青楼多怨情。","厭向殊乡久離別，秋来愁听擣衣声。"]', '诗', 'shi', '', NULL, '燕歌行 屈同仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8551389a-8251-4516-80e0-9247893493ca', '烏江女', '烏江女', '1f6ba682-264a-4f73-9660-a71d29205c33', '唐', '["越豔誰家女，朝遊江岸傍。","青春猶未嫁，紅粉舊來娼。","錦袖盛朱橘，銀鉤摘紫房。","見人羞不語，回艇入溪藏。"]', '["越豔誰家女，朝游江岸傍。","青春猶未嫁，紅粉旧来娼。","錦袖盛朱橘，銀鉤摘紫房。","见人羞不語，回艇入溪藏。"]', '诗', 'shi', '', NULL, '烏江女 屈同仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2b3aeca-a140-477f-bd2f-54a71f4353cd', '昌年宮之作', '昌年宮之作', '680cecb2-8459-491d-82d0-3af11329c8a9', '唐', '["但有離宮處，君王每不居。","旗門芳草合，輦路小槐疎。","殿閉山煙滿，窗凝野靄虛。","豐年多望幸，春色待鑾輿。"]', '["但有離宮处，君王每不居。","旗门芳草合，輦路小槐疎。","殿閉山煙满，窗凝野靄虛。","豐年多望幸，春色待鑾輿。"]', '诗', 'shi', '', NULL, '昌年宮之作 豆盧復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('215caa5f-74fc-4e81-af61-b8ba6c9a9ff0', '落第歸鄉留別長安主人', '落第归乡留別长安主人', '680cecb2-8459-491d-82d0-3af11329c8a9', '唐', '["客裏愁多不記春，聞鶯始歎柳條新。","年年下第東歸去，羞見長安舊主人。"]', '["客裏愁多不記春，闻鶯始歎柳條新。","年年下第东归去，羞见长安旧主人。"]', '诗', 'shi', '', NULL, '落第歸鄉留別長安主人 豆盧復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f558fbb7-b8d7-413b-bc61-fbafc0b99404', '奉試詠青', '奉試詠青', 'd093a429-c504-47f2-9312-f9da7eded1e8', '唐', '["路闢天光遠，春還月道臨。","草濃河畔色，槐結路邊陰。","未映君王史，先標胄子襟。","經明如可拾，自有致雲心。"]', '["路闢天光远，春還月道臨。","草濃河畔色，槐結路邊陰。","未映君王史，先標胄子襟。","經明如可拾，自有致云心。"]', '诗', 'shi', '', NULL, '奉試詠青 荆冬倩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b22bb0c9-e21c-40d4-8aaf-24d3bf78fc49', '觀漢水', '观漢水', 'd6e55832-f274-4838-a9f5-eb3b59e885e5', '唐', '["發源自嶓冢，東注經襄陽。","一道入溟渤，別流爲滄浪。","求思詠游女，投弔悲昭王。","水濱不可問，日暮空湯湯。"]', '["發源自嶓冢，东注經襄陽。","一道入溟渤，別流爲滄浪。","求思詠游女，投弔悲昭王。","水濱不可问，日暮空湯湯。"]', '诗', 'shi', '', NULL, '觀漢水 梁洽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2237386f-91db-4f62-9103-fec2c5791d81', '遊越溪', '游越溪', '97f15a88-8e57-40e8-8390-0885bc093839', '唐', '["溪水碧悠悠，猨聲斷客愁。","漁潭逢釣楫，月浦值孤舟。","訪泊隨煙火，迷途視斗牛。","今宵越鄉意，還取醉忘憂。"]', '["溪水碧悠悠，猨声斷客愁。","漁潭逢釣楫，月浦值孤舟。","訪泊隨煙火，迷途視斗牛。","今宵越乡意，還取醉忘憂。"]', '诗', 'shi', '', NULL, '遊越溪 鄭紹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19340af6-e25d-41c8-90fc-b465d9be1134', '登樓', '登楼', 'f6695e0e-a579-49ec-8c66-b8456a86027d', '唐', '["白日依山盡，黃河入海流。","欲窮千里目，更上一層樓。"]', '["白日依山尽，黄河入海流。","欲窮千里目，更上一層楼。"]', '诗', 'shi', '', NULL, '登樓 朱斌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12ae270e-cab4-4a34-b9a1-0aaa66c16f98', '感寓二首 一', '感寓二首 一', '612b8a33-bf23-4091-8faf-a6017537c9f2', '唐', '["彩雲呈瑞質，五色發人寰。","獨作龍虎狀，孤飛天地間。","隱隱臨北極，峨峨象南山。","恨在帝鄉外，不逢枝葉攀。"]', '["彩云呈瑞質，五色發人寰。","独作龙虎狀，孤飞天地间。","隐隐臨北極，峨峨象南山。","恨在帝乡外，不逢枝葉攀。"]', '诗', 'shi', '', NULL, '感寓二首 一 梁德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19d9cc0a-3c1b-4697-871d-f53f26660013', '感寓二首 二', '感寓二首 二', '612b8a33-bf23-4091-8faf-a6017537c9f2', '唐', '["幽澗生蕙若，幽渚老江蘺。","榮落人不見，芳香徒爾爲。","不及綠萍草，生君紅蓮池。","左右美人弄，朝夕春風吹。","葉洗玉泉水，珠清湛露滋。","心亦願如此，託君君不知。"]', '["幽澗生蕙若，幽渚老江蘺。","榮落人不见，芳香徒爾爲。","不及綠萍草，生君紅蓮池。","左右美人弄，朝夕春风吹。","葉洗玉泉水，珠清湛露滋。","心亦願如此，託君君不知。"]', '诗', 'shi', '', NULL, '感寓二首 二 梁德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c5837c9-6ef1-4c77-b669-77663144d23d', '詠談容娘', '詠談容娘', '5c18d032-0907-4909-8516-987eafb01514', '唐', '["舉手整花鈿，翻身舞錦筵。","馬圍行處匝，人壓看場圓。","歌要齊聲和，情教細語傳。","不知心大小，容得許多憐。"]', '["舉手整花鈿，翻身舞錦筵。","马圍行处匝，人壓看場圓。","歌要齊声和，情教細語傳。","不知心大小，容得許多怜。"]', '诗', 'shi', '', NULL, '詠談容娘 常非月 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82a5b213-a081-4aa3-9f2d-2f36a9313063', '覽史', '覽史', 'ce43a74d-4bab-4d61-8dda-c2cc0c645d67', '唐', '["享年八十已，歷數窮蒼生。","七虎門源上，咆哮關內鳴。","建都用鶉宿，設險因金城。","舜曲煙火起，汾河珠翠明。","海雲引天仗，朔雪留邊兵。","作孽人怨久，其亡鬼信盈。","素靈感劉季，白馬從子嬰。","昏虐不務德，百代無芳聲。"]', '["享年八十已，歷數窮蒼生。","七虎门源上，咆哮关內鳴。","建都用鶉宿，設險因金城。","舜曲煙火起，汾河珠翠明。","海云引天仗，朔雪留邊兵。","作孽人怨久，其亡鬼信盈。","素靈感劉季，白马從子嬰。","昏虐不務德，百代無芳声。"]', '诗', 'shi', '', NULL, '覽史 張良璞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('994e03a6-82ba-4093-a8f0-e13f2e784c19', '奉試冷井詩', '奉試冷井诗', 'a9d94cde-418e-4da2-bb61-aa7456d9c2ea', '唐', '["仙闈井初鑿，靈液沁成泉。","色湛青苔裏，寒凝紫綆邊。","銅瓶向影落，玉甃抱虛圓。","永願調神鼎，堯時泰萬年。"]', '["仙闈井初鑿，靈液沁成泉。","色湛青苔裏，寒凝紫綆邊。","銅瓶向影落，玉甃抱虛圓。","永願調神鼎，堯时泰万年。"]', '诗', 'shi', '', NULL, '奉試冷井詩 孫欣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8bc4775-9f20-4ede-b873-0c0138d9bdd0', '都中閑居', '都中闲居', '7d2b44c2-87af-46b5-bb26-fbc6cb31286d', '唐', '["君王巡海內，北闕下明臺。","雲物天中少，煙花歲後來。","河從御苑出，山向國門開。","寂寞東京裏，空留賈誼才。"]', '["君王巡海內，北闕下明台。","云物天中少，煙花歲後来。","河從御苑出，山向国门开。","寂寞东京裏，空留賈誼才。"]', '诗', 'shi', '', NULL, '都中閑居 王羨門 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bfd22e0-4623-4efc-9678-a4d436cde303', '江南弄', '江南弄', '761e00bd-bfba-4c2a-b27e-a6bebba88b3a', '唐', '["春江可憐事，最在美人家。","鸚鵡能言鳥，芙蓉巧笑花。","地銜金作埒，水抱玉爲沙。","薄晚青絲騎，長鞭赴狹斜。"]', '["春江可怜事，最在美人家。","鸚鵡能言鸟，芙蓉巧笑花。","地銜金作埒，水抱玉爲沙。","薄晚青絲騎，长鞭赴狹斜。"]', '诗', 'shi', '', NULL, '江南弄 芮挺章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c312e177-7bc0-4c6e-b9a6-ea31ebc32c39', '少年行', '少年行', '761e00bd-bfba-4c2a-b27e-a6bebba88b3a', '唐', '["任氣稱張放，銜恩在少年。","玉階朝就日，金屋夜升天。","軒騎青雲際，笙歌綠水邊。","建章明月好，留醉伴風煙。"]', '["任氣稱張放，銜恩在少年。","玉階朝就日，金屋夜升天。","軒騎青云際，笙歌綠水邊。","建章明月好，留醉伴风煙。"]', '诗', 'shi', '', NULL, '少年行 芮挺章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17e77a5c-a215-4d63-9f3a-c75c4c48187c', '伊水門', '伊水门', 'ba9e0e4d-b3e4-423b-b0e6-87e448fedef4', '唐', '["朝涉伊水門，伊水入門流。","愜心乃成興，澹然汎孤舟。","霏微傍青靄，容與隨白鷗。","竹陰交前浦，柳花媚中洲。","日落陰雲生，彌覺茲路幽。","聊以恣所適，此外知何求。"]', '["朝涉伊水门，伊水入门流。","愜心乃成兴，澹然汎孤舟。","霏微傍青靄，容與隨白鷗。","竹陰交前浦，柳花媚中洲。","日落陰云生，彌覺茲路幽。","聊以恣所適，此外知何求。"]', '诗', 'shi', '', NULL, '伊水門 樓頴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4d5874c-4eaf-4eec-ae81-15e1130e6fd4', '東郊納涼憶左威衛李錄事收昆季太原崔參軍三首 一', '东郊納涼憶左威衛李錄事收昆季太原崔參軍三首 一', 'ba9e0e4d-b3e4-423b-b0e6-87e448fedef4', '唐', '["水竹誰家宅，幽庭向苑門。","今知季倫沼，舊是辟疆園。","飢鷺窺魚靜，鳴鴉帶子喧。","興成秪自適，欲白返忘言。"]', '["水竹誰家宅，幽庭向苑门。","今知季倫沼，旧是辟疆园。","飢鷺窺鱼静，鳴鴉带子喧。","兴成秪自適，欲白返忘言。"]', '诗', 'shi', '', NULL, '東郊納涼憶左威衛李錄事收昆季太原崔參軍三首 一 樓頴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d69a74c-1dad-46c4-a6d8-78d56d12145d', '東郊納涼憶左威衛李錄事收昆季太原崔參軍三首 二', '东郊納涼憶左威衛李錄事收昆季太原崔參軍三首 二', 'ba9e0e4d-b3e4-423b-b0e6-87e448fedef4', '唐', '["納涼每選地，近得青門東。","林與繚垣接，池將沁水通。","枝交帝女樹，橋映美人虹。","想是忘機者，悠悠在興中。"]', '["納涼每選地，近得青门东。","林與繚垣接，池將沁水通。","枝交帝女樹，橋映美人虹。","想是忘機者，悠悠在兴中。"]', '诗', 'shi', '', NULL, '東郊納涼憶左威衛李錄事收昆季太原崔參軍三首 二 樓頴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43033c59-1b27-4769-9fee-3d2c3185ce1a', '東郊納涼憶左威衛李錄事收昆季太原崔參軍三首 三', '东郊納涼憶左威衛李錄事收昆季太原崔參軍三首 三', 'ba9e0e4d-b3e4-423b-b0e6-87e448fedef4', '唐', '["林間求適意，池上得清飆。","稍稍斜回檝，時時一度橋。","水光壁際動，山影浪中搖。","不見李元禮，神仙何處要。"]', '["林间求適意，池上得清飆。","稍稍斜回檝，时时一度橋。","水光壁際动，山影浪中搖。","不见李元禮，神仙何处要。"]', '诗', 'shi', '', NULL, '東郊納涼憶左威衛李錄事收昆季太原崔參軍三首 三 樓頴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79882b3c-9e56-4a56-a59e-96ee3cd33301', '西施石', '西施石', 'ba9e0e4d-b3e4-423b-b0e6-87e448fedef4', '唐', '["西施昔日浣紗津，石上青苔思殺人。","一去姑蘇不復返，岸旁桃李爲誰春。"]', '["西施昔日浣紗津，石上青苔思殺人。","一去姑蘇不复返，岸旁桃李爲誰春。"]', '诗', 'shi', '', NULL, '西施石 樓頴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0c0473c-b66b-47d3-aec2-8033fe7e2cce', '江南行', '江南行', '91c0da00-96e1-41ea-bd8c-b56887bfedce', '唐', '["楊柳青青鶯欲啼，風光搖蕩綠蘋齊，金陰城頭日色低。","日色低，情難極，水中鳧鷖雙比翼。"]', '["楊柳青青鶯欲啼，风光搖蕩綠蘋齊，金陰城头日色低。","日色低，情难極，水中鳧鷖雙比翼。"]', '诗', 'shi', '', NULL, '江南行 李康成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('935306d8-d08d-41f7-b8f0-cad379229322', '采蓮曲', '采蓮曲', '91c0da00-96e1-41ea-bd8c-b56887bfedce', '唐', '["采蓮去，月沒春江曙。","翠鈿紅袖水中央，青荷蓮子雜衣香，雲起風生歸路長。","歸路長，那得久。","各迴船，兩搖手。"]', '["采蓮去，月沒春江曙。","翠鈿紅袖水中央，青荷蓮子杂衣香，云起风生归路长。","归路长，那得久。","各迴船，兩搖手。"]', '诗', 'shi', '', NULL, '采蓮曲 李康成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76d53cae-3896-4d5a-a8ee-5594289c037a', '玉華仙子歌', '玉华仙子歌', '91c0da00-96e1-41ea-bd8c-b56887bfedce', '唐', '["紫陽仙子名玉華，珠盤承露餌丹砂。","轉態凝情五雲裏，嬌顏千歲芙蓉花。","紫陽綵女矜無數，遙見玉華皆掩嫭。","高堂初日不成妍，洛渚流風徒自憐。","璇階霓綺閣，碧題霜羅幕。","仙娥桂樹長自春，王母桃花未嘗落。","上元夫人賓上清，深宮寂歷厭層城。","解佩空憐鄭交甫，吹簫不逐許飛瓊。","溶溶紫庭步，渺渺瀛臺路。","蘭陵貴士謝相逢，濟北風生尚迴顧。","滄洲傲吏愛金丹，清心迴望雲之端。","羽蓋霓裳一相識，傳情寫念長無極。","長無極，永相隨。","攀霄歷金闕，弄影下瑤池。","夕宿紫府雲母帳，朝餐玄圃崑崙芝。","不學蘭香中道絕，却教青鳥報相思。"]', '["紫陽仙子名玉华，珠盤承露餌丹砂。","轉態凝情五云裏，嬌顏千歲芙蓉花。","紫陽綵女矜無數，遙见玉华皆掩嫭。","高堂初日不成妍，洛渚流风徒自怜。","璇階霓綺閣，碧題霜羅幕。","仙娥桂樹长自春，王母桃花未嘗落。","上元夫人賓上清，深宮寂歷厭層城。","解佩空怜鄭交甫，吹簫不逐許飞瓊。","溶溶紫庭步，渺渺瀛台路。","蘭陵貴士謝相逢，濟北风生尚迴顧。","滄洲傲吏愛金丹，清心迴望云之端。","羽蓋霓裳一相識，傳情寫念长無極。","长無極，永相隨。","攀霄歷金闕，弄影下瑤池。","夕宿紫府云母帳，朝餐玄圃崑崙芝。","不学蘭香中道絕，却教青鸟報相思。"]', '诗', 'shi', '', NULL, '玉華仙子歌 李康成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('157dde0c-9fb0-4ca2-8c33-6f412582c028', '自君之出矣', '自君之出矣', '91c0da00-96e1-41ea-bd8c-b56887bfedce', '唐', '["自君之出矣，弦吹絕無聲。","思君如百草，撩亂逐春生。"]', '["自君之出矣，弦吹絕無声。","思君如百草，撩亂逐春生。"]', '诗', 'shi', '', NULL, '自君之出矣 李康成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32e82de4-254a-41e6-a92f-2b2c676e9a1f', '句', '句', '91c0da00-96e1-41ea-bd8c-b56887bfedce', '唐', '["因緣苟會合，萬里猶同鄉。","運命尚不諧，隔壁無津梁。"]', '["因緣苟會合，万里猶同乡。","運命尚不諧，隔壁無津梁。"]', '诗', 'shi', '', NULL, '句 李康成 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c05348b3-0526-4cf9-b443-eb0aecf607b5', '時興', '时兴', '539b5fb7-4dbb-4075-b6b3-1e0faf7cd286', '唐', '["貴人昔未貴，咸願顧寒微。","及自登樞要，何曾問布衣。","平明登紫閣，日晏下彤闈。","擾擾路傍子，無勞歌是非。"]', '["貴人昔未貴，咸願顧寒微。","及自登樞要，何曾问布衣。","平明登紫閣，日晏下彤闈。","擾擾路傍子，無勞歌是非。"]', '诗', 'shi', '', NULL, '時興 楊賁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('612abeca-9d61-4454-8ba4-6e0b3e393cc9', '詠石季倫', '詠石季倫', '0d798201-d592-4b91-b4c8-899e9b85d9a5', '唐', '["金谷繁華石季倫，只能謀富不謀身。","當時縱與綠珠去，猶有無窮歌舞人。"]', '["金谷繁华石季倫，只能謀富不謀身。","當时縱與綠珠去，猶有無窮歌舞人。"]', '诗', 'shi', '', NULL, '詠石季倫 李清 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82664df2-6554-44d5-ad5c-fceffb3c45bc', '鶴警露', '鹤警露', '9d401b55-4d7a-4930-ac28-bca426b38447', '唐', '["南國商飆動，東臯野鶴鳴。","溪松寒暫宿，露草滴還驚。","欲有高飛意，空聞召侶情。","風間傳藻質，月下引清聲。","未假摶扶勢，焉知羽翼輕。","吾君開太液，願得應皇明。"]', '["南国商飆动，东臯野鹤鳴。","溪松寒暫宿，露草滴還驚。","欲有高飞意，空闻召侶情。","风间傳藻質，月下引清声。","未假摶扶勢，焉知羽翼轻。","吾君开太液，願得應皇明。"]', '诗', 'shi', '', NULL, '鶴警露 陳季 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df64caa8-cae5-4863-b8ce-d499357b1dab', '湘靈鼓瑟', '湘靈鼓瑟', '9d401b55-4d7a-4930-ac28-bca426b38447', '唐', '["神女泛瑤瑟，古祠嚴野亭。","楚雲來泱漭，湘水助清泠。","妙指微幽契，繁聲入杳冥。","一彈新月白，數曲暮山青。","調苦荆人怨，時遙帝子靈。","遺音如可賞，試奏爲君聽。"]', '["神女泛瑤瑟，古祠嚴野亭。","楚云来泱漭，湘水助清泠。","妙指微幽契，繁声入杳冥。","一彈新月白，數曲暮山青。","調苦荆人怨，时遙帝子靈。","遺音如可賞，試奏爲君听。"]', '诗', 'shi', '', NULL, '湘靈鼓瑟 陳季 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abf04401-d182-49d3-8f95-1731010abba7', '湘靈鼓瑟', '湘靈鼓瑟', 'd5245741-7298-44d1-9477-d97c6667298f', '唐', '["寶瑟和琴韻，靈妃應樂章。","依稀聞促柱，髣髴夢新妝。","波外聲初發，風前曲正長。","淒清和萬籟，斷續繞三湘。","轉覺雲山迥，空懷杜若芳。","誠能傳此意，雅奏在宮商。"]', '["寶瑟和琴韻，靈妃應乐章。","依稀闻促柱，髣髴梦新妝。","波外声初發，风前曲正长。","淒清和万籟，斷續繞三湘。","轉覺云山迥，空懷杜若芳。","誠能傳此意，雅奏在宮商。"]', '诗', 'shi', '', NULL, '湘靈鼓瑟 王邕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fcd37d1-dd53-4dd6-a562-45cd6b346dd6', '嵩山望幸', '嵩山望幸', 'd5245741-7298-44d1-9477-d97c6667298f', '唐', '["峻極位何崇，方知造化功。","降靈逢聖主，望幸表維嵩。","隱映連青壁，嵯峨向碧空。","象車因叶瑞，龍駕願升中。","萬歲聲長在，千巖氣轉雄。","東都歌盛事，西笑佇皇風。"]', '["峻極位何崇，方知造化功。","降靈逢聖主，望幸表維嵩。","隐映連青壁，嵯峨向碧空。","象车因叶瑞，龙駕願升中。","万歲声长在，千巖氣轉雄。","东都歌盛事，西笑佇皇风。"]', '诗', 'shi', '', NULL, '嵩山望幸 王邕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bd56fd4-dab6-4485-b48f-0333a6f4e4bc', '湘靈鼓瑟', '湘靈鼓瑟', '70960c8a-4b9a-4023-ac67-189f315431e8', '唐', '["帝子鳴金瑟，餘聲自抑揚。","悲風絲上斷，流水曲中長。","出沒遊魚聽，逶迤彩鳳翔。","微音時扣徵，雅韻乍含商。","神理誠難測，幽情詎可量。","至今聞古調，應恨滯三湘。"]', '["帝子鳴金瑟，餘声自抑揚。","悲风絲上斷，流水曲中长。","出沒游鱼听，逶迤彩鳳翔。","微音时扣徵，雅韻乍含商。","神理誠难測，幽情詎可量。","至今闻古調，應恨滯三湘。"]', '诗', 'shi', '', NULL, '湘靈鼓瑟 莊若訥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('799e398b-266a-474f-a861-cdcacae127a2', '湘靈鼓瑟', '湘靈鼓瑟', '24095c62-7ee4-456b-98e9-2fd5df842554', '唐', '["瑤瑟多哀怨，朱弦且莫聽。","扁舟三楚客，藂竹二妃靈。","淅瀝聞餘響，依稀欲辨形。","柱間寒水碧，曲裏暮山青。","良馬悲銜草，遊魚思繞萍。","知音若相遇，終不滯南溟。"]', '["瑤瑟多哀怨，朱弦且莫听。","扁舟三楚客，藂竹二妃靈。","淅瀝闻餘响，依稀欲辨形。","柱间寒水碧，曲裏暮山青。","良马悲銜草，游鱼思繞萍。","知音若相遇，終不滯南溟。"]', '诗', 'shi', '', NULL, '湘靈鼓瑟 魏璀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d17d86c-b052-4a60-be76-3015ea8d1e8b', '懷素上人草書歌', '懷素上人草书歌', '3bd25804-cb1a-4abf-af44-7a100dd3b2f6', '唐', '["衡陽雙峽插天峻，青壁巉巉萬餘仞。","此中靈秀衆所知，草書獨有懷素奇。","懷素身長五尺四，嚼湯誦呪吁可畏。","銅瓶錫杖倚閑庭，斑管秋毫多逸意。","或粉壁，或綵牋，蒲葵絹素何相鮮。","忽作風馳如電掣，更點飛花兼散雪。","寒猨飲水撼枯藤，壯士拔山伸勁鐵。","君不見張芝昔日稱獨賢，君不見近日張旭爲老顛。","二公絕藝人所惜，懷素傳之得真跡。","崢嶸蹙出海上山，突兀狀成湖畔石。","一縱又一橫，一欹又一傾。","臨江不羨飛帆勢，下筆長爲驟雨聲。","我牧此州喜相識，又見草書多慧力。","懷素懷素不可得，開卷臨池轉相憶。"]', '["衡陽雙峽插天峻，青壁巉巉万餘仞。","此中靈秀衆所知，草书独有懷素奇。","懷素身长五尺四，嚼湯誦呪吁可畏。","銅瓶錫杖倚闲庭，斑管秋毫多逸意。","或粉壁，或綵牋，蒲葵絹素何相鲜。","忽作风驰如電掣，更点飞花兼散雪。","寒猨饮水撼枯藤，壯士拔山伸勁鐵。","君不见張芝昔日稱独賢，君不见近日張旭爲老顛。","二公絕藝人所惜，懷素傳之得真跡。","崢嶸蹙出海上山，突兀狀成湖畔石。","一縱又一橫，一欹又一傾。","臨江不羨飞帆勢，下笔长爲驟雨声。","我牧此州喜相識，又见草书多慧力。","懷素懷素不可得，开卷臨池轉相憶。"]', '诗', 'shi', '', NULL, '懷素上人草書歌 王𩔪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c269dec4-e6e7-40b3-b1c5-b371d0450eb0', '懷素上人草書歌', '懷素上人草书歌', 'efdd44dd-30a5-4bc2-8da8-888d3cf8af7b', '唐', '["狂僧揮翰狂且逸，獨任天機摧格律。","龍虎慚因點畫生，雷霆却避鋒鋩疾。","魚牋娟素豈不貴，只嫌局促兒童戲。","粉壁長廊數十間，興來小豁胸襟氣。","長幼集，賢豪至，枕糟藉麴猶半醉。","忽然絕叫三五聲，滿壁縱橫千萬字。","吳興張老爾莫顛，葉縣公孫我何謂。","如熊如羆不足比，如虺如蛇不足擬。","涵物爲動鬼神泣，狂風入林花亂起。","殊形怪狀不易說，就中驚燥尤枯絕。","邊風殺氣同慘烈，崩槎臥木爭摧折。","塞草遙飛大漠霜，胡天亂下陰山雪。","偏看能事轉新奇，郡守王公同賦詩。","枯藤勁鐵媿三舍，驟雨寒猨驚一時。","此生絕藝人莫測，假此常爲護持力。","連城之璧不可量，五百年知草聖當。"]', '["狂僧揮翰狂且逸，独任天機摧格律。","龙虎慚因点畫生，雷霆却避鋒鋩疾。","鱼牋娟素豈不貴，只嫌局促兒童戲。","粉壁长廊數十间，兴来小豁胸襟氣。","长幼集，賢豪至，枕糟藉麴猶半醉。","忽然絕叫三五声，满壁縱橫千万字。","吳兴張老爾莫顛，葉縣公孫我何謂。","如熊如羆不足比，如虺如蛇不足擬。","涵物爲动鬼神泣，狂风入林花亂起。","殊形怪狀不易说，就中驚燥尤枯絕。","邊风殺氣同慘烈，崩槎臥木爭摧折。","塞草遙飞大漠霜，胡天亂下陰山雪。","偏看能事轉新奇，郡守王公同賦诗。","枯藤勁鐵媿三舍，驟雨寒猨驚一时。","此生絕藝人莫測，假此常爲護持力。","連城之璧不可量，五百年知草聖當。"]', '诗', 'shi', '', NULL, '懷素上人草書歌 竇冀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39bc54b3-62f5-49f3-8629-bcd6fe2026ff', '懷素上人草書歌', '懷素上人草书歌', '9a10d0b2-e0c6-47b8-854b-129f6641032e', '唐', '["吾觀文士多利用，筆精墨妙誠堪重。","身上藝能無不通，就中草聖最天縱。","有時興酣發神機，抽毫點墨縱橫揮。","風聲吼烈隨手起，龍蛇迸落空壁飛。","連拂數行勢不絕，藤懸查蹙生奇節。","劃然放縱驚雲濤，或時頓挫縈豪髮。","自言轉腕無所拘，大笑羲之用陣圖。","狂來紙盡勢不盡，投筆抗聲連叫呼。","信知鬼神助此道，墨池未盡書已好。","行路談君口不容，滿堂觀者空絕倒。","所恨時人多笑聲，唯知賤實翻貴名。","觀爾向來三五字，顛奇何謝張先生。"]', '["吾观文士多利用，笔精墨妙誠堪重。","身上藝能無不通，就中草聖最天縱。","有时兴酣發神機，抽毫点墨縱橫揮。","风声吼烈隨手起，龙蛇迸落空壁飞。","連拂數行勢不絕，藤懸查蹙生奇節。","劃然放縱驚云濤，或时頓挫縈豪髮。","自言轉腕無所拘，大笑羲之用陣圖。","狂来紙尽勢不尽，投笔抗声連叫呼。","信知鬼神助此道，墨池未尽书已好。","行路談君口不容，满堂观者空絕倒。","所恨时人多笑声，唯知賤實翻貴名。","观爾向来三五字，顛奇何謝張先生。"]', '诗', 'shi', '', NULL, '懷素上人草書歌 魯收 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2365ddee-8124-44e2-ac84-53e8c677b8a9', '懷素上人草書歌', '懷素上人草书歌', '072c493e-3116-4160-8a99-a93bd54889ae', '唐', '["幾年出家通宿命，一朝却憶臨池聖。","轉腕摧鋒增崛崎，秋毫繭紙常相隨。","衡陽客舍來相訪，連飲百杯神轉王。","忽聞風裏度飛泉，紙落紛紛如跕鳶。","形容脫略真如助，心思周游在何處。","筆下惟看激電流，字成只畏盤龍去。","怪狀崩騰若轉蓬，飛絲歷亂如迴風。","長松老死倚雲壁，蹙浪相翻驚海鴻。","于今年少尚如此，歷覩遠代無倫比。","妙絕當動鬼神泣，崔蔡幽魂更心死。"]', '["幾年出家通宿命，一朝却憶臨池聖。","轉腕摧鋒增崛崎，秋毫繭紙常相隨。","衡陽客舍来相訪，連饮百杯神轉王。","忽闻风裏度飞泉，紙落紛紛如跕鳶。","形容脫略真如助，心思周游在何处。","笔下惟看激電流，字成只畏盤龙去。","怪狀崩腾若轉蓬，飞絲歷亂如迴风。","长松老死倚云壁，蹙浪相翻驚海鴻。","于今年少尚如此，歷覩远代無倫比。","妙絕當动鬼神泣，崔蔡幽魂更心死。"]', '诗', 'shi', '', NULL, '懷素上人草書歌 朱逵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b63bb31-0c8a-4643-af5a-b393c1c9c4d4', '題懷素上人草書', '題懷素上人草书', '48d24c54-554c-40a4-967f-9af992c198d2', '唐', '["志在新奇無定則，古瘦灕纚半無墨。","醉來信手兩三行，醒後却書書不得。"]', '["志在新奇無定則，古瘦灕纚半無墨。","醉来信手兩三行，醒後却书书不得。"]', '诗', 'shi', '', NULL, '題懷素上人草書 許瑤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28b2515e-49c3-49f9-8702-d7b63a8136f4', '祀風師樂章 迎神', '祀风師乐章 迎神', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["太皞御氣，句芒肇功。","蒼龍青旗，爰候祥風。","律以和應，神以感通。","鼎俎脩蠁，時惟禮崇。"]', '["太皞御氣，句芒肇功。","蒼龙青旗，爰候祥风。","律以和應，神以感通。","鼎俎脩蠁，时惟禮崇。"]', '诗', 'shi', '', NULL, '祀風師樂章 迎神 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb26e2fd-fd49-4ebe-a774-2c01ad17fa90', '祀風師樂章 奠幣登歌', '祀风師乐章 奠幣登歌', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["旨酒告潔，青蘋應候。","禮陳瑤幣，樂獻金奏。","彈弦自昔，解凍惟舊。","仰瞻肸蠁，羣祥來湊。"]', '["旨酒告潔，青蘋應候。","禮陳瑤幣，乐獻金奏。","彈弦自昔，解凍惟旧。","仰瞻肸蠁，羣祥来湊。"]', '诗', 'shi', '', NULL, '祀風師樂章 奠幣登歌 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6a27558-dde1-4b22-b245-664a2bf49a29', '祀風師樂章 迎俎酌獻', '祀风師乐章 迎俎酌獻', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["德盛昭臨，迎拜巽方。","爰候發生，式薦馨香。","酌醴具舉，工歌再揚。","神歆入律，恩降百祥。"]', '["德盛昭臨，迎拜巽方。","爰候發生，式薦馨香。","酌醴具舉，工歌再揚。","神歆入律，恩降百祥。"]', '诗', 'shi', '', NULL, '祀風師樂章 迎俎酌獻 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28e9732b-57cd-451d-b6f1-80004f369685', '祀風師樂章 亞獻終獻', '祀风師乐章 亞獻終獻', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["膋薌備，玉帛陳。","風動物，樂感神。","三獻終，百神臻。","草木榮，天下春。"]', '["膋薌備，玉帛陳。","风动物，乐感神。","三獻終，百神臻。","草木榮，天下春。"]', '诗', 'shi', '', NULL, '祀風師樂章 亞獻終獻 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43745683-136f-47c7-9e3c-0bdba015e213', '祀風師樂章 送神', '祀风師乐章 送神', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["微穆敷華能應節，飄揚發彩宜行慶。","送迎靈駕神心饗，跪拜靈壇禮容盛。","氣和草木發萌芽，德暢禽魚遂翔泳。","永望翠蓋逐流雲，自茲率土調春令。"]', '["微穆敷华能應節，飄揚發彩宜行慶。","送迎靈駕神心饗，跪拜靈壇禮容盛。","氣和草木發萌芽，德暢禽鱼遂翔泳。","永望翠蓋逐流云，自茲率土調春令。"]', '诗', 'shi', '', NULL, '祀風師樂章 送神 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('100d48d7-777e-48a5-8a24-437bbb9aad06', '祀雨師樂章 迎神', '祀雨師乐章 迎神', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["陟降左右，誠達幽圓。","作解之功，樂惟有年。","雲軿戾止，灑霧飄煙。","惟馨展禮，爰列豆籩。"]', '["陟降左右，誠達幽圓。","作解之功，乐惟有年。","云軿戾止，灑霧飄煙。","惟馨展禮，爰列豆籩。"]', '诗', 'shi', '', NULL, '祀雨師樂章 迎神 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfe6bbaa-2b5f-4aed-94a1-b23a41960a48', '祀雨師樂章 奠幣登歌', '祀雨師乐章 奠幣登歌', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["歲正朱明，禮布玄制。","惟樂能感，與神合契。","陰霧離披，靈馭搖裔。","膏澤之慶，期於稔歲。"]', '["歲正朱明，禮布玄制。","惟乐能感，與神合契。","陰霧離披，靈馭搖裔。","膏澤之慶，期於稔歲。"]', '诗', 'shi', '', NULL, '祀雨師樂章 奠幣登歌 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a97b3c58-cbd4-419d-a959-8b4c3beeb3ad', '祀雨師樂章 迎俎酌獻', '祀雨師乐章 迎俎酌獻', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["陽開幽蟄，躬奉鬱鬯。","禮備節應，震來靈降。","動植求聲，飛沈允望。","時康氣茂，惟神之貺。"]', '["陽开幽蟄，躬奉鬱鬯。","禮備節應，震来靈降。","动植求声，飞沈允望。","时康氣茂，惟神之貺。"]', '诗', 'shi', '', NULL, '祀雨師樂章 迎俎酌獻 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d09d1609-8bf2-4982-82e3-83cce2ef2a91', '祀雨師樂章 亞獻終獻', '祀雨師乐章 亞獻終獻', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["奠既備，獻將終。","神行令，瑞飛空。","迎乾德，祈歲功。","乘煙燎，儼從風。"]', '["奠既備，獻將終。","神行令，瑞飞空。","迎乾德，祈歲功。","乘煙燎，儼從风。"]', '诗', 'shi', '', NULL, '祀雨師樂章 亞獻終獻 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44e3940f-60cb-4554-a34f-44c4e20939b5', '祀雨師樂章 送神', '祀雨師乐章 送神', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["整駕升車望寥廓，垂陰薦祉蕩昏氛。","饗時靈貺僾如在，樂罷餘聲遙可聞。","飲福陳誠禮容備，撤俎終獻曙光分。","跪拜臨壇結空想，年年應節候油雲。"]', '["整駕升车望寥廓，垂陰薦祉蕩昏氛。","饗时靈貺僾如在，乐罷餘声遙可闻。","饮福陳誠禮容備，撤俎終獻曙光分。","跪拜臨壇結空想，年年應節候油云。"]', '诗', 'shi', '', NULL, '祀雨師樂章 送神 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3701a25a-98c8-4ff3-bfa5-1118d77f8800', '答竇援遺臥病見寄', '答竇援遺臥病见寄', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["今春扶病移滄海，幾度承恩對白花。","送客屢聞簾外鵲，銷愁已辨酒中虵。","瓶開枸杞懸泉水，鼎鍊芙蓉伏火砂。","誤入塵埃牽吏役，羞將簿領到君家。"]', '["今春扶病移滄海，幾度承恩对白花。","送客屢闻簾外鵲，銷愁已辨酒中虵。","瓶开枸杞懸泉水，鼎鍊芙蓉伏火砂。","誤入塵埃牽吏役，羞將簿領到君家。"]', '诗', 'shi', '', NULL, '答竇援遺臥病見寄 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28880f73-8de2-43d1-8e5d-648dee798338', '對酒贈故人', '对酒贈故人', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["扶起離披菊，霜輕喜重開。","醉中驚老去，笑裏覺愁來。","月送人無盡，風吹浪不回。","感時將有寄，詩思澀難裁。"]', '["扶起離披菊，霜轻喜重开。","醉中驚老去，笑裏覺愁来。","月送人無尽，风吹浪不回。","感时將有寄，诗思澀难裁。"]', '诗', 'shi', '', NULL, '對酒贈故人 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2f6d5f6-85d3-4363-ae06-f7c437690049', '同李吏部伏日口號呈元庶子路中丞', '同李吏部伏日口號呈元庶子路中丞', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["火炎逢六月，金伏過三庚。","幾度衣裳汗，誰家枕簟清。","頒冰無下位，裁扇有高名。","吏部還開甕，殷勤二客情。"]', '["火炎逢六月，金伏過三庚。","幾度衣裳汗，誰家枕簟清。","頒冰無下位，裁扇有高名。","吏部還开甕，殷勤二客情。"]', '诗', 'shi', '', NULL, '同李吏部伏日口號呈元庶子路中丞 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa21adbe-1de4-40d0-888d-38ebbe473d3a', '嶺下臥疾寄劉長卿員外', '嶺下臥疾寄劉长卿員外', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["唯有貧兼病，能令親愛疎。","歲時供放逐，身世付空虛。","脛弱秋添絮，頭風曉廢梳。","波瀾喧衆口，藜藿靜吾廬。","喪馬思開卦，占鴞嬾發書。","十年江海隔，離恨子知予。"]', '["唯有貧兼病，能令親愛疎。","歲时供放逐，身世付空虛。","脛弱秋添絮，头风晓廢梳。","波瀾喧衆口，藜藿静吾廬。","喪马思开卦，占鴞嬾發书。","十年江海隔，離恨子知予。"]', '诗', 'shi', '', NULL, '嶺下臥疾寄劉長卿員外 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b7c07da-1c88-4ce4-8576-fd922f78d183', '戲題諸判官廳壁', '戲題諸判官廳壁', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["六十老翁無所取，二三君子不相遺。","願留今日交歡意，直到隳官謝病時。"]', '["六十老翁無所取，二三君子不相遺。","願留今日交歡意，直到隳官謝病时。"]', '诗', 'shi', '', NULL, '戲題諸判官廳壁 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd892edd-f7b3-4d5c-bacc-8b1a02a0564a', '酬兵部李侍郎晚過東廳之作', '酬兵部李侍郎晚過东廳之作', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["酒禮慙先祭，刑書已曠官。","詔馳黃紙速，身在絳紗安。","聖位登堂靜，生徒跪席寒。","庭槐暫搖落，幸爲入春看。"]', '["酒禮慙先祭，刑书已曠官。","詔驰黄紙速，身在絳紗安。","聖位登堂静，生徒跪席寒。","庭槐暫搖落，幸爲入春看。"]', '诗', 'shi', '', NULL, '酬兵部李侍郎晚過東廳之作 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bfe6521-bb53-46ae-af7c-2339309f0605', '昭德皇后挽歌詞', '昭德皇后挽歌词', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["西汜馳暉過，東園別路長。","歲華唯隴柏，春事罷公桑。","龜兆開泉戶，禽巢閉畫梁。","更聞哀禮過，明詔制心喪。"]', '["西汜驰暉過，东园別路长。","歲华唯隴柏，春事罷公桑。","龟兆开泉戶，禽巢閉畫梁。","更闻哀禮過，明詔制心喪。"]', '诗', 'shi', '', NULL, '昭德皇后挽歌詞 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dff0f52-aa3a-4933-ad04-39145433b715', '秋日過徐氏園林', '秋日過徐氏园林', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["回塘分越水，古樹積吳煙。","掃竹催鋪席，垂蘿待繫船。","鳥窺新罅栗，龜上半攲蓮。","屢入忘歸地，長嗟俗事牽。"]', '["回塘分越水，古樹積吳煙。","掃竹催鋪席，垂蘿待繫船。","鸟窺新罅栗，龟上半攲蓮。","屢入忘归地，长嗟俗事牽。"]', '诗', 'shi', '', NULL, '秋日過徐氏園林 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e1e3697-9fad-4ec7-9c4e-4bc4b8bb90f3', '雙山過信公所居', '雙山過信公所居', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["遙禮前朝塔，微聞後夜鐘。","人間第四祖，雲裏一雙峰。","積雨封苔徑，多年亞石松。","傳心不傳法，誰可繼高蹤。"]', '["遙禮前朝塔，微闻後夜鐘。","人间第四祖，云裏一雙峰。","積雨封苔徑，多年亞石松。","傳心不傳法，誰可繼高蹤。"]', '诗', 'shi', '', NULL, '雙山過信公所居 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c46b6815-891b-4b37-8fd1-533c6b1c31a2', '尚書宗兄使過詩以奉獻', '尚书宗兄使過诗以奉獻', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["洛下交親滿，歸閑意有餘。","翻嫌舊坐宅，却駕所懸車。","腹飽山僧供，頭輕侍婢梳。","上官唯揖讓，半祿代耕鉏。","雨散三秋別，風傳一字書。","勝遊如可繼，還欲並園廬。"]', '["洛下交親满，归闲意有餘。","翻嫌旧坐宅，却駕所懸车。","腹飽山僧供，头轻侍婢梳。","上官唯揖讓，半祿代耕鉏。","雨散三秋別，风傳一字书。","勝游如可繼，還欲並园廬。"]', '诗', 'shi', '', NULL, '尚書宗兄使過詩以奉獻 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0879b3a8-9a54-4a34-9746-c2490ef2497e', '抱疾謝李吏部贈訶黎勒葉', '抱疾謝李吏部贈訶黎勒葉', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["一葉生西徼，齎來上海查。","歲時經水府，根本別天涯。","方士真難見，商胡輒自誇。","此香同異域，看色勝仙家。","茗飲暫調氣，梧丸喜伐邪。","幸蒙祛老疾，深願駐韶華。"]', '["一葉生西徼，齎来上海查。","歲时經水府，根本別天涯。","方士真难见，商胡輒自誇。","此香同異域，看色勝仙家。","茗饮暫調氣，梧丸喜伐邪。","幸蒙祛老疾，深願駐韶华。"]', '诗', 'shi', '', NULL, '抱疾謝李吏部贈訶黎勒葉 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23ecc4c8-9ab8-4d67-a68c-1d2f0e57f0ff', '奉和柳相公中書言懷', '奉和柳相公中书言懷', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["運籌時所貴，前席禮偏深。","羸駕歸貧宅，攲冠出禁林。","鳳巢方得地，牛喘最關心。","雅望期三入，東山未可尋。"]', '["運籌时所貴，前席禮偏深。","羸駕归貧宅，攲冠出禁林。","鳳巢方得地，牛喘最关心。","雅望期三入，东山未可尋。"]', '诗', 'shi', '', NULL, '奉和柳相公中書言懷 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b39dc82-798d-44db-8452-bf8e17e7d343', '客自江南話過亡友朱司議故宅', '客自江南話過亡友朱司議故宅', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["交臂多相共，風流憶此人。","海翻移里巷，書蠹積埃塵。","奉佛棲禪久，辭官上疏頻。","故來分半宅，惟是舊交親。"]', '["交臂多相共，风流憶此人。","海翻移里巷，书蠹積埃塵。","奉佛棲禪久，辞官上疏頻。","故来分半宅，惟是旧交親。"]', '诗', 'shi', '', NULL, '客自江南話過亡友朱司議故宅 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2250742-d493-44e6-9035-33a91c1b5162', '酬于侍郎湖南見寄十四韻', '酬于侍郎湖南见寄十四韻', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["桂嶺千崖斷，湘流一派通。","長沙今賈傅，東海舊于公。","章甫經殊俗，離騷繼雅風。","金閨文作字，玉匣氣成虹。","翰墨時招侶，丹青夙在公。","主恩留左掖，人望積南宮。","巧拙循名異，浮沈顧位同。","九遷歸上略，三已契愚衷。","責謝庭中吏，悲寬塞上翁。","楚材欣有適，燕石愧無功。","山曉重嵐外，林春苦霧中。","雪花翻海鶴，波影倒江楓。","去札頻逢信，回帆早挂空。","避賢方有日，非敢愛微躬。"]', '["桂嶺千崖斷，湘流一派通。","长沙今賈傅，东海旧于公。","章甫經殊俗，離騷繼雅风。","金閨文作字，玉匣氣成虹。","翰墨时招侶，丹青夙在公。","主恩留左掖，人望積南宮。","巧拙循名異，浮沈顧位同。","九遷归上略，三已契愚衷。","責謝庭中吏，悲寬塞上翁。","楚材欣有適，燕石愧無功。","山晓重嵐外，林春苦霧中。","雪花翻海鹤，波影倒江楓。","去札頻逢信，回帆早挂空。","避賢方有日，非敢愛微躬。"]', '诗', 'shi', '', NULL, '酬于侍郎湖南見寄十四韻 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9bf081f-19e0-4276-bfae-1331b732a6d3', '朝拜元陵', '朝拜元陵', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["宮前石馬對中峰，雲裏金鋪閉幾重。","不見露盤迎曉日，唯聞木斧扣寒松。"]', '["宮前石马对中峰，云裏金鋪閉幾重。","不见露盤迎晓日，唯闻木斧扣寒松。"]', '诗', 'shi', '', NULL, '朝拜元陵 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0e238eb-b1b5-4edb-820b-e5cc8b6481e1', '發襄陽後却寄公安人', '發襄陽後却寄公安人', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["揮淚送迴人，將書報所親。","晚年多疾病，中路有風塵。","王粲頻徵楚，君恩許入秦。","還同星火去，馬上別江春。"]', '["揮泪送迴人，將书報所親。","晚年多疾病，中路有风塵。","王粲頻徵楚，君恩許入秦。","還同星火去，马上別江春。"]', '诗', 'shi', '', NULL, '發襄陽後却寄公安人 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12cabe5b-f212-401c-bcd7-fc940a5870b6', '立春後休沐', '立春後休沐', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["心與青春背，新年亦掩扉。","漸窮無相學，惟避不材譏。","積病攻難愈，銜恩報轉微。","定知書課日，優詔許辭歸。"]', '["心與青春背，新年亦掩扉。","漸窮無相学，惟避不材譏。","積病攻难愈，銜恩報轉微。","定知书課日，優詔許辞归。"]', '诗', 'shi', '', NULL, '立春後休沐 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feb085bc-e461-4a18-b787-e831e3ef1885', '宿廬山贈白鶴觀劉尊師', '宿廬山贈白鹤观劉尊師', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["蒼蒼五老霧中壇，杳杳三山洞裏官。","手護崑崙象牙簡，心推霹靂棗枝盤。","春飛雪粉如毫潤，曉漱瓊膏冰齒寒。","漸恨流年筋力少，惟思露冕事星冠。"]', '["蒼蒼五老霧中壇，杳杳三山洞裏官。","手護崑崙象牙簡，心推霹靂棗枝盤。","春飞雪粉如毫潤，晓漱瓊膏冰齒寒。","漸恨流年筋力少，惟思露冕事星冠。"]', '诗', 'shi', '', NULL, '宿廬山贈白鶴觀劉尊師 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b59b031-7cee-4c88-8023-1b0b04a9da60', '觀壁盧九想圖', '观壁盧九想圖', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["一世榮枯無異同，百年哀樂又歸空。","夜闌鳥鵲相爭處，林下真僧在定中。"]', '["一世榮枯無異同，百年哀乐又归空。","夜闌鸟鵲相爭处，林下真僧在定中。"]', '诗', 'shi', '', NULL, '觀壁盧九想圖 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d7b4fc4-62ae-48e7-a486-a8ff73caaf7d', '送日本國聘賀使晁巨卿東歸', '送日本国聘賀使晁巨卿东归', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["上才生下國，東海是西鄰。","九譯蕃君使，千年聖主臣。","野情偏得禮，木性本含真。","錦帆乘風轉，金裝照地新。","孤城開蜃閣，曉日上朱輪。","早識來朝歲，塗山玉帛均。"]', '["上才生下国，东海是西鄰。","九譯蕃君使，千年聖主臣。","野情偏得禮，木性本含真。","錦帆乘风轉，金裝照地新。","孤城开蜃閣，晓日上朱輪。","早識来朝歲，塗山玉帛均。"]', '诗', 'shi', '', NULL, '送日本國聘賀使晁巨卿東歸 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7da2608c-26ec-44e8-a87b-2ba1aa566724', '顧著作宅賦詩', '顧著作宅賦诗', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["幾年江海煙霞，乘醉一到京華。","已覺不嫌羊酪，誰能長守兔罝。","脫巾偏招相國，逢竹便認吾家。","各在芸臺閣裏，煩君日日登車。"]', '["幾年江海煙霞，乘醉一到京华。","已覺不嫌羊酪，誰能长守兔罝。","脫巾偏招相国，逢竹便認吾家。","各在芸台閣裏，煩君日日登车。"]', '诗', 'shi', '', NULL, '顧著作宅賦詩 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6360ff09-9f22-4d4e-87bf-301394732d34', '近獲風痺之疾題寄所懷', '近獲风痺之疾題寄所懷', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["病夫將已矣，無可答君恩。","衾枕同羇客，圖書委外孫。","久來從吏道，常欲奉空門。","疾走機先息，攲行力漸煩。","無醫能却老，有變是游魂。","鳥宿還依伴，蓬飄莫問根。","寓形齊指馬，觀境制心猨。","唯借南榮地，清晨暫負喧。"]', '["病夫將已矣，無可答君恩。","衾枕同羇客，圖书委外孫。","久来從吏道，常欲奉空门。","疾走機先息，攲行力漸煩。","無醫能却老，有变是游魂。","鸟宿還依伴，蓬飄莫问根。","寓形齊指马，观境制心猨。","唯借南榮地，清晨暫負喧。"]', '诗', 'shi', '', NULL, '近獲風痺之疾題寄所懷 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42864ab0-426d-435d-b6e9-81a45a5f225d', '奉和常閣老晚秋集賢院即事寄贈徐薛二侍郎', '奉和常閣老晚秋集賢院即事寄贈徐薛二侍郎', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["祕殿掖垣西，書樓苑樹齊。","秋煙凝縹帙，曉色上璇題。","門接承明近，池連太液低。","疎鐘文馬駐，繁葉綵禽栖。","職美綸江綍，榮深組及珪。","九霄偏眷顧，三事早提攜。","對案臨青玉，窺書捧紫泥。","始歡新遇重，還惜舊遊暌。","左宦登吳岫，分家渡越溪。","賦中頻歎鵩，卜處幾聽雞。","望闕應多戀，臨津不用迷。","柏梁思和曲，朝夕候金閨。"]', '["祕殿掖垣西，书楼苑樹齊。","秋煙凝縹帙，晓色上璇題。","门接承明近，池連太液低。","疎鐘文马駐，繁葉綵禽栖。","職美綸江綍，榮深組及珪。","九霄偏眷顧，三事早提携。","对案臨青玉，窺书捧紫泥。","始歡新遇重，還惜旧游暌。","左宦登吳岫，分家渡越溪。","賦中頻歎鵩，卜处幾听雞。","望闕應多戀，臨津不用迷。","柏梁思和曲，朝夕候金閨。"]', '诗', 'shi', '', NULL, '奉和常閣老晚秋集賢院即事寄贈徐薛二侍郎 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c55e35df-d9e5-49a2-a088-4595d03dd2f0', '酬顧況見寄', '酬顧況见寄', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["于越城邊楓葉高，楚人書裏寄離騷。","寒江鸂鶒思儔侶，歲歲臨流刷羽毛。"]', '["于越城邊楓葉高，楚人书裏寄離騷。","寒江鸂鶒思儔侶，歲歲臨流刷羽毛。"]', '诗', 'shi', '', NULL, '酬顧況見寄 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e27839b5-a0d2-41ff-aa5b-a2a0355afc68', '歲日作', '歲日作', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["更勞今日春風至，枯樹無枝可寄花。","覽鏡唯看飄亂髮，臨風誰爲駐浮槎。"]', '["更勞今日春风至，枯樹無枝可寄花。","覽镜唯看飄亂髮，臨风誰爲駐浮槎。"]', '诗', 'shi', '', NULL, '歲日作 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('002801a4-8a5f-4931-83cd-49a1f94b0e51', '元日觀百僚朝會', '元日观百僚朝會', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["萬國賀唐堯，清晨會百僚。","花冠蕭相府，繡服霍嫖姚。","壽色凝丹檻，歡聲徹九霄。","御鑪分獸炭，仙管弄雲韶。","日照金觴動，風吹玉佩搖。","都城獻賦者，不得共趨朝。"]', '["万国賀唐堯，清晨會百僚。","花冠蕭相府，繡服霍嫖姚。","壽色凝丹檻，歡声徹九霄。","御鑪分獸炭，仙管弄云韶。","日照金觴动，风吹玉佩搖。","都城獻賦者，不得共趨朝。"]', '诗', 'shi', '', NULL, '元日觀百僚朝會 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99e68734-394d-4679-93a3-e60c4e1ad4b4', '再過金陵', '再過金陵', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["玉樹歌終王氣收，鴈行高送石城秋。","江山不管興亡事，一任斜陽伴客愁。"]', '["玉樹歌終王氣收，鴈行高送石城秋。","江山不管兴亡事，一任斜陽伴客愁。"]', '诗', 'shi', '', NULL, '再過金陵 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('485b1bb2-22ad-445c-980e-219abd32e4f0', '寄楊侍御', '寄楊侍御', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["一官何幸得同時，十載無媒獨見遺。","今日不論腰下組，請君看取鬢邊絲。"]', '["一官何幸得同时，十載無媒独见遺。","今日不論腰下組，請君看取鬢邊絲。"]', '诗', 'shi', '', NULL, '寄楊侍御 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9c84c93-6f83-4456-80d8-8b7fe5e427a2', '江上曲', '江上曲', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["江心澹澹芙蓉花，江口蛾眉獨浣紗。","可憐應是陽臺女，對坐鷺鷥嬌不語。","掩面羞看北地人，回身忽作空山語。","蒼梧秋色不堪論，千載依依帝子魂。","君看峰上斑斑竹，盡是湘妃泣淚痕。"]', '["江心澹澹芙蓉花，江口蛾眉独浣紗。","可怜應是陽台女，对坐鷺鷥嬌不語。","掩面羞看北地人，回身忽作空山語。","蒼梧秋色不堪論，千載依依帝子魂。","君看峰上斑斑竹，尽是湘妃泣泪痕。"]', '诗', 'shi', '', NULL, '江上曲 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28a07ece-270c-4194-ad97-8b944d5d4293', '傷吳中', '傷吳中', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["館娃宮中春已歸，闔閭城頭鶯已飛。","復見花開人又老，橫塘寂寂柳依依。","憶昔吳王在宮闕，館娃滿眼看花發。","舞袖朝欺陌上春，歌聲夜怨江邊月。","古來人事亦猶今，莫厭清觴與綠琴。","獨向西山聊一笑，白雲芳草自知心。"]', '["館娃宮中春已归，闔閭城头鶯已飞。","复见花开人又老，橫塘寂寂柳依依。","憶昔吳王在宮闕，館娃满眼看花發。","舞袖朝欺陌上春，歌声夜怨江邊月。","古来人事亦猶今，莫厭清觴與綠琴。","独向西山聊一笑，白云芳草自知心。"]', '诗', 'shi', '', NULL, '傷吳中 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e30c468-9d80-4b8c-9a87-1276b583687a', '夜聞江南人家賽神因題即事', '夜闻江南人家賽神因題即事', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["南方淫祀古風俗，楚嫗解唱迎神曲。","鎗鎗銅鼓蘆葉深，寂寂瓊筵江水綠。","雨過風清洲渚閑，椒漿醉盡迎神還。","帝女凌空下湘岸，番君隔浦向堯山。","月隱回塘猶自舞，一門依倚神之祜。","韓康靈藥不復求，扁鵲醫方曾莫覩。","逐客臨江空自悲，月明流水無已時。","聽此迎神送神曲，攜觴欲弔屈原祠。"]', '["南方淫祀古风俗，楚嫗解唱迎神曲。","鎗鎗銅鼓蘆葉深，寂寂瓊筵江水綠。","雨過风清洲渚闲，椒漿醉尽迎神還。","帝女凌空下湘岸，番君隔浦向堯山。","月隐回塘猶自舞，一门依倚神之祜。","韓康靈藥不复求，扁鵲醫方曾莫覩。","逐客臨江空自悲，月明流水無已时。","听此迎神送神曲，携觴欲弔屈原祠。"]', '诗', 'shi', '', NULL, '夜聞江南人家賽神因題即事 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6474e381-8e86-4d81-859b-c164f2155a19', '古興', '古兴', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["十五小家女，雙鬟人不如。","蛾眉暫一見，可直千金餘。","自從得向蓬萊裏，出入金輿乘玉趾。","梧桐樹上春鴉鳴，曉伴君王猶未起。","莫道君恩長不休，婕妤團扇苦悲秋。","君看魏帝鄴都裏，惟有銅臺漳水流。"]', '["十五小家女，雙鬟人不如。","蛾眉暫一见，可直千金餘。","自從得向蓬萊裏，出入金輿乘玉趾。","梧桐樹上春鴉鳴，晓伴君王猶未起。","莫道君恩长不休，婕妤團扇苦悲秋。","君看魏帝鄴都裏，惟有銅台漳水流。"]', '诗', 'shi', '', NULL, '古興 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fb7edee-7723-4b43-b0d1-9266be92085a', '雜興', '杂兴', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["花間昔日黃鸝囀，妾向青樓已生怨。","花落黃鸝不復來，妾老君心亦應變。","君心比妾心，妾意舊來深。","一別十年無尺素，歸時莫贈路傍金。"]', '["花间昔日黄鸝囀，妾向青楼已生怨。","花落黄鸝不复来，妾老君心亦應变。","君心比妾心，妾意旧来深。","一別十年無尺素，归时莫贈路傍金。"]', '诗', 'shi', '', NULL, '雜興 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02fdb3e2-f9dc-42c6-86cc-7d25e26b7411', '送韋邕少府歸鍾山', '送韋邕少府归鍾山', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["祈門官罷後，負笈向桃源。","萬卷長開帙，千峰不閉門。","綠楊垂野渡，黃鳥傍山村。","念爾能高枕，丹墀會一論。"]', '["祈门官罷後，負笈向桃源。","万卷长开帙，千峰不閉门。","綠楊垂野渡，黄鸟傍山村。","念爾能高枕，丹墀會一論。"]', '诗', 'shi', '', NULL, '送韋邕少府歸鍾山 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('533548fe-7dd5-4443-9374-5d91c7be7eea', '送盧員外往饒州', '送盧員外往饒州', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["爲郎復典郡，錦帳映朱輪。","露冕隨龍節，停橈得水人。","早霜蘆葉變，寒雨石榴新。","莫怪諳風土，三年作逐臣。"]', '["爲郎复典郡，錦帳映朱輪。","露冕隨龙節，停橈得水人。","早霜蘆葉变，寒雨石榴新。","莫怪諳风土，三年作逐臣。"]', '诗', 'shi', '', NULL, '送盧員外往饒州 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fc627fa-6569-4d61-9498-2b3b770ae02c', '送裴五歸京口', '送裴五归京口', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["君罷江西日，家貧爲一官。","還歸五陵去，只向遠峰看。","暮色催人別，秋風待雨寒。","遙知到三徑，唯有菊花殘。"]', '["君罷江西日，家貧爲一官。","還归五陵去，只向远峰看。","暮色催人別，秋风待雨寒。","遙知到三徑，唯有菊花殘。"]', '诗', 'shi', '', NULL, '送裴五歸京口 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ddf2b76-d1de-4a26-adaa-48c0cd3203d2', '送嚴維歸越州', '送嚴維归越州', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["艱難只用武，歸向淛河東。","松雪千山暮，林泉一水通。","鄉心緣綠草，野思看青楓。","春日偏相憶，裁書寄剡中。"]', '["艱难只用武，归向淛河东。","松雪千山暮，林泉一水通。","乡心緣綠草，野思看青楓。","春日偏相憶，裁书寄剡中。"]', '诗', 'shi', '', NULL, '送嚴維歸越州 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4173ec91-e1df-4acd-ab7c-697ff97e31b8', '送杜士瞻楚州覲省', '送杜士瞻楚州覲省', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["風流與才思，俱似晉時人。","淮月歸心促，江花入興新。","雲深滄海暮，柳暗白田春。","共道官猶小，憐君孝養親。"]', '["风流與才思，俱似晉时人。","淮月归心促，江花入兴新。","云深滄海暮，柳暗白田春。","共道官猶小，怜君孝養親。"]', '诗', 'shi', '', NULL, '送杜士瞻楚州覲省 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8a0aa65-3552-4460-9a5a-08eecec348a7', '送裴宣城上元所居', '送裴宣城上元所居', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["水流過海稀，爾去換春衣。","淚向檳榔盡，身隨鴻雁歸。","草思晴後發，花怨雨中飛。","想到金陵渚，酣歌對落暉。"]', '["水流過海稀，爾去換春衣。","泪向檳榔尽，身隨鴻雁归。","草思晴後發，花怨雨中飞。","想到金陵渚，酣歌对落暉。"]', '诗', 'shi', '', NULL, '送裴宣城上元所居 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dde40866-706c-4105-8845-b9babd63a926', '留別毘陵諸公', '留別毘陵諸公', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["久作涔陽令，丹墀忽再還。","淒涼辭澤國，離亂到鄉山。","北固灘聲滿，南徐草色閑。","知心從此別，相憶鬢毛斑。"]', '["久作涔陽令，丹墀忽再還。","淒涼辞澤国，離亂到乡山。","北固灘声满，南徐草色闲。","知心從此別，相憶鬢毛斑。"]', '诗', 'shi', '', NULL, '留別毘陵諸公 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71435a7a-6541-45dd-a0f3-de97ca80c620', '送獨孤拾遺先輩先赴上都', '送独孤拾遺先輩先赴上都', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["行春日已曉，桂檝逐寒煙。","轉曲遙峰出，看濤極浦連。","入京當獻賦，封事更聞天。","日日趨黃閣，應忘雲海邊。"]', '["行春日已晓，桂檝逐寒煙。","轉曲遙峰出，看濤極浦連。","入京當獻賦，封事更闻天。","日日趨黄閣，應忘云海邊。"]', '诗', 'shi', '', NULL, '送獨孤拾遺先輩先赴上都 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a1dfe28-4e40-488a-844d-5dbf5f3023e8', '常州韋郎中汎舟見餞', '常州韋郎中汎舟见餞', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["主人馮軾貴，送客汎舟稀。","逼岸隨芳草，回橈背落暉。","映花雙節駐，臨水伯勞飛。","醉與羣公狎，春塘露冕歸。"]', '["主人馮軾貴，送客汎舟稀。","逼岸隨芳草，回橈背落暉。","映花雙節駐，臨水伯勞飞。","醉與羣公狎，春塘露冕归。"]', '诗', 'shi', '', NULL, '常州韋郎中汎舟見餞 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1ebbb06-55b7-40d1-8f23-63491faa6fa7', '送崔侍御入朝', '送崔侍御入朝', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["十年猶執憲，萬里獨歸春。","舊國逢芳草，青雲見故人。","潘郎今髮白，陶令本家貧。","相送臨京口，停橈淚滿巾。"]', '["十年猶執憲，万里独归春。","旧国逢芳草，青云见故人。","潘郎今髮白，陶令本家貧。","相送臨京口，停橈泪满巾。"]', '诗', 'shi', '', NULL, '送崔侍御入朝 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccd8a969-3713-4066-b890-ead4d4fb7b6e', '送岳州司馬弟之任', '送岳州司马弟之任', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["岳陽天水外，念爾一帆過。","野墅人煙逈，山城雁影多。","有時巫峽色，終日洞庭波。","丞相今爲郡，應無勞者歌。"]', '["岳陽天水外，念爾一帆過。","野墅人煙逈，山城雁影多。","有时巫峽色，終日洞庭波。","丞相今爲郡，應無勞者歌。"]', '诗', 'shi', '', NULL, '送岳州司馬弟之任 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41181679-c303-4d56-a0a2-f454236cfa0b', '裴侍御見贈斑竹杖', '裴侍御见贈斑竹杖', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["騷人誇竹杖，贈我意何深。","萬點湘妃淚，三年賈誼心。","願持終白首，誰道貴黃金。","他日歸愚谷，偏宜綠綺琴。"]', '["騷人誇竹杖，贈我意何深。","万点湘妃泪，三年賈誼心。","願持終白首，誰道貴黄金。","他日归愚谷，偏宜綠綺琴。"]', '诗', 'shi', '', NULL, '裴侍御見贈斑竹杖 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e04861a-4123-4038-8fb3-b7089068eada', '送張觀歸袁州', '送張观归袁州', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["羨爾湘東去，煙花尚可親。","綠芳深映鳥，遠岫遞迎人。","飢狖啼初日，殘鶯惜暮春。","遙憐謝客興，佳句又應新。"]', '["羨爾湘东去，煙花尚可親。","綠芳深映鸟，远岫遞迎人。","飢狖啼初日，殘鶯惜暮春。","遙怜謝客兴，佳句又應新。"]', '诗', 'shi', '', NULL, '送張觀歸袁州 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7994f02-d08b-4d5b-9ffa-1aab1ca621a1', '冬夜饒州使堂餞相公五叔赴歙州', '冬夜饒州使堂餞相公五叔赴歙州', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["丞相過邦牧，清絃送羽觴。","高情同客醉，子夜爲人長。","斜漢這過斗，寒雲正護霜。","新安江自綠，明主待惟良。"]', '["丞相過邦牧，清絃送羽觴。","高情同客醉，子夜爲人长。","斜漢這過斗，寒云正護霜。","新安江自綠，明主待惟良。"]', '诗', 'shi', '', NULL, '冬夜饒州使堂餞相公五叔赴歙州 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b67d634-5c78-4b60-a552-b2a4c1c0f570', '蔣山開善寺', '蔣山开善寺', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["山殿秋雲裏，香煙出翠微。","客尋朝磬至，僧背夕陽歸。","下界千門在，前朝萬事非。","看心兼送目，葭菼自依依。"]', '["山殿秋云裏，香煙出翠微。","客尋朝磬至，僧背夕陽归。","下界千门在，前朝万事非。","看心兼送目，葭菼自依依。"]', '诗', 'shi', '', NULL, '蔣山開善寺 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64ce1225-6e8b-46b5-b1df-50a4cba1f0f3', '晚發江寧道中呈嚴維', '晚發江寧道中呈嚴維', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["惆悵遙江路，蕭條落日過。","蟬鳴獨樹急，鴉向古城多。","轉曲隨青嶂，因高見白波。","潘生秋徑草，嚴子意如何。"]', '["惆悵遙江路，蕭條落日過。","蟬鳴独樹急，鴉向古城多。","轉曲隨青嶂，因高见白波。","潘生秋徑草，嚴子意如何。"]', '诗', 'shi', '', NULL, '晚發江寧道中呈嚴維 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('020842e9-f0d8-42ab-b484-44909b2da611', '句容縣東青陽館作', '句容縣东青陽館作', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["句曲千峰暮，歸人向遠煙。","風搖近水葉，雲護欲晴天。","夕照留山館，秋光落草田。","征途傍斜日，一騎獨翩翩。"]', '["句曲千峰暮，归人向远煙。","风搖近水葉，云護欲晴天。","夕照留山館，秋光落草田。","征途傍斜日，一騎独翩翩。"]', '诗', 'shi', '', NULL, '句容縣東青陽館作 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74dba239-9f0b-4c10-b35c-a4a3440c1844', '晚春宴無錫蔡明府西亭', '晚春宴無錫蔡明府西亭', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["茅簷閑寂寂，無事覺人和。","井近時澆圃，城低下見河。","興緣芳草積，情向遠峰多。","別日歸吳地，停橈更一過。"]', '["茅簷闲寂寂，無事覺人和。","井近时澆圃，城低下见河。","兴緣芳草積，情向远峰多。","別日归吳地，停橈更一過。"]', '诗', 'shi', '', NULL, '晚春宴無錫蔡明府西亭 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d93b38b6-87b1-4440-9a3e-ef787ece0177', '送王端赴朝', '送王端赴朝', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["君承明主意，日日上丹墀。","東閣論兵後，南宮草奏期。","人稀傍河處，槐暗入關時。","獨遣吳州客，平陵結夢思。"]', '["君承明主意，日日上丹墀。","东閣論兵後，南宮草奏期。","人稀傍河处，槐暗入关时。","独遣吳州客，平陵結梦思。"]', '诗', 'shi', '', NULL, '送王端赴朝 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9deee86d-3d16-40f1-aff9-f8805c75d827', '送王正字山寺讀書', '送王正字山寺读书', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["欲究先儒教，還過支遁居。","山堦閑聽法，竹逕獨看書。","向日荷新卷，迎秋柳半疎。","風流有佳句，不似帶經鋤。"]', '["欲究先儒教，還過支遁居。","山堦闲听法，竹逕独看书。","向日荷新卷，迎秋柳半疎。","风流有佳句，不似带經鋤。"]', '诗', 'shi', '', NULL, '送王正字山寺讀書 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4964360-04be-4cde-a26a-df00ee1f498c', '送房明府罷長寧令湖州客舍', '送房明府罷长寧令湖州客舍', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["君爲萬里宰，恩及五湖人。","未滿先求退，歸閑不厭貧。","遠峰晴更近，殘柳雨還新。","要自趨丹陛，明年雞樹親。"]', '["君爲万里宰，恩及五湖人。","未满先求退，归闲不厭貧。","远峰晴更近，殘柳雨還新。","要自趨丹陛，明年雞樹親。"]', '诗', 'shi', '', NULL, '送房明府罷長寧令湖州客舍 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c23312e-3048-4c55-9912-4d83d982cf18', '詠螢', '詠螢', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["映水光難定，凌虛體自輕。","夜風吹不滅，秋露洗還明。","向燭仍分焰，投書更有情。","猶將流亂影，來此傍簷楹。"]', '["映水光难定，凌虛體自轻。","夜风吹不滅，秋露洗還明。","向燭仍分焰，投书更有情。","猶將流亂影，来此傍簷楹。"]', '诗', 'shi', '', NULL, '詠螢 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50b98014-0f20-4554-b959-8c8929b28582', '送李中丞楊判官', '送李中丞楊判官', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["射策名先著，論兵氣自雄。","能全季布諾，不道魯連功。","流水蒹葭外，諸山睥睨中。","別君秋日晚，回首夕陽空。"]', '["射策名先著，論兵氣自雄。","能全季布諾，不道魯連功。","流水蒹葭外，諸山睥睨中。","別君秋日晚，回首夕陽空。"]', '诗', 'shi', '', NULL, '送李中丞楊判官 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90852836-e7f5-4e1f-87d7-5961625496ad', '至七里灘作', '至七里灘作', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["遷客投於越，臨江淚滿衣。","獨隨流水遠，轉覺故人稀。","萬木迎秋序，千峰駐晚暉。","行舟猶未已，惆悵暮潮歸。"]', '["遷客投於越，臨江泪满衣。","独隨流水远，轉覺故人稀。","万木迎秋序，千峰駐晚暉。","行舟猶未已，惆悵暮潮归。"]', '诗', 'shi', '', NULL, '至七里灘作 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4da1836b-da70-4a43-9e51-a9bc390a0fe9', '南浦渡口', '南浦渡口', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["寂寞橫塘路，新篁覆水低。","東風潮信滿，時雨稻秔齊。","寡婦共租稅，漁人逐鼓鼙。","慙無卓魯術，解印謝黔黎。"]', '["寂寞橫塘路，新篁覆水低。","东风潮信满，时雨稻秔齊。","寡婦共租稅，漁人逐鼓鼙。","慙無卓魯術，解印謝黔黎。"]', '诗', 'shi', '', NULL, '南浦渡口 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0167aaca-d4f5-4e4b-9fb8-bd29260f31b7', '暮秋遷客增思寄京華', '暮秋遷客增思寄京华', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["宋玉怨三秋，張衡復四愁。","思鄉雁北至，欲別水東流。","倚樹看黃葉，逢人訴白頭。","佳期不可失，落日自登樓。"]', '["宋玉怨三秋，張衡复四愁。","思乡雁北至，欲別水东流。","倚樹看黄葉，逢人訴白头。","佳期不可失，落日自登楼。"]', '诗', 'shi', '', NULL, '暮秋遷客增思寄京華 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d09e9302-9cad-4c5d-9a81-9333926e16c5', '送蘇修往上饒', '送蘇修往上饒', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["愛爾無羈束，雲山恣意過。","一身隨遠岫，孤櫂任輕波。","世事關心少，漁家寄宿多。","蘆花泊舟處，江月奈人何。"]', '["愛爾無羈束，云山恣意過。","一身隨远岫，孤櫂任轻波。","世事关心少，漁家寄宿多。","蘆花泊舟处，江月奈人何。"]', '诗', 'shi', '', NULL, '送蘇修往上饒 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5e8730f-33d8-4f24-9e84-c5736559a754', '題王十九茆堂', '題王十九茆堂', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["滿庭多種藥，入里作山家。","終日能留客，凌寒亦對花。","海鷗過竹嶼，門柳拂江沙。","知爾卑棲意，題詩美白華。"]', '["满庭多種藥，入里作山家。","終日能留客，凌寒亦对花。","海鷗過竹嶼，门柳拂江沙。","知爾卑棲意，題诗美白华。"]', '诗', 'shi', '', NULL, '題王十九茆堂 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4058b815-c70e-4e63-8101-481838451b80', '送弘志上人歸湖州', '送弘志上人归湖州', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["山林唯幽靜，行住不妨禪。","高月穿松逕，殘陽過水田。","詩從宿世悟，法爲本師傳。","能使南人敬，修持香火緣。"]', '["山林唯幽静，行住不妨禪。","高月穿松逕，殘陽過水田。","诗從宿世悟，法爲本師傳。","能使南人敬，修持香火緣。"]', '诗', 'shi', '', NULL, '送弘志上人歸湖州 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8af9dc6-1cb8-481a-99f5-a5b541a7211c', '送陸士倫宰義興', '送陸士倫宰義兴', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["陽羨蘭陵近，高城帶水閑。","淺流通野寺，綠茗蓋春山。","長吏多愁罷，遊人詎肯還。","知君日清淨，無事掩重關。"]', '["陽羨蘭陵近，高城带水闲。","淺流通野寺，綠茗蓋春山。","长吏多愁罷，游人詎肯還。","知君日清淨，無事掩重关。"]', '诗', 'shi', '', NULL, '送陸士倫宰義興 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57a69cfd-64bb-45a4-a77f-acd1e0ccd4f2', '和張舍人中書宿直', '和張舍人中书宿直', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["漢主留才子，春城直紫微。","對花閶闔靜，過竹吏人稀。","裁詔催添燭，將朝欲更衣。","玉堂宜歲久，且莫厭彤闈。"]', '["漢主留才子，春城直紫微。","对花閶闔静，過竹吏人稀。","裁詔催添燭，將朝欲更衣。","玉堂宜歲久，且莫厭彤闈。"]', '诗', 'shi', '', NULL, '和張舍人中書宿直 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('906f5bf6-edeb-4e57-ad55-b555632ed3f2', '司勳王郎中宅送韋九郎中往濠州', '司勳王郎中宅送韋九郎中往濠州', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["憐爾因同舍，看書似外家。","出關逢落葉，傍水見寒花。","送遠添秋思，將衰戀歲華。","清淮倍相憶，回首莫令賒。"]', '["怜爾因同舍，看书似外家。","出关逢落葉，傍水见寒花。","送远添秋思，將衰戀歲华。","清淮倍相憶，回首莫令賒。"]', '诗', 'shi', '', NULL, '司勳王郎中宅送韋九郎中往濠州 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cffe3dda-3661-44a4-82b5-a6e797d90996', '晚春送吉校書歸楚州', '晚春送吉校书归楚州', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["詩人饒楚思，淮上及春歸。","舊浦菱花發，閑門柳絮飛。","高名鄉曲重，少事道流稀。","定向漁家醉，殘陽臥釣磯。"]', '["诗人饒楚思，淮上及春归。","旧浦菱花發，闲门柳絮飞。","高名乡曲重，少事道流稀。","定向漁家醉，殘陽臥釣磯。"]', '诗', 'shi', '', NULL, '晚春送吉校書歸楚州 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b2c8e43-f10d-45f0-a287-b9a9a7f7d90d', '送嚴二擢第東歸', '送嚴二擢第东归', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["隳官就賓薦，時輩詎爭先。","盛業推儒行，高科獨少年。","迎秋見衰葉，餘照逐鳴蟬。","舊里三峰下，開門古縣前。"]', '["隳官就賓薦，时輩詎爭先。","盛業推儒行，高科独少年。","迎秋见衰葉，餘照逐鳴蟬。","旧里三峰下，开门古縣前。"]', '诗', 'shi', '', NULL, '送嚴二擢第東歸 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b91be50-04b7-4afd-a8cd-fd519f6913e2', '送冷朝陽及第東歸江寧', '送冷朝陽及第东归江寧', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["高第由佳句，諸生似者稀。","長安帶酒別，建業候潮歸。","稚子歡迎櫂，隣人爲掃扉。","含情過舊浦，鷗鳥亦依依。"]', '["高第由佳句，諸生似者稀。","长安带酒別，建業候潮归。","稚子歡迎櫂，隣人爲掃扉。","含情過旧浦，鷗鸟亦依依。"]', '诗', 'shi', '', NULL, '送冷朝陽及第東歸江寧 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c08bd7f-4428-47f3-b4c8-dfb6c845732e', '送越州辛法曹之任', '送越州辛法曹之任', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["但能一官適，莫羨五侯尊。","山色垂趨府，潮聲自到門。","緣塘剡溪路，映竹五湖村。","王謝登臨處，依依今尚存。"]', '["但能一官適，莫羨五侯尊。","山色垂趨府，潮声自到门。","緣塘剡溪路，映竹五湖村。","王謝登臨处，依依今尚存。"]', '诗', 'shi', '', NULL, '送越州辛法曹之任 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f14e7e2-6703-487c-acde-03fcb5af2dda', '送樊兵曹潭州謁韋大夫', '送樊兵曹潭州謁韋大夫', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["塞鴻歸欲盡，北客始辭春。","零桂雖逢竹，湘川少見人。","江花鋪淺水，山木暗殘春。","修刺轅門裏，多憐爾爲親。"]', '["塞鴻归欲尽，北客始辞春。","零桂雖逢竹，湘川少见人。","江花鋪淺水，山木暗殘春。","修刺轅门裏，多怜爾爲親。"]', '诗', 'shi', '', NULL, '送樊兵曹潭州謁韋大夫 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7001236e-1245-48ce-af89-43614dce03bd', '送杜御史還廣陵', '送杜御史還廣陵', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["慙君從弱歲，顧我比諸昆。","同事元戎久，俱承國士恩。","隨鶯過淮水，看柳向轅門。","草色金陵岸，思心那可論。"]', '["慙君從弱歲，顧我比諸昆。","同事元戎久，俱承国士恩。","隨鶯過淮水，看柳向轅门。","草色金陵岸，思心那可論。"]', '诗', 'shi', '', NULL, '送杜御史還廣陵 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04eb81bc-564c-434c-89a8-bb2920ae3ac1', '送兗州杜別駕之任', '送兗州杜別駕之任', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["停車邀別乘，促軫奏胡笳。","若見楚山暮，因愁浙水賒。","河堤經淺草，村徑歷繁花。","更有堪悲處，梁城春日斜。"]', '["停车邀別乘，促軫奏胡笳。","若见楚山暮，因愁浙水賒。","河堤經淺草，村徑歷繁花。","更有堪悲处，梁城春日斜。"]', '诗', 'shi', '', NULL, '送兗州杜別駕之任 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42bff76a-a87d-4701-966c-ac367bf4d4d0', '題裴十六少卿東亭', '題裴十六少卿东亭', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["平津舊東閣，深巷見南山。","卷箔嵐煙潤，遮牕竹影閑。","傾茶兼落帽，戀客不開關。","斜照窺簾外，川禽時往還。"]', '["平津旧东閣，深巷见南山。","卷箔嵐煙潤，遮牕竹影闲。","傾茶兼落帽，戀客不开关。","斜照窺簾外，川禽时往還。"]', '诗', 'shi', '', NULL, '題裴十六少卿東亭 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8788cd3e-5458-47a4-86b0-9ca39798283e', '同皇甫侍御題薦福寺一公房', '同皇甫侍御題薦福寺一公房', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["虛室獨焚香，林空靜磬長。","閑窺數竿竹，老在一繩牀。","啜茗翻真偈，然燈繼夕陽。","人歸遠相送，步履出回廊。"]', '["虛室独焚香，林空静磬长。","闲窺數竿竹，老在一繩牀。","啜茗翻真偈，然灯繼夕陽。","人归远相送，步履出回廊。"]', '诗', 'shi', '', NULL, '同皇甫侍御題薦福寺一公房 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ace98560-95a8-432b-9f52-eb9538c9b4a5', '送從姪端之東都', '送從姪端之东都', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["虜近人行少，憐君獨出城。","故關逢落葉，寒日逐徂征。","聞笛添歸思，看山愜野情。","皇華今絕少，龍頟也相迎。"]', '["虜近人行少，怜君独出城。","故关逢落葉，寒日逐徂征。","闻笛添归思，看山愜野情。","皇华今絕少，龙頟也相迎。"]', '诗', 'shi', '', NULL, '送從姪端之東都 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a06822a8-066a-4eaf-96e9-b074349ac01d', '送王諫議充東都留守判官', '送王諫議充东都留守判官', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["時稱謝康樂，別事漢平津。","衰柳寒關道，高車左掖臣。","背河見北雁，到洛問東人。","憶昔遊金谷，相看華髮新。"]', '["时稱謝康乐，別事漢平津。","衰柳寒关道，高车左掖臣。","背河见北雁，到洛问东人。","憶昔游金谷，相看华髮新。"]', '诗', 'shi', '', NULL, '送王諫議充東都留守判官 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cf2d943-e52c-4406-bd53-03f686f4abb7', '和都官苗員外秋夜省直對雨簡諸知己', '和都官苗員外秋夜省直对雨簡諸知己', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["多雨南宮夜，仙郎寓直時。","漏長丹鳳闕，秋冷白雲司。","螢影侵堦亂，鴻聲出苑遲。","蕭條人吏散，小謝有新詩。"]', '["多雨南宮夜，仙郎寓直时。","漏长丹鳳闕，秋冷白云司。","螢影侵堦亂，鴻声出苑遲。","蕭條人吏散，小謝有新诗。"]', '诗', 'shi', '', NULL, '和都官苗員外秋夜省直對雨簡諸知己 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f83410d6-cd74-4482-812f-2e7b1d126333', '送從弟歸河朔', '送從弟归河朔', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["故鄉那可到，令弟獨能歸。","諸將矜旄節，何人重布衣。","空城流水在，荒澤舊村稀。","秋日平原路，蟲鳴桑葉飛。"]', '["故乡那可到，令弟独能归。","諸將矜旄節，何人重布衣。","空城流水在，荒澤旧村稀。","秋日平原路，蟲鳴桑葉飞。"]', '诗', 'shi', '', NULL, '送從弟歸河朔 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0117d122-eb63-4b9c-9b0d-764719baccc1', '送崔夷甫員外和蕃', '送崔夷甫員外和蕃', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["君過湟中去，尋源未是賒。","經春逢白草，盡日度黃沙。","雙節行爲伴，孤烽到似家。","和戎非用武，不學李輕車。"]', '["君過湟中去，尋源未是賒。","經春逢白草，尽日度黄沙。","雙節行爲伴，孤烽到似家。","和戎非用武，不学李轻车。"]', '诗', 'shi', '', NULL, '送崔夷甫員外和蕃 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4f82821-1cd6-41ed-a7fb-8ce1470eea9b', '春日長安送從弟尉吳縣', '春日长安送從弟尉吳縣', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["春愁能浩蕩，送別又如何。","人向吳臺遠，鶯飛漢苑多。","見花羞白髮，因爾憶滄波。","好是神仙尉，前賢亦未過。"]', '["春愁能浩蕩，送別又如何。","人向吳台远，鶯飞漢苑多。","见花羞白髮，因爾憶滄波。","好是神仙尉，前賢亦未過。"]', '诗', 'shi', '', NULL, '春日長安送從弟尉吳縣 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbbc6828-0b3a-4640-a1c9-04223b560134', '元日無衣冠入朝寄皇甫拾遺冉從弟補闕紓', '元日無衣冠入朝寄皇甫拾遺冉從弟補闕紓', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["伏奏隨廉使，周行外冗員。","白髭空受歲，丹陛不朝天。","秉燭千官去，垂簾一室眠。","羨君青瑣裏，並冕入爐煙。"]', '["伏奏隨廉使，周行外冗員。","白髭空受歲，丹陛不朝天。","秉燭千官去，垂簾一室眠。","羨君青瑣裏，並冕入爐煙。"]', '诗', 'shi', '', NULL, '元日無衣冠入朝寄皇甫拾遺冉從弟補闕紓 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a72f115d-7bd1-4549-a495-dc1043f2a8a6', '和韓郎中揚子津翫雪寄嚴維', '和韓郎中揚子津翫雪寄嚴維', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["雪深揚子岸，看柳盡成梅。","山色潛知近，潮聲只聽來。","夜禽驚曉散，春物受寒催。","粉署生新興，瑤華寄上才。"]', '["雪深揚子岸，看柳尽成梅。","山色潛知近，潮声只听来。","夜禽驚晓散，春物受寒催。","粉署生新兴，瑤华寄上才。"]', '诗', 'shi', '', NULL, '和韓郎中揚子津翫雪寄嚴維 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c03ba182-6545-4ebb-8758-ecb1989b981b', '送王牧往吉州謁王使君叔', '送王牧往吉州謁王使君叔', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["細草綠汀洲，王孫耐薄遊。","年華初冠帶，文體舊弓裘。","野渡花爭發，春塘水亂流。","使君憐小阮，應念倚門愁。"]', '["細草綠汀洲，王孫耐薄游。","年华初冠带，文體旧弓裘。","野渡花爭發，春塘水亂流。","使君怜小阮，應念倚门愁。"]', '诗', 'shi', '', NULL, '送王牧往吉州謁王使君叔 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72b4526a-3179-4df1-a534-6ed85a50a07e', '廣陵送林宰', '廣陵送林宰', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["清政過前哲，香名達至尊。","明通漢家籍，重識府公恩。","春景生雲物，風潮歛雪痕。","長吟策羸馬，青楚入關門。"]', '["清政過前哲，香名達至尊。","明通漢家籍，重識府公恩。","春景生云物，风潮歛雪痕。","长吟策羸马，青楚入关门。"]', '诗', 'shi', '', NULL, '廣陵送林宰 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fb130fc-fd7a-4f7a-9128-120886ff520b', '贈衛南長官赴任', '贈衛南长官赴任', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["吏曹難茂宰，主意念疲人。","更事文犀節，還過白馬津。","雲間辭北闕，樹裏出西秦。","爲報陶明府，裁書莫厭貧。"]', '["吏曹难茂宰，主意念疲人。","更事文犀節，還過白马津。","云间辞北闕，樹裏出西秦。","爲報陶明府，裁书莫厭貧。"]', '诗', 'shi', '', NULL, '贈衛南長官赴任 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90f7a912-549f-444d-9b12-99c89f224b94', '自常州還江陰途中作', '自常州還江陰途中作', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["處處空籬落，江村不忍看。","無人花色慘，多雨鳥聲寒。","黃霸初臨郡，陶潛未罷官。","乘春務征伐，誰肯問凋殘。"]', '["处处空籬落，江村不忍看。","無人花色慘，多雨鸟声寒。","黄霸初臨郡，陶潛未罷官。","乘春務征伐，誰肯问凋殘。"]', '诗', 'shi', '', NULL, '自常州還江陰途中作 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ff09cfa-7e73-42d6-a0b9-26ae6d4f85f8', '潤州楊別駕宅送蔣九侍御收兵歸揚州', '潤州楊別駕宅送蔣九侍御收兵归揚州', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["沴氣清金虎，兵威壯鐵冠。","揚旌川色暗，吹角水風寒。","人對輜軿醉，花垂睥睨殘。","羨歸丞相閣，空望舊門欄。"]', '["沴氣清金虎，兵威壯鐵冠。","揚旌川色暗，吹角水风寒。","人对輜軿醉，花垂睥睨殘。","羨归丞相閣，空望旧门欄。"]', '诗', 'shi', '', NULL, '潤州楊別駕宅送蔣九侍御收兵歸揚州 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('889929d5-2846-4b0b-a3ad-1572ec48dfa4', '仲夏江陰官舍寄裴明府', '仲夏江陰官舍寄裴明府', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["萬室邊江次，孤城對海安。","朝霞晴作雨，濕氣晚生寒。","苔色侵衣桁，潮痕上井欄。","題詩招茂宰，思爾欲辭官。"]', '["万室邊江次，孤城对海安。","朝霞晴作雨，濕氣晚生寒。","苔色侵衣桁，潮痕上井欄。","題诗招茂宰，思爾欲辞官。"]', '诗', 'shi', '', NULL, '仲夏江陰官舍寄裴明府 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c56b83a-34f3-4a30-a7fe-c0f7bb2fcac1', '送夏侯審參軍遊江東', '送夏侯審參軍游江东', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["袖中多麗句，未遣世人聞。","醉夜眠江月，閑時逐海雲。","荻花寒漫漫，鷗鳥暮羣羣。","若到長沙苑，漁家更待君。"]', '["袖中多丽句，未遣世人闻。","醉夜眠江月，闲时逐海云。","荻花寒漫漫，鷗鸟暮羣羣。","若到长沙苑，漁家更待君。"]', '诗', 'shi', '', NULL, '送夏侯審參軍遊江東 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bd840b4-d47c-467f-a3f5-98ed69b0a1a4', '送袁員外宣慰勸農畢赴洪州使院', '送袁員外宣慰勸農畢赴洪州使院', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["聖主臨前殿，殷憂遣使臣。","氣迎天詔喜，恩發土膏春。","草色催歸櫂，鶯聲爲送人。","龍沙多道里，流水自相親。"]', '["聖主臨前殿，殷憂遣使臣。","氣迎天詔喜，恩發土膏春。","草色催归櫂，鶯声爲送人。","龙沙多道里，流水自相親。"]', '诗', 'shi', '', NULL, '送袁員外宣慰勸農畢赴洪州使院 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3377290f-6a0b-403b-8e2b-66980e476240', '送侍御史四叔歸朝', '送侍御史四叔归朝', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["淮南頻送別，臨水惜殘春。","攀折隋宮柳，淹留秦地人。","含情歸上國，論舊見平津。","更接天津近，餘花映綬新。"]', '["淮南頻送別，臨水惜殘春。","攀折隋宮柳，淹留秦地人。","含情归上国，論旧见平津。","更接天津近，餘花映綬新。"]', '诗', 'shi', '', NULL, '送侍御史四叔歸朝 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a44cd68d-3b13-4e10-bbf4-035abc5948a4', '登楚州城望驛路十餘里山村竹林相次交映', '登楚州城望驛路十餘里山村竹林相次交映', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["十里山村道，千峰櫟樹林。","霜濃竹枝亞，歲晚荻花深。","草市多樵客，漁家足水禽。","幽居雖可羨，無那子牟心。"]', '["十里山村道，千峰櫟樹林。","霜濃竹枝亞，歲晚荻花深。","草市多樵客，漁家足水禽。","幽居雖可羨，無那子牟心。"]', '诗', 'shi', '', NULL, '登楚州城望驛路十餘里山村竹林相次交映 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed9d64a1-e731-4851-92fa-05556336ef56', '奉陪韋潤州遊鶴林寺', '奉陪韋潤州游鹤林寺', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["野寺江城近，雙旌五馬過。","禪心超忍辱，梵語問多羅。","松林閑僧老，雲煙晚日和。","寒塘歸路轉，清磬隔微波。"]', '["野寺江城近，雙旌五马過。","禪心超忍辱，梵語问多羅。","松林闲僧老，云煙晚日和。","寒塘归路轉，清磬隔微波。"]', '诗', 'shi', '', NULL, '奉陪韋潤州遊鶴林寺 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('659a929c-5811-471d-a322-9d3aa5b6d9b8', '奉酬路五郎中院長新除工部員外見簡', '奉酬路五郎中院长新除工部員外见簡', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["一門同祕省，萬里作長城。","問絹蓮花府，揚旗細柳營。","詞鋒偏却敵，草奏直論兵。","何幸新詩贈，真輸小謝名。"]', '["一门同祕省，万里作长城。","问絹蓮花府，揚旗細柳營。","词鋒偏却敵，草奏直論兵。","何幸新诗贈，真輸小謝名。"]', '诗', 'shi', '', NULL, '奉酬路五郎中院長新除工部員外見簡 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8b5abae-eba0-409b-8690-9bcb9655ab1e', '送韋司直西行', '送韋司直西行', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["不恥青袍故，尤宜白髮新。","心朝玉皇帝，貌似紫陽人。","湘浦眠銷日，桃源醉度春。","能文兼證道，莊叟是前身。"]', '["不恥青袍故，尤宜白髮新。","心朝玉皇帝，貌似紫陽人。","湘浦眠銷日，桃源醉度春。","能文兼證道，莊叟是前身。"]', '诗', 'shi', '', NULL, '送韋司直西行 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('436fc561-fab5-49ce-8506-59c5945fb2b5', '送上官侍御赴黔中', '送上官侍御赴黔中', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["莫向黔中路，令人到欲迷。","水聲巫峽裏，山色夜郎西。","樹隔朝雲合，猨窺曉月啼。","南方饒翠羽，知爾飲清溪。"]', '["莫向黔中路，令人到欲迷。","水声巫峽裏，山色夜郎西。","樹隔朝云合，猨窺晓月啼。","南方饒翠羽，知爾饮清溪。"]', '诗', 'shi', '', NULL, '送上官侍御赴黔中 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1a00c30-798a-4085-a3c8-bb6dd38b2e61', '送元侍御還荆南幕府', '送元侍御還荆南幕府', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["迢遞荆州路，山多水又分。","霜林澹寒日，朔鴈蔽南雲。","八座由持節，三湘亦置軍。","自當行直指，應不爲功勳。"]', '["迢遞荆州路，山多水又分。","霜林澹寒日，朔鴈蔽南云。","八座由持節，三湘亦置軍。","自當行直指，應不爲功勳。"]', '诗', 'shi', '', NULL, '送元侍御還荆南幕府 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb65a8de-23eb-4aa0-a490-61fb8e57f42a', '登湓城浦望廬山初晴直省齎敕催赴江陰', '登湓城浦望廬山初晴直省齎敕催赴江陰', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["西望香爐雪，千峰晚色新。","白頭悲作吏，黃紙苦催人。","多負登山屐，深藏漉酒巾。","傷心公府內，手板日相親。"]', '["西望香爐雪，千峰晚色新。","白头悲作吏，黄紙苦催人。","多負登山屐，深藏漉酒巾。","傷心公府內，手板日相親。"]', '诗', 'shi', '', NULL, '登湓城浦望廬山初晴直省齎敕催赴江陰 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('545ae0c5-171e-4e69-9c4c-b9a4300f6f95', '九日', '九日', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["惆悵重陽日，空山野菊新。","蒹葭百戰地，江海十年人。","歎老堪衰柳，傷秋對白蘋。","孤樓聞夕磬，塘路向城闉。"]', '["惆悵重陽日，空山野菊新。","蒹葭百戰地，江海十年人。","歎老堪衰柳，傷秋对白蘋。","孤楼闻夕磬，塘路向城闉。"]', '诗', 'shi', '', NULL, '九日 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11df3b79-9086-4902-840b-c9e9adf9fc25', '九日送人', '九日送人', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["晴景應重陽，高臺愴遠鄉。","水澄千室倒，霧卷四山長。","受節人逾老，驚寒菊半黃。","席前愁此別，未別已沾裳。"]', '["晴景應重陽，高台愴远乡。","水澄千室倒，霧卷四山长。","受節人逾老，驚寒菊半黄。","席前愁此別，未別已沾裳。"]', '诗', 'shi', '', NULL, '九日送人 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f523cd08-69d6-45c1-bc6a-633f43223f59', '春日淇上作', '春日淇上作', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["淇上春風漲，鴛鴦逐浪飛。","清明桑葉小，度雨杏花稀。","衛女紅粧薄，王孫白馬肥。","相將踏青去，不解惜羅衣。"]', '["淇上春风漲，鴛鴦逐浪飞。","清明桑葉小，度雨杏花稀。","衛女紅粧薄，王孫白马肥。","相將踏青去，不解惜羅衣。"]', '诗', 'shi', '', NULL, '春日淇上作 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('528dac78-a720-4031-8164-12f0f165c2e1', '送從叔陽冰祇召赴都', '送從叔陽冰祇召赴都', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["自小從遊慣，多由戲笑偏。","常時矜禮數，漸老荷優憐。","見主承休命，爲郎貴晚年。","伯喈文與篆，虛作漢家賢。"]', '["自小從游慣，多由戲笑偏。","常时矜禮數，漸老荷優怜。","见主承休命，爲郎貴晚年。","伯喈文與篆，虛作漢家賢。"]', '诗', 'shi', '', NULL, '送從叔陽冰祇召赴都 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de9b1a7e-ae47-460e-9d7d-6798210877ff', '送友人入湘', '送友人入湘', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["聞說湘川路，年年苦雨多。","猨啼巫峽雨，月照洞庭波。","窮海人還去，孤城雁共過。","青山不可極，來往自蹉跎。"]', '["闻说湘川路，年年苦雨多。","猨啼巫峽雨，月照洞庭波。","窮海人還去，孤城雁共過。","青山不可極，来往自蹉跎。"]', '诗', 'shi', '', NULL, '送友人入湘 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1baae898-b280-4e24-aa44-1c7b92850846', '送裴員外往江南', '送裴員外往江南', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["公務江南遠，留驩幕下榮。","楓林緣楚塞，水驛到湓城。","岸草知春晚，沙禽好夜驚。","風帆幾度泊，處處暮潮聲。"]', '["公務江南远，留驩幕下榮。","楓林緣楚塞，水驛到湓城。","岸草知春晚，沙禽好夜驚。","风帆幾度泊，处处暮潮声。"]', '诗', 'shi', '', NULL, '送裴員外往江南 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('953fb239-9773-4cb6-922b-505de607ecac', '登秦嶺', '登秦嶺', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["南登秦嶺頭，回望始堪愁。","漢闕青門遠，高山藍水流。","三湘遷客去，九陌故人遊。","從此辭鄉淚，雙垂不復收。"]', '["南登秦嶺头，回望始堪愁。","漢闕青门远，高山藍水流。","三湘遷客去，九陌故人游。","從此辞乡泪，雙垂不复收。"]', '诗', 'shi', '', NULL, '登秦嶺 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c16afdba-9694-47d9-b108-51b6dca140bc', '送張惟儉秀才入舉', '送張惟儉秀才入舉', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["清秀過終童，攜書訪老翁。","以吾爲世舊，憐爾繼家風。","淮岸經霜柳，關城帶月鴻。","春歸定得意，花送到東中。"]', '["清秀過終童，携书訪老翁。","以吾爲世旧，怜爾繼家风。","淮岸經霜柳，关城带月鴻。","春归定得意，花送到东中。"]', '诗', 'shi', '', NULL, '送張惟儉秀才入舉 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f24485df-2c1c-4633-8220-d7e60cdb3aa4', '送韋侍御湖南幕府', '送韋侍御湖南幕府', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["執憲隨征虜，逢秋出故關。","雨多愁郢路，葉下識衡山。","地遠從軍樂，兵強分野閑。","皇家不易將，此去未應還。"]', '["執憲隨征虜，逢秋出故关。","雨多愁郢路，葉下識衡山。","地远從軍乐，兵強分野闲。","皇家不易將，此去未應還。"]', '诗', 'shi', '', NULL, '送韋侍御湖南幕府 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f92251f-8521-4f44-ac7f-2cb17365e348', '同皇甫冉赴官留別靈一上人', '同皇甫冉赴官留別靈一上人', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["法許廬山遠，詩傳休上人。","獨歸雙樹宿，靜與百花親。","對物雖留興，觀空已悟身。","能令折腰客，遙賞竹房春。"]', '["法許廬山远，诗傳休上人。","独归雙樹宿，静與百花親。","对物雖留兴，观空已悟身。","能令折腰客，遙賞竹房春。"]', '诗', 'shi', '', NULL, '同皇甫冉赴官留別靈一上人 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a3d9214-9963-48a6-bb04-ce3cb73e07b3', '送客遊荆州', '送客游荆州', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["草色隨驄馬，悠悠共出秦。","水傳雲夢曉，山接洞庭春。","帆影連三峽，猨聲在四隣。","青門一分首，難見杜陵人。"]', '["草色隨驄马，悠悠共出秦。","水傳云梦晓，山接洞庭春。","帆影連三峽，猨声在四隣。","青门一分首，难见杜陵人。"]', '诗', 'shi', '', NULL, '送客遊荆州 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b9c6487-5561-4147-8a86-32b4e5956147', '與鄭錫遊春', '與鄭錫游春', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["東門垂柳長，回首獨心傷。","日暖臨芳草，天晴憶故鄉。","映花鶯上下，過水蝶悠颺。","借問同行客，今朝淚幾行。"]', '["东门垂柳长，回首独心傷。","日暖臨芳草，天晴憶故乡。","映花鶯上下，過水蝶悠颺。","借问同行客，今朝泪幾行。"]', '诗', 'shi', '', NULL, '與鄭錫遊春 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f19370d8-5bc7-42c7-a16b-740337f9e5d8', '故燕國相公輓歌二首 一', '故燕国相公輓歌二首 一', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["文若爲全德，留侯是重名。","論公長不宰，因病得無生。","大夢依禪定，高墳共化城。","自應憐寂滅，人世但傷情。"]', '["文若爲全德，留侯是重名。","論公长不宰，因病得無生。","大梦依禪定，高墳共化城。","自應怜寂滅，人世但傷情。"]', '诗', 'shi', '', NULL, '故燕國相公輓歌二首 一 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a5dcd73-11dd-46df-9eb3-e345148ad909', '故燕國相公輓歌二首 二', '故燕国相公輓歌二首 二', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["共美持衡日，皆言折檻時。","蜀侯供廟略，漢主缺台司。","車馬行仍止，笳簫咽又悲。","今年杜陵陌，殄瘁百花遲。"]', '["共美持衡日，皆言折檻时。","蜀侯供廟略，漢主缺台司。","车马行仍止，笳簫咽又悲。","今年杜陵陌，殄瘁百花遲。"]', '诗', 'shi', '', NULL, '故燕國相公輓歌二首 二 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e84d461b-df53-426b-ba6a-848c87223cab', '故吏部郎中贈給事中韋公挽歌二首 一', '故吏部郎中贈給事中韋公挽歌二首 一', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["神理今何在，斯人竟若斯。","顏淵徒有德，伯道且無兒。","白髮今非老，青雲數有奇。","誰言夕郎拜，翻向夜臺悲。"]', '["神理今何在，斯人竟若斯。","顏淵徒有德，伯道且無兒。","白髮今非老，青云數有奇。","誰言夕郎拜，翻向夜台悲。"]', '诗', 'shi', '', NULL, '故吏部郎中贈給事中韋公挽歌二首 一 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e70522e6-cb7f-4624-94e7-96ce81db4c6c', '故吏部郎中贈給事中韋公挽歌二首 二', '故吏部郎中贈給事中韋公挽歌二首 二', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["社里東城接，松阡北地開。","聞笳春色慘，執紼故人哀。","終日南山對，何時渭水回。","仁兄與恩舊，相望泣泉臺。"]', '["社里东城接，松阡北地开。","闻笳春色慘，執紼故人哀。","終日南山对，何时渭水回。","仁兄與恩旧，相望泣泉台。"]', '诗', 'shi', '', NULL, '故吏部郎中贈給事中韋公挽歌二首 二 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d233eb4-3770-4ebd-abaf-7e54728db062', '和袁郎中破賊後經剡縣山水上太尉', '和袁郎中破賊後經剡縣山水上太尉', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["受律仙郎貴，長驅下會稽。","鳴笳山月曉，搖斾野雲低。","翦寇人皆賀，迴軍馬自嘶。","地閑春草綠，城靜夜烏啼。","破竹清閩嶺，看花入剡溪。","元戎催獻捷，莫道事攀躋。"]', '["受律仙郎貴，长驱下會稽。","鳴笳山月晓，搖斾野云低。","翦寇人皆賀，迴軍马自嘶。","地闲春草綠，城静夜烏啼。","破竹清閩嶺，看花入剡溪。","元戎催獻捷，莫道事攀躋。"]', '诗', 'shi', '', NULL, '和袁郎中破賊後經剡縣山水上太尉 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6b89b6c-ce08-47a5-b56c-4d3c26dd52fd', '送評事十九叔入秦', '送評事十九叔入秦', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["白露沾蕙草，王孫轉憶歸。","蔡州新戰罷，郢路去人稀。","謁帝不辭遠，懷親空有違。","孤舟看落葉，平楚逐斜暉。","北闕見端冕，南臺當繡衣。","唯余播遷客，只伴鷓鴣飛。"]', '["白露沾蕙草，王孫轉憶归。","蔡州新戰罷，郢路去人稀。","謁帝不辞远，懷親空有違。","孤舟看落葉，平楚逐斜暉。","北闕见端冕，南台當繡衣。","唯余播遷客，只伴鷓鴣飞。"]', '诗', 'shi', '', NULL, '送評事十九叔入秦 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f888b69-cfce-4eb1-bee2-109b63caf609', '贈王八衢', '贈王八衢', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["丹地偏相逐，清江若有期。","腰金才子貴，剖竹老人遲。","桂楫閑迎客，茶甌對說詩。","渚田分邑里，山桂樹罘罳。","心靜無華髮，人和似古時。","別君遠山去，幽獨更應悲。"]', '["丹地偏相逐，清江若有期。","腰金才子貴，剖竹老人遲。","桂楫闲迎客，茶甌对说诗。","渚田分邑里，山桂樹罘罳。","心静無华髮，人和似古时。","別君远山去，幽独更應悲。"]', '诗', 'shi', '', NULL, '贈王八衢 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a31da724-61fb-4082-a5e3-ba1d3b7f2d9c', '入睦州分水路憶劉長卿', '入睦州分水路憶劉长卿', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["北闕忤明主，南方隨白雲。","沿洄灘草色，應接海鷗羣。","建德潮已盡，新安江又分。","回看嚴子瀨，朗詠謝安文。","雨過暮山碧，猨吟秋日曛。","吳洲不可到，刷鬢爲思君。"]', '["北闕忤明主，南方隨白云。","沿洄灘草色，應接海鷗羣。","建德潮已尽，新安江又分。","回看嚴子瀨，朗詠謝安文。","雨過暮山碧，猨吟秋日曛。","吳洲不可到，刷鬢爲思君。"]', '诗', 'shi', '', NULL, '入睦州分水路憶劉長卿 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb420b79-5f9d-405b-9bd3-37fece652d2f', '奉和杜相公長興新宅即事呈元相公', '奉和杜相公长兴新宅即事呈元相公', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["意有空門樂，居無甲第奢。","經過容法侶，雕飾讓侯家。","隱樹重簷肅，開園一逕斜。","據梧聽好鳥，行藥寄名花。","夢蝶留清簟，垂貂坐絳紗。","當山不掩戶，映日自傾茶。","雅望歸安石，深知在叔牙。","還成吉甫頌，贈荅比瑤華。"]', '["意有空门乐，居無甲第奢。","經過容法侶，雕飾讓侯家。","隐樹重簷肅，开园一逕斜。","據梧听好鸟，行藥寄名花。","梦蝶留清簟，垂貂坐絳紗。","當山不掩戶，映日自傾茶。","雅望归安石，深知在叔牙。","還成吉甫頌，贈荅比瑤华。"]', '诗', 'shi', '', NULL, '奉和杜相公長興新宅即事呈元相公 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3007f5f4-1d3c-4960-9e74-d75729d8fe3a', '江湖秋思', '江湖秋思', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["趨陪禁掖鴈行隨，遷向江潭鶴髮垂。","素浪遙疑八谿水，清楓忽似萬年枝。","嵩南春徧傷魂夢，壺口雲深隔路岐。","共望漢朝多霈澤，蒼蠅早晚得先知。"]', '["趨陪禁掖鴈行隨，遷向江潭鹤髮垂。","素浪遙疑八谿水，清楓忽似万年枝。","嵩南春徧傷魂梦，壺口云深隔路岐。","共望漢朝多霈澤，蒼蠅早晚得先知。"]', '诗', 'shi', '', NULL, '江湖秋思 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7c38125-f18c-453a-beaf-e2aea15560a4', '送朱中舍游江東', '送朱中舍游江东', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["孤城郭外送王孫，越水吳洲共爾論。","野寺山邊斜有逕，漁家竹裏半開門。","青楓獨映搖前浦，白鷺閑飛過遠村。","若到西陵征戰處，不堪秋草自傷魂。"]', '["孤城郭外送王孫，越水吳洲共爾論。","野寺山邊斜有逕，漁家竹裏半开门。","青楓独映搖前浦，白鷺闲飞過远村。","若到西陵征戰处，不堪秋草自傷魂。"]', '诗', 'shi', '', NULL, '送朱中舍游江東 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ce226b7-ea64-4eff-8070-de1fefab65b3', '送竇拾遺赴朝因寄中書十七弟', '送竇拾遺赴朝因寄中书十七弟', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["自歎未霑黃紙詔，那堪遠送赤墀人。","老爲僑客偏相戀，素是詩家倍益親。","妻兒共載無羈思，鴛鷺同行不負身。","憑爾將書通令弟，唯論華髮愧頭巾。"]', '["自歎未霑黄紙詔，那堪远送赤墀人。","老爲僑客偏相戀，素是诗家倍益親。","妻兒共載無羈思，鴛鷺同行不負身。","憑爾將书通令弟，唯論华髮愧头巾。"]', '诗', 'shi', '', NULL, '送竇拾遺赴朝因寄中書十七弟 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39623e50-e397-46d0-8715-f405674194cf', '自蘇臺至望亭驛人家盡空春物增思悵然有作因寄從弟紓', '自蘇台至望亭驛人家尽空春物增思悵然有作因寄從弟紓', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["南浦菰蔣覆白蘋，東吳黎庶逐黃巾。","野棠自發空臨水，江燕初歸不見人。","遠岫依依如送客，平田渺渺獨傷春。","那堪回首長洲苑，烽火年年報虜塵。"]', '["南浦菰蔣覆白蘋，东吳黎庶逐黄巾。","野棠自發空臨水，江燕初归不见人。","远岫依依如送客，平田渺渺独傷春。","那堪回首长洲苑，烽火年年報虜塵。"]', '诗', 'shi', '', NULL, '自蘇臺至望亭驛人家盡空春物增思悵然有作因寄從弟紓 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f38be33d-7a3b-4a47-a06d-1c87deffd4ef', '承恩量移宰江邑臨鄱江悵然之作', '承恩量移宰江邑臨鄱江悵然之作', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["四年謫宦滯江城，未厭門前鄱水清。","誰言宰邑化黎庶，欲別雲山如弟兄。","雙鷗爲底無心狎，白髮從他遶鬢生。","惆悵閑眠臨極浦，夕陽秋草不勝情。"]', '["四年謫宦滯江城，未厭门前鄱水清。","誰言宰邑化黎庶，欲別云山如弟兄。","雙鷗爲底無心狎，白髮從他遶鬢生。","惆悵闲眠臨極浦，夕陽秋草不勝情。"]', '诗', 'shi', '', NULL, '承恩量移宰江邑臨鄱江悵然之作 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1b6399b-c2e2-4a61-8d15-b3362da6d6b0', '題靈臺縣東山村主人', '題靈台縣东山村主人', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["處處征胡人漸稀，山村寥落暮煙微。","門臨莽蒼經年閉，身逐嫖姚幾日歸。","貧妻白髮輸殘稅，餘寇黃河未解圍。","天子如今能用武，祗應歲晚息兵機。"]', '["处处征胡人漸稀，山村寥落暮煙微。","门臨莽蒼經年閉，身逐嫖姚幾日归。","貧妻白髮輸殘稅，餘寇黄河未解圍。","天子如今能用武，祗應歲晚息兵機。"]', '诗', 'shi', '', NULL, '題靈臺縣東山村主人 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('defb1a3b-499d-47da-b4ed-e397a921753e', '同皇甫冉登重玄閣', '同皇甫冉登重玄閣', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["高閣朱欄不厭遊，蒹葭白水遶長洲。","孤雲獨鳥川光暮，萬井千山海色秋。","清梵林中人轉靜，夕陽城上角偏愁。","誰憐遠作秦吳別，離恨歸心雙淚流。"]', '["高閣朱欄不厭游，蒹葭白水遶长洲。","孤云独鸟川光暮，万井千山海色秋。","清梵林中人轉静，夕陽城上角偏愁。","誰怜远作秦吳別，離恨归心雙泪流。"]', '诗', 'shi', '', NULL, '同皇甫冉登重玄閣 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('930a9bfb-ee77-4806-b03c-7bf63a9b070e', '宋州東登望題武陵驛', '宋州东登望題武陵驛', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["梁宋人稀鳥自啼，登艫一望倍含悽。","白骨半隨河水去，黃雲猶傍郡城低。","平陂戰地花空落，舊苑春田草未齊。","明主頻移虎符守，幾時行縣向黔黎。"]', '["梁宋人稀鸟自啼，登艫一望倍含悽。","白骨半隨河水去，黄云猶傍郡城低。","平陂戰地花空落，旧苑春田草未齊。","明主頻移虎符守，幾时行縣向黔黎。"]', '诗', 'shi', '', NULL, '宋州東登望題武陵驛 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0561406-6676-4987-8d23-f7aba74b1273', '晚登江樓有懷', '晚登江楼有懷', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["獨坐南樓佳興新，青山綠水共爲隣。","爽氣遙分隔浦岫，斜光偏照渡江人。","心閑鷗鳥時相近，事簡魚竿私自親。","只憶帝京不可到，秋琴一弄欲沾巾。"]', '["独坐南楼佳兴新，青山綠水共爲隣。","爽氣遙分隔浦岫，斜光偏照渡江人。","心闲鷗鸟时相近，事簡鱼竿私自親。","只憶帝京不可到，秋琴一弄欲沾巾。"]', '诗', 'shi', '', NULL, '晚登江樓有懷 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36128fe1-a9f6-4841-99a6-9b7995ac94d3', '遊徐城河忽見清淮因寄趙八', '游徐城河忽见清淮因寄趙八', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["自緣遲暮憶滄洲，翻愛南河濁水流。","初過重陽惜殘菊，行看舊浦識羣鷗。","朝霞映日同歸處，暝柳搖風欲別秋。","長恨相逢即分首，含情掩淚獨回頭。"]', '["自緣遲暮憶滄洲，翻愛南河濁水流。","初過重陽惜殘菊，行看旧浦識羣鷗。","朝霞映日同归处，暝柳搖风欲別秋。","长恨相逢即分首，含情掩泪独回头。"]', '诗', 'shi', '', NULL, '遊徐城河忽見清淮因寄趙八 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a742e3a3-3988-418b-9cab-d8f72c78f439', '題遊仙閣白公廟', '題游仙閣白公廟', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["仙冠輕舉竟何之，薜荔緣堦竹映祠。","甲子不知風馭日，朝昏唯見雨來時。","霓旌翠蓋終難遇，流水青山空所思。","逐客自憐雙鬢改，梵香多負白雲期。"]', '["仙冠轻舉竟何之，薜荔緣堦竹映祠。","甲子不知风馭日，朝昏唯见雨来时。","霓旌翠蓋終难遇，流水青山空所思。","逐客自怜雙鬢改，梵香多負白云期。"]', '诗', 'shi', '', NULL, '題遊仙閣白公廟 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9259cb41-d39c-4d4d-b7b4-a231bc70e4d2', '送鄭正則漢陽迎婦', '送鄭正則漢陽迎婦', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["錦字相催鳥急飛，郎君暫脫老萊衣。","遙想雙眉待人畫，行看五馬送潮歸。","望夫山上花猶發，新婦江邊鶯未稀。","令秩和鳴真可羨，此行誰道負春輝。"]', '["錦字相催鸟急飞，郎君暫脫老萊衣。","遙想雙眉待人畫，行看五马送潮归。","望夫山上花猶發，新婦江邊鶯未稀。","令秩和鳴真可羨，此行誰道負春輝。"]', '诗', 'shi', '', NULL, '送鄭正則漢陽迎婦 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6dae641-c374-41d8-9195-525ac6869f79', '送皇甫冉往安宜', '送皇甫冉往安宜', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["江臯盡日唯煙水，君向白田何日歸。","楚地蒹葭連海逈，隋朝楊柳映堤稀。","津樓故市無行客，山館荒城閉落暉。","若問行人與征戰，使君雙淚定霑衣。"]', '["江臯尽日唯煙水，君向白田何日归。","楚地蒹葭連海逈，隋朝楊柳映堤稀。","津楼故市無行客，山館荒城閉落暉。","若问行人與征戰，使君雙泪定霑衣。"]', '诗', 'shi', '', NULL, '送皇甫冉往安宜 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f250e306-a578-4bb0-bdef-066a2be420fb', '晚發咸陽寄同院遺補', '晚發咸陽寄同院遺補', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["征戰初休草又衰，咸陽晚眺淚堪垂。","去路全無千里客，秋田不見五陵兒。","秦家故事隨流水，漢代高墳對石碑。","回首青山獨不語，羨君談笑萬年枝。"]', '["征戰初休草又衰，咸陽晚眺泪堪垂。","去路全無千里客，秋田不见五陵兒。","秦家故事隨流水，漢代高墳对石碑。","回首青山独不語，羨君談笑万年枝。"]', '诗', 'shi', '', NULL, '晚發咸陽寄同院遺補 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27acb13b-76e1-46ee-a681-148fc96b24b6', '早秋京口旅泊章侍御寄書相問因以贈之時七夕', '早秋京口旅泊章侍御寄书相问因以贈之时七夕', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["移家避寇逐行舟，厭見南徐江水流。","吳越征徭非舊日，秣陵凋弊不宜秋。","千家閉戶無砧杵，七夕何人望斗牛。","祗有同時驄馬客，偏宜尺牘問窮愁。"]', '["移家避寇逐行舟，厭见南徐江水流。","吳越征徭非旧日，秣陵凋弊不宜秋。","千家閉戶無砧杵，七夕何人望斗牛。","祗有同时驄马客，偏宜尺牘问窮愁。"]', '诗', 'shi', '', NULL, '早秋京口旅泊章侍御寄書相問因以贈之時七夕 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fad0b1d2-0982-4e21-a0f7-9fbde68bd3e3', '秋曉招隱寺東峰茶宴送內弟閻伯均歸江州', '秋晓招隐寺东峰茶宴送內弟閻伯均归江州', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["萬畦新稻傍山村，數里深松到寺門。","幸有香茶留穉子，不堪秋草送王孫。","煙塵怨別唯愁隔，井邑蕭條誰忍論。","莫怪臨歧獨垂淚，魏舒偏念外家恩。"]', '["万畦新稻傍山村，數里深松到寺门。","幸有香茶留穉子，不堪秋草送王孫。","煙塵怨別唯愁隔，井邑蕭條誰忍論。","莫怪臨歧独垂泪，魏舒偏念外家恩。"]', '诗', 'shi', '', NULL, '秋曉招隱寺東峰茶宴送內弟閻伯均歸江州 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a3d6317-14e6-4974-85bf-696d58458a5e', '送嚴員外', '送嚴員外', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["春風倚櫂闔閭城，水國春寒陰復晴。","細雨濕衣看不見，閑花落地聽無聲。","日斜江上孤帆影，草綠湖南萬里情。","君去若逢相識問，青袍今已誤儒生。"]', '["春风倚櫂闔閭城，水国春寒陰复晴。","細雨濕衣看不见，闲花落地听無声。","日斜江上孤帆影，草綠湖南万里情。","君去若逢相識问，青袍今已誤儒生。"]', '诗', 'shi', '', NULL, '送嚴員外 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8b615ec-00f5-4b3c-bcb7-8435e10014aa', '赴南中留別褚七少府湖上林亭', '赴南中留別褚七少府湖上林亭', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["種田東郭傍春陂，萬事無情把釣絲。","綠竹放侵行逕裏，青山常對卷簾時。","紛紛花發門空閉，寂寂鶯啼日更遲。","從此別君千萬里，白雲流水憶佳期。"]', '["種田东郭傍春陂，万事無情把釣絲。","綠竹放侵行逕裏，青山常对卷簾时。","紛紛花發门空閉，寂寂鶯啼日更遲。","從此別君千万里，白云流水憶佳期。"]', '诗', 'shi', '', NULL, '赴南中留別褚七少府湖上林亭 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47037677-642e-4c75-a11d-36d3e89d9c8d', '與從弟正字從兄兵曹宴集林園', '與從弟正字從兄兵曹宴集林园', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["竹窓松戶有佳期，美酒香茶慰所思。","輔嗣外生還解易，惠連羣從總能詩。","簷前花落春深後，谷裏鶯啼日暮時。","去路歸程仍待月，垂韁不控馬行遲。"]', '["竹窓松戶有佳期，美酒香茶慰所思。","輔嗣外生還解易，惠連羣從總能诗。","簷前花落春深後，谷裏鶯啼日暮时。","去路归程仍待月，垂韁不控马行遲。"]', '诗', 'shi', '', NULL, '與從弟正字從兄兵曹宴集林園 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fee12dd9-a381-4288-903b-129416897f9b', '酬皇甫十六侍御曾見寄', '酬皇甫十六侍御曾见寄', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["自顧衰容累玉除，忽承優詔赴銅魚。","江頭鳥避青旄節，城裏人迎露網車。","長沙地近悲才子，古郡山多憶舊廬。","更枉新詩思何苦，離騷愁處亦無如。"]', '["自顧衰容累玉除，忽承優詔赴銅鱼。","江头鸟避青旄節，城裏人迎露網车。","长沙地近悲才子，古郡山多憶旧廬。","更枉新诗思何苦，離騷愁处亦無如。"]', '诗', 'shi', '', NULL, '酬皇甫十六侍御曾見寄 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3092fea-a23f-44ab-a0da-65be3e4e1fae', '暮春宜陽郡齋愁坐忽枉劉七侍御新詩因以酬答', '暮春宜陽郡斋愁坐忽枉劉七侍御新诗因以酬答', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["子規夜夜[啼]櫧葉，遠道逢春半是愁。","芳草伴人還易老，落花隨水亦東流。","山臨睥睨恆多雨，地接瀟湘畏及秋。","唯羨君爲周柱史，手持黃紙到滄洲。"]', '["子規夜夜[啼]櫧葉，远道逢春半是愁。","芳草伴人還易老，落花隨水亦东流。","山臨睥睨恆多雨，地接瀟湘畏及秋。","唯羨君爲周柱史，手持黄紙到滄洲。"]', '诗', 'shi', '', NULL, '暮春宜陽郡齋愁坐忽枉劉七侍御新詩因以酬答 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df2faabf-b5ef-4c87-8091-da1a91285122', '送舍弟', '送舍弟', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["諸謝偏推永嘉守，三何獨許水曹郎。","老兄鄙思難儔匹，令弟清詞堪比量。","疊嶂入雲藏古寺，高秋背月轉南湘。","定知馬上多新句，早寄袁溪當八行。"]', '["諸謝偏推永嘉守，三何独許水曹郎。","老兄鄙思难儔匹，令弟清词堪比量。","叠嶂入云藏古寺，高秋背月轉南湘。","定知马上多新句，早寄袁溪當八行。"]', '诗', 'shi', '', NULL, '送舍弟 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('beee5922-6237-4c9a-af25-43a4cb4274e6', '送從弟永任饒州錄事參軍', '送從弟永任饒州錄事參軍', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["一官萬里向千溪，水宿山行魚浦西。","日晚長煙高岸近，天寒積雪遠峰低。","蘆花渚裏鴻相呌，苦竹叢邊猨暗啼。","聞道慈親倚門待，到時蘭葉正萋萋。"]', '["一官万里向千溪，水宿山行鱼浦西。","日晚长煙高岸近，天寒積雪远峰低。","蘆花渚裏鴻相呌，苦竹叢邊猨暗啼。","闻道慈親倚门待，到时蘭葉正萋萋。"]', '诗', 'shi', '', NULL, '送從弟永任饒州錄事參軍 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c611bf84-57f9-44ee-ac22-d7a270a21190', '送馬將軍奏事畢歸滑州使幕', '送马將軍奏事畢归滑州使幕', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["吳門別後蹈滄州，帝里相逢俱白頭。","自歎馬卿常帶病，還嗟李廣未封侯。","棠梨宮裏瞻龍衮，細柳營前著豹裘。","想到滑臺桑葉落，黃河東注荻花秋。"]', '["吳门別後蹈滄州，帝里相逢俱白头。","自歎马卿常带病，還嗟李廣未封侯。","棠梨宮裏瞻龙衮，細柳營前著豹裘。","想到滑台桑葉落，黄河东注荻花秋。"]', '诗', 'shi', '', NULL, '送馬將軍奏事畢歸滑州使幕 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25e0e52b-b822-44f8-9cc5-4ffa1a63948e', '聞逝者自驚', '闻逝者自驚', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["亦知死是人間事，年老聞之心自疑。","黃卷清琴總爲累，落花流水共添悲。","願將從藥看真訣，又欲休官就本師。","兒女眼前難喜捨，彌憐雙鬢漸如絲。"]', '["亦知死是人间事，年老闻之心自疑。","黄卷清琴總爲累，落花流水共添悲。","願將從藥看真訣，又欲休官就本師。","兒女眼前难喜捨，彌怜雙鬢漸如絲。"]', '诗', 'shi', '', NULL, '聞逝者自驚 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6038ff33-cb0f-4ab7-82bd-c603b030c1bb', '傷歙州陳二使君', '傷歙州陳二使君', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["憐君辭滿臥滄洲，一旦云亡萬事休。","慈母斷腸妻獨泣，寒雲慘色水空流。","江村故老長懷惠，山路孤猨亦共愁。","寂寞荒墳近漁浦，野松孤月即千秋。"]', '["怜君辞满臥滄洲，一旦云亡万事休。","慈母斷腸妻独泣，寒云慘色水空流。","江村故老长懷惠，山路孤猨亦共愁。","寂寞荒墳近漁浦，野松孤月即千秋。"]', '诗', 'shi', '', NULL, '傷歙州陳二使君 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb4f4170-b86e-44bf-813e-516858bef701', '白田西憶楚州使君弟', '白田西憶楚州使君弟', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["山陽郭裏無潮，野水自向新橋。","魚網平鋪荷葉，鷺鷥閑步稻苗。","秣陵歸人惆悵，楚地連山寂寥。","却憶士龍賓閣，清琴綠竹蕭蕭。"]', '["山陽郭裏無潮，野水自向新橋。","鱼網平鋪荷葉，鷺鷥闲步稻苗。","秣陵归人惆悵，楚地連山寂寥。","却憶士龙賓閣，清琴綠竹蕭蕭。"]', '诗', 'shi', '', NULL, '白田西憶楚州使君弟 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ae993ab-d22e-4fd2-ab42-db08325f8452', '送陸澧還吳中', '送陸澧還吳中', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["瓜步寒潮送客，楊花暮雨霑衣。","故鄉南望何處，春水連天獨歸。"]', '["瓜步寒潮送客，楊花暮雨霑衣。","故乡南望何处，春水連天独归。"]', '诗', 'shi', '', NULL, '送陸澧還吳中 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('098ed74c-c5fa-4944-9078-b76bd958fbba', '春日憶家', '春日憶家', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["自覺勞鄉夢，無人見客心。","空餘庭草色，日日伴愁襟。"]', '["自覺勞乡梦，無人见客心。","空餘庭草色，日日伴愁襟。"]', '诗', 'shi', '', NULL, '春日憶家 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adc558c2-6360-4480-be16-abc304c00cb4', '遠寺鐘', '远寺鐘', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["疎鐘何處來，度竹兼拂水。","漸逐微風聲，依依猶在耳。"]', '["疎鐘何处来，度竹兼拂水。","漸逐微风声，依依猶在耳。"]', '诗', 'shi', '', NULL, '遠寺鐘 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cdca6e7-551e-4198-a27f-f392fafb9d63', '白鷺', '白鷺', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["江南淥水多，顧影逗輕波。","落日秦雲裏，山高奈若何。"]', '["江南淥水多，顧影逗轻波。","落日秦云裏，山高奈若何。"]', '诗', 'shi', '', NULL, '白鷺 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97808292-ac16-4d5e-bee4-a18466d6f570', '夜宴南陵留別', '夜宴南陵留別', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["雪滿前庭月色閑，主人留客未能還。","預愁明日相思處，匹馬千山與萬山。"]', '["雪满前庭月色闲，主人留客未能還。","預愁明日相思处，匹马千山與万山。"]', '诗', 'shi', '', NULL, '夜宴南陵留別 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00b580c8-f454-4c84-bd31-82181647e0f8', '題前溪館', '題前溪館', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["兩年謫宦在江西，舉目雲山要自迷。","今日始知風土異，潯陽南去鷓鴣啼。"]', '["兩年謫宦在江西，舉目云山要自迷。","今日始知风土異，潯陽南去鷓鴣啼。"]', '诗', 'shi', '', NULL, '題前溪館 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc772e4d-25ce-4aa6-8efb-7c1624eec584', '過烏公山寄錢起員外', '過烏公山寄錢起員外', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["雨過青山猨呌時，愁人淚點石榴枝。","無端王事還相繫，腸斷蒹葭君不知。"]', '["雨過青山猨呌时，愁人泪点石榴枝。","無端王事還相繫，腸斷蒹葭君不知。"]', '诗', 'shi', '', NULL, '過烏公山寄錢起員外 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('861ef4ac-6a0f-4307-a083-e0175c488c75', '寄王舍人竹樓', '寄王舍人竹楼', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["傲吏身閑笑五侯，西江取竹起高樓。","南風不用蒲葵扇，紗帽閑眠對水鷗。"]', '["傲吏身闲笑五侯，西江取竹起高楼。","南风不用蒲葵扇，紗帽闲眠对水鷗。"]', '诗', 'shi', '', NULL, '寄王舍人竹樓 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f6e313b-5dbb-49b5-b3f9-5df77fff1cbf', '韋潤州後亭海榴', '韋潤州後亭海榴', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["江上年年小雪遲，年光獨報海榴知。","寂寂山城風日暖，謝公含笑向南枝。"]', '["江上年年小雪遲，年光独報海榴知。","寂寂山城风日暖，謝公含笑向南枝。"]', '诗', 'shi', '', NULL, '韋潤州後亭海榴 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a030fce-75ee-45a4-aa0c-a08f08411c58', '送崔十一弟歸北京', '送崔十一弟归北京', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["潘郎美貌謝公詩，銀印花驄年少時。","楚地江臯一爲別，晉山沙水獨相思。"]', '["潘郎美貌謝公诗，銀印花驄年少时。","楚地江臯一爲別，晉山沙水独相思。"]', '诗', 'shi', '', NULL, '送崔十一弟歸北京 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5b34377-94f1-4b05-9a2c-88743f3c5507', '訪韓司空不遇', '訪韓司空不遇', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["圖畫風流似長康，文詞體格效陳王。","蓬萊對去歸常晚，叢竹閑飛滿夕陽。"]', '["圖畫风流似长康，文词體格效陳王。","蓬萊对去归常晚，叢竹闲飞满夕陽。"]', '诗', 'shi', '', NULL, '訪韓司空不遇 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5953a86-c1c2-432a-8e73-cfb2ab364071', '題道虔上人竹房', '題道虔上人竹房', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["詩思禪心共竹閑，任他流水向人間。","手持如意高窓裏，斜日沿江千萬山。"]', '["诗思禪心共竹闲，任他流水向人间。","手持如意高窓裏，斜日沿江千万山。"]', '诗', 'shi', '', NULL, '題道虔上人竹房 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b51c9f56-c13f-487f-846f-90ec85b1b7ac', '秋朝木芙蓉', '秋朝木芙蓉', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["水面芙蓉秋已衰，繁條到是著花時。","平明露滴垂紅臉，似有朝愁暮落悲。"]', '["水面芙蓉秋已衰，繁條到是著花时。","平明露滴垂紅臉，似有朝愁暮落悲。"]', '诗', 'shi', '', NULL, '秋朝木芙蓉 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f26ba25-f4d8-4154-ad57-55c52c23dbf2', '袁江口憶王司勳王吏部二郎中起居十七弟', '袁江口憶王司勳王吏部二郎中起居十七弟', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["京華不啻三千里，客淚如今一萬雙。","若個最爲相憶處，青楓黃竹入袁江。"]', '["京华不啻三千里，客泪如今一万雙。","若個最爲相憶处，青楓黄竹入袁江。"]', '诗', 'shi', '', NULL, '袁江口憶王司勳王吏部二郎中起居十七弟 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7506cd12-8989-487c-8fcd-ba8bdfabf91b', '答泉州薛播使君重陽日贈酒', '答泉州薛播使君重陽日贈酒', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["欲強登高無力去，籬邊黃菊爲誰開。","共知不是潯陽郡，那得王弘送酒來。"]', '["欲強登高無力去，籬邊黄菊爲誰开。","共知不是潯陽郡，那得王弘送酒来。"]', '诗', 'shi', '', NULL, '答泉州薛播使君重陽日贈酒 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('717fa41a-9749-4852-9fde-9062bd2cf900', '題張公洞', '題張公洞', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["空山杳杳鸞鳳飛，神仙門戶開翠微。","主人白髮雪霞衣，松間留我談玄機。"]', '["空山杳杳鸾鳳飞，神仙门戶开翠微。","主人白髮雪霞衣，松间留我談玄機。"]', '诗', 'shi', '', NULL, '題張公洞 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18b46e80-2f5a-46a6-90c7-04489f737d04', '句', '句', 'b6582665-d9aa-4446-9323-461712ed8a50', '唐', '["水田飛白鷺，夏木囀黃鸝。","白馬撼金珂，紛紛侍從多。","身居驃騎幕，家住滹沱河。","溪北映初星。"]', '["水田飞白鷺，夏木囀黄鸝。","白马撼金珂，紛紛侍從多。","身居驃騎幕，家住滹沱河。","溪北映初星。"]', '诗', 'shi', '', NULL, '句 李嘉祐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('339220a8-d5ec-402c-a634-61b8cfbcbff1', '送泉州李使君之任', '送泉州李使君之任', 'a77de794-b66a-4761-8263-9299b9711106', '唐', '["傍海皆荒服，分符重漢臣。","雲山百越路，市井十洲人。","執玉來朝遠，還珠入貢頻。","連年不見雪，到處即行春。"]', '["傍海皆荒服，分符重漢臣。","云山百越路，市井十洲人。","執玉来朝远，還珠入貢頻。","連年不见雪，到处即行春。"]', '诗', 'shi', '', NULL, '送泉州李使君之任 包何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a323547-6881-41da-b642-fed14eca69de', '和孟虔州閑齋即事', '和孟虔州闲斋即事', 'a77de794-b66a-4761-8263-9299b9711106', '唐', '["古郡鄰江嶺，公庭半薜蘿。","府僚閑不入，山鳥靜偏過。","睥睨臨花柳，欄干枕芰荷。","麥秋今欲至，君聽兩岐歌。"]', '["古郡鄰江嶺，公庭半薜蘿。","府僚闲不入，山鸟静偏過。","睥睨臨花柳，欄干枕芰荷。","麦秋今欲至，君听兩岐歌。"]', '诗', 'shi', '', NULL, '和孟虔州閑齋即事 包何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a493fa7e-84de-40f6-b655-46677ab9ff46', '同李郎中淨律院梡子樹', '同李郎中淨律院梡子樹', 'a77de794-b66a-4761-8263-9299b9711106', '唐', '["本梡稀難識，沙門種則生。","葉殊經寫字，子爲佛稱名。","濾水澆新長，燃燈暖更榮。","亭亭無別意，只是勸修行。"]', '["本梡稀难識，沙门種則生。","葉殊經寫字，子爲佛稱名。","濾水澆新长，燃灯暖更榮。","亭亭無別意，只是勸修行。"]', '诗', 'shi', '', NULL, '同李郎中淨律院梡子樹 包何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('969d645c-9a62-4480-97a2-10621a949360', '同閻伯均宿道士觀有述', '同閻伯均宿道士观有述', 'a77de794-b66a-4761-8263-9299b9711106', '唐', '["南國佳人去不迴，洛陽才子更須媒。","綺琴白雪無心弄，羅幌清風到曉開。","冉冉修篁依戶牖，迢迢列宿映樓臺。","縱令奔月成仙去，且作行雲入夢來。"]', '["南国佳人去不迴，洛陽才子更須媒。","綺琴白雪無心弄，羅幌清风到晓开。","冉冉修篁依戶牖，迢迢列宿映楼台。","縱令奔月成仙去，且作行云入梦来。"]', '诗', 'shi', '', NULL, '同閻伯均宿道士觀有述 包何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67060c60-5264-4524-99a9-aa12ae3c641a', '送烏程王明府貶巴江', '送烏程王明府貶巴江', 'a77de794-b66a-4761-8263-9299b9711106', '唐', '["一片孤帆無四鄰，北風吹過五湖濱。","相看盡是江南客，獨有君爲嶺外人。"]', '["一片孤帆無四鄰，北风吹過五湖濱。","相看尽是江南客，独有君爲嶺外人。"]', '诗', 'shi', '', NULL, '送烏程王明府貶巴江 包何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2897a95-99ad-4753-a6f2-2136d02d696e', '同舍弟佶班韋二員外秋苔對之成詠', '同舍弟佶班韋二員外秋苔对之成詠', 'a77de794-b66a-4761-8263-9299b9711106', '唐', '["每看苔蘚色，如向簿書閑。","幽思纏芳樹，高情寄遠山。","雨痕連地綠，日色出林斑。","却笑興公賦，臨危滑石間。"]', '["每看苔蘚色，如向簿书闲。","幽思纏芳樹，高情寄远山。","雨痕連地綠，日色出林斑。","却笑兴公賦，臨危滑石间。"]', '诗', 'shi', '', NULL, '同舍弟佶班韋二員外秋苔對之成詠 包何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8f5187e-4b1c-4be1-9abe-8fa0c2275009', '送王汶宰江陰', '送王汶宰江陰', 'a77de794-b66a-4761-8263-9299b9711106', '唐', '["郡北乘流去，花間竟日行。","海魚朝滿市，江鳥夜喧城。","止酒非關病，援琴不在聲。","應緣五斗米，數日滯淵明。"]', '["郡北乘流去，花间竟日行。","海鱼朝满市，江鸟夜喧城。","止酒非关病，援琴不在声。","應緣五斗米，數日滯淵明。"]', '诗', 'shi', '', NULL, '送王汶宰江陰 包何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50cada64-f5ae-4538-a363-474c0ab3a296', '和苗員外寓直中書', '和苗員外寓直中书', 'a77de794-b66a-4761-8263-9299b9711106', '唐', '["朝列稱多士，君家有二難。","貞爲臺裏柏，芳作省中蘭。","夜宿分曹闊，晨趨接武歡。","每憐雙闕下，鴈序入鴛鸞。"]', '["朝列稱多士，君家有二难。","貞爲台裏柏，芳作省中蘭。","夜宿分曹闊，晨趨接武歡。","每怜雙闕下，鴈序入鴛鸾。"]', '诗', 'shi', '', NULL, '和苗員外寓直中書 包何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1f7c92e-a574-4324-9c60-8b87a2f2a94f', '闕下芙蓉', '闕下芙蓉', 'a77de794-b66a-4761-8263-9299b9711106', '唐', '["一人理國致昇平，萬物呈祥助聖明。","天上河從闕下過，江南花向殿前生。","慶雲垂蔭開難落，湛露爲珠滿不傾。","更對樂懸張宴處，歌工欲奏採蓮聲。"]', '["一人理国致昇平，万物呈祥助聖明。","天上河從闕下過，江南花向殿前生。","慶云垂蔭开难落，湛露爲珠满不傾。","更对乐懸張宴处，歌工欲奏採蓮声。"]', '诗', 'shi', '', NULL, '闕下芙蓉 包何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('601b5495-9683-460a-9ef7-f27c3965cef1', '江上田家', '江上田家', 'a77de794-b66a-4761-8263-9299b9711106', '唐', '["近海川原薄，人家本自稀。","黍苗期臘酒，霜葉是寒衣。","市井誰相識，漁樵夜始歸。","不須騎馬問，恐畏狎鷗飛。"]', '["近海川原薄，人家本自稀。","黍苗期臘酒，霜葉是寒衣。","市井誰相識，漁樵夜始归。","不須騎马问，恐畏狎鷗飞。"]', '诗', 'shi', '', NULL, '江上田家 包何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5f9b99b-fe97-4eef-8fea-30b45125aa97', '送韋侍御奉使江嶺諸道催青苗錢', '送韋侍御奉使江嶺諸道催青苗錢', 'a77de794-b66a-4761-8263-9299b9711106', '唐', '["近遠從王事，南行處處經。","手持霜簡白，心在夏苗青。","迴鴈書應報，愁猨夜屢聽。","因君使絕域，方物盡來庭。"]', '["近远從王事，南行处处經。","手持霜簡白，心在夏苗青。","迴鴈书應報，愁猨夜屢听。","因君使絕域，方物尽来庭。"]', '诗', 'shi', '', NULL, '送韋侍御奉使江嶺諸道催青苗錢 包何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dbed00f-b5d4-4276-8de1-d65054b3d4a7', '和程員外春日東郊即事', '和程員外春日东郊即事', 'a77de794-b66a-4761-8263-9299b9711106', '唐', '["郎官休浣憐遲日，野老歡娛爲有年。","幾處折花驚蝶夢，數家留葉待蠶眠。","藤垂宛地縈珠履，泉迸侵堦浸綠錢。","直到閉關朝謁去，鶯聲不散柳含煙。"]', '["郎官休浣怜遲日，野老歡娛爲有年。","幾处折花驚蝶梦，數家留葉待蠶眠。","藤垂宛地縈珠履，泉迸侵堦浸綠錢。","直到閉关朝謁去，鶯声不散柳含煙。"]', '诗', 'shi', '', NULL, '和程員外春日東郊即事 包何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fc07309-faba-489d-924d-9c46e950a35c', '裴端公使院賦得隔簾見春雨', '裴端公使院賦得隔簾见春雨', 'a77de794-b66a-4761-8263-9299b9711106', '唐', '["細雨未成霖，垂簾但覺陰。","唯看上砌濕，不遣入簷深。","度隟霑霜簡，因風潤綺琴。","須移戶外屨，簷溜夜相侵。"]', '["細雨未成霖，垂簾但覺陰。","唯看上砌濕，不遣入簷深。","度隟霑霜簡，因风潤綺琴。","須移戶外屨，簷溜夜相侵。"]', '诗', 'shi', '', NULL, '裴端公使院賦得隔簾見春雨 包何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b48efd98-7757-45e7-88d9-f9bbcadadc51', '相里使君第七男生日', '相里使君第七男生日', 'a77de794-b66a-4761-8263-9299b9711106', '唐', '["取妻生子復生男，獨有君家衆所談。","荀氏八龍唯欠一，桓山四鳳已過三。","他時幹蠱聲名著，今日懸弧宴樂酣。","誰道衆賢能繼體，須知箇箇出於藍。"]', '["取妻生子复生男，独有君家衆所談。","荀氏八龙唯欠一，桓山四鳳已過三。","他时幹蠱声名著，今日懸弧宴乐酣。","誰道衆賢能繼體，須知箇箇出於藍。"]', '诗', 'shi', '', NULL, '相里使君第七男生日 包何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13603ba0-f3e4-43a0-adb6-eb8f9dc839ca', '同諸公尋李方直不遇', '同諸公尋李方直不遇', 'a77de794-b66a-4761-8263-9299b9711106', '唐', '["聞說到揚州，吹簫憶舊遊。","人來多不見，莫是上迷樓。"]', '["闻说到揚州，吹簫憶旧游。","人来多不见，莫是上迷楼。"]', '诗', 'shi', '', NULL, '同諸公尋李方直不遇 包何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e3a1fc2-0e5b-4e24-818e-d91c7f84c403', '婺州留別鄧使君', '婺州留別鄧使君', 'a77de794-b66a-4761-8263-9299b9711106', '唐', '["西掖馳名久，東陽出守時。","江山婺女分，風月隱侯詩。","別恨雙溪急，留歡五馬遲。","迴舟映沙嶼，未遠剩相思。"]', '["西掖驰名久，东陽出守时。","江山婺女分，风月隐侯诗。","別恨雙溪急，留歡五马遲。","迴舟映沙嶼，未远剩相思。"]', '诗', 'shi', '', NULL, '婺州留別鄧使君 包何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a8dc382-dabc-4d44-933a-a9cd5d1d198f', '寄楊侍御', '寄楊侍御', 'a77de794-b66a-4761-8263-9299b9711106', '唐', '["一官何幸得同時，十載無媒獨見遺。","今日不論腰下組，請君看取鬢邊絲。"]', '["一官何幸得同时，十載無媒独见遺。","今日不論腰下組，請君看取鬢邊絲。"]', '诗', 'shi', '', NULL, '寄楊侍御 包何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ab01ce4-3218-4299-9a70-5eec67eb1501', '賦得秤送孟孺卿', '賦得秤送孟孺卿', 'a77de794-b66a-4761-8263-9299b9711106', '唐', '["願以金秤鎚，因君贈別離。","鉤懸新月吐，衡舉衆星隨。","掌握須平執，錙銖必盡知。","由來投分審，莫放弄權移。"]', '["願以金秤鎚，因君贈別離。","鉤懸新月吐，衡舉衆星隨。","掌握須平執，錙銖必尽知。","由来投分審，莫放弄權移。"]', '诗', 'shi', '', NULL, '賦得秤送孟孺卿 包何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5a1b0dc-92fd-41ad-aa63-3bb3b4c772f7', '長安曉望寄崔補闕', '长安晓望寄崔補闕', 'a77de794-b66a-4761-8263-9299b9711106', '唐', '["迢遞山河擁帝京，參差宮殿接雲平。","風吹曉漏經長樂，柳帶晴煙出禁城。","天淨笙歌臨路發，日高車馬隔塵行。","自憐久滯諸生列，未得金閨籍姓名。"]', '["迢遞山河擁帝京，參差宮殿接云平。","风吹晓漏經长乐，柳带晴煙出禁城。","天淨笙歌臨路發，日高车马隔塵行。","自怜久滯諸生列，未得金閨籍姓名。"]', '诗', 'shi', '', NULL, '長安曉望寄崔補闕 包何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1df593c6-0623-4de8-b8a5-af33274f0bb6', '送蕭穎士赴東府得路字', '送蕭穎士赴东府得路字', 'e672d57c-eba7-44f1-8b0f-d5e59af872b3', '唐', '["子欲適東周，門人盈岐路。","高標信難仰，薄官非始務。","綿邈千里途，裴回四郊暮。","征車日云遠，撫己慙深顧。"]', '["子欲適东周，门人盈岐路。","高標信难仰，薄官非始務。","綿邈千里途，裴回四郊暮。","征车日云远，撫己慙深顧。"]', '诗', 'shi', '', NULL, '送蕭穎士赴東府得路字 賈邕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7482274-6498-487b-bec5-1847f108176b', '送蕭穎士赴東府得適字', '送蕭穎士赴东府得適字', '6110e34f-0f34-431f-8a31-315ecc7f5437', '唐', '["大名掩諸古，獨斷無不適。","德遂天下宗，官爲幕中客。","驪山浮雲散，灞岸零雨夕。","請業非遠期，圓光再生魄。"]', '["大名掩諸古，独斷無不適。","德遂天下宗，官爲幕中客。","驪山浮云散，灞岸零雨夕。","請業非远期，圓光再生魄。"]', '诗', 'shi', '', NULL, '送蕭穎士赴東府得適字 劉舟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34d2f706-800b-4608-8ea2-2588e9c32644', '送蕭穎士赴東府得離字', '送蕭穎士赴东府得離字', '52c31212-5700-4a7e-a1e9-0c2dec05e1a8', '唐', '["大德詎可擬，高梧有長離。","素懷經綸具，昭世猶安卑。","落日去關外，悠悠隔山陂。","我心如浮雲，千里相追隨。"]', '["大德詎可擬，高梧有长離。","素懷經綸具，昭世猶安卑。","落日去关外，悠悠隔山陂。","我心如浮云，千里相追隨。"]', '诗', 'shi', '', NULL, '送蕭穎士赴東府得離字 長孫鑄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70847d6a-a1e9-4b6f-a904-25924ca4c875', '送蕭穎士赴東府得還字', '送蕭穎士赴东府得還字', '85209d40-29d3-4d0e-9432-bb8eb0402fc3', '唐', '["夫子高世蹟，時人不可攀。","今予亦云幸，謬得承溫顏。","良策資入幕，遂行從近關。","青春灞亭別，此去何時還。"]', '["夫子高世蹟，时人不可攀。","今予亦云幸，謬得承溫顏。","良策資入幕，遂行從近关。","青春灞亭別，此去何时還。"]', '诗', 'shi', '', NULL, '送蕭穎士赴東府得還字 房白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f272b01-b1f7-44cd-8a4f-866e6efaf0ff', '送蕭穎士赴東府得引字', '送蕭穎士赴东府得引字', 'ba997d81-0da2-4a32-93a3-de4220fa722c', '唐', '["吾見夫子德，誰云習相近。","數仞不可窺，言味終難盡。","處喧慮常澹，作吏心亦隱。","更有嵩少峰，東南爲勝引。"]', '["吾见夫子德，誰云習相近。","數仞不可窺，言味終难尽。","处喧慮常澹，作吏心亦隐。","更有嵩少峰，东南爲勝引。"]', '诗', 'shi', '', NULL, '送蕭穎士赴東府得引字 元晟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cc8c077-d931-4eb2-85fd-4fe1bfdb5810', '送蕭穎士赴東府得淺字', '送蕭穎士赴东府得淺字', '08c706ac-24fb-42bd-8b41-daf93fdb2db5', '唐', '["吾師繼微言，贊述在墳典。","寸祿聊自資，平生宦情鮮。","逶遲東州路，春草深復淺。","日遠夫子門，中心曷由展。"]', '["吾師繼微言，贊述在墳典。","寸祿聊自資，平生宦情鲜。","逶遲东州路，春草深复淺。","日远夫子门，中心曷由展。"]', '诗', 'shi', '', NULL, '送蕭穎士赴東府得淺字 劉太沖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed0a8f5b-76c8-4fc8-aa9d-4b45fe3a18eb', '送蕭穎士赴東府得草字', '送蕭穎士赴东府得草字', '7b7d37c1-2c11-45f8-863c-5f5114e1f570', '唐', '["天生良史筆，浪跡擅文藻。","中夏授參謀，東夷願聞道。","行軒翫春日，餞席藉芳草。","幸得師季良，欣留篋笥寶。"]', '["天生良史笔，浪跡擅文藻。","中夏授參謀，东夷願闻道。","行軒翫春日，餞席藉芳草。","幸得師季良，欣留篋笥寶。"]', '诗', 'shi', '', NULL, '送蕭穎士赴東府得草字 姚發 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aba90e40-6a95-49eb-9432-5ef7e17a3ee8', '送蕭穎士赴東府得往字', '送蕭穎士赴东府得往字', '2bb45090-8b6f-48da-8e5e-87709982b8a5', '唐', '["斤溪數畝田，素心擬長往。","繄君曲得引，使我纓俗網。","風塵豈不勞，道義成心賞。","春郊桃李月，忍此戒征兩。"]', '["斤溪數畝田，素心擬长往。","繄君曲得引，使我纓俗網。","风塵豈不勞，道義成心賞。","春郊桃李月，忍此戒征兩。"]', '诗', 'shi', '', NULL, '送蕭穎士赴東府得往字 鄭愕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dad9262-faad-45d2-a3d8-69c51f97ddad', '送蕭穎士赴東府得散字', '送蕭穎士赴东府得散字', 'a52ccb9b-61c5-40a7-9cca-d32224300371', '唐', '["官閑幕府下，聊以任縱誕。","文學魯仲尼，高標嵇中散。","出門時雨潤，對酒春風暖。","感激知己恩，別離魂欲斷。"]', '["官闲幕府下，聊以任縱誕。","文学魯仲尼，高標嵇中散。","出门时雨潤，对酒春风暖。","感激知己恩，別離魂欲斷。"]', '诗', 'shi', '', NULL, '送蕭穎士赴東府得散字 殷少野 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7f47dc5-2dbd-43bd-a851-74c76735992e', '送蕭穎士赴東府得君字', '送蕭穎士赴东府得君字', 'd727969c-ddc1-4fa7-b8df-858d354f46f8', '唐', '["策名十二載，獨立先斯文。","邇來及門者，半已昇青雲。","青雲豈無姿，黃鵠素不羣。","一辭芸香吏，幾歲滄江濆。","散職既不羈，天聽亦昭聞。","雖承急賢詔，未謁陶唐君。","薄俸還自急，此言那足云。","和風媚東郊，時物滋南薰。","蕙草正可摘，豫章猶未分。","宗師忽千里，使我心氛氳。"]', '["策名十二載，独立先斯文。","邇来及门者，半已昇青云。","青云豈無姿，黄鵠素不羣。","一辞芸香吏，幾歲滄江濆。","散職既不羈，天听亦昭闻。","雖承急賢詔，未謁陶唐君。","薄俸還自急，此言那足云。","和风媚东郊，时物滋南薰。","蕙草正可摘，豫章猶未分。","宗師忽千里，使我心氛氳。"]', '诗', 'shi', '', NULL, '送蕭穎士赴東府得君字 鄔載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5082efe-beda-482e-8f57-f88241cdda54', '奉陪韋中丞使君遊鶴林寺', '奉陪韋中丞使君游鹤林寺', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["古寺傳燈久，層城閉閣閑。","香花同法侶，旌斾入深山。","寒磬虛空裏，孤雲起滅間。","謝公憶高臥，徒御欲東還。"]', '["古寺傳灯久，層城閉閣闲。","香花同法侶，旌斾入深山。","寒磬虛空裏，孤云起滅间。","謝公憶高臥，徒御欲东還。"]', '诗', 'shi', '', NULL, '奉陪韋中丞使君遊鶴林寺 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('432d77a0-08de-44b9-a3c4-06db88347496', '奉送杜侍御還京', '奉送杜侍御還京', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["罷戰回龍節，朝天上鳳池。","寒生五湖道，春入萬年枝。","召化多遺愛，胡清已畏知。","懷恩偏感別，墮淚向旌麾。"]', '["罷戰回龙節，朝天上鳳池。","寒生五湖道，春入万年枝。","召化多遺愛，胡清已畏知。","懷恩偏感別，墮泪向旌麾。"]', '诗', 'shi', '', NULL, '奉送杜侍御還京 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c4d514a-2b2c-4a60-bdfd-8ad970a85e8a', '酬鄭侍御秋夜見寄', '酬鄭侍御秋夜见寄', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["搖落空林夜，河陽興已生。","未辭公府步，知結遠山情。","高柳風難定，寒泉月助明。","袁公方臥雪，尺素及柴荆。"]', '["搖落空林夜，河陽兴已生。","未辞公府步，知結远山情。","高柳风难定，寒泉月助明。","袁公方臥雪，尺素及柴荆。"]', '诗', 'shi', '', NULL, '酬鄭侍御秋夜見寄 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2d89260-e3b7-4077-aaaa-0a67db01d5b6', '酬竇拾遺秋日見呈', '酬竇拾遺秋日见呈', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["孤城永巷時相見，衰柳閑門日半斜。","欲送近臣朝魏闕，猶憐殘菊在陶家。"]', '["孤城永巷时相见，衰柳闲门日半斜。","欲送近臣朝魏闕，猶怜殘菊在陶家。"]', '诗', 'shi', '', NULL, '酬竇拾遺秋日見呈 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84fccfc1-60e4-4e70-a963-bcd0224c80c9', '韋使君宅海榴詠', '韋使君宅海榴詠', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["淮陽臥理有清風，臘月榴花帶雪紅。","閉閣寂寥常對此，江湖心在數枝中。"]', '["淮陽臥理有清风，臘月榴花带雪紅。","閉閣寂寥常对此，江湖心在數枝中。"]', '诗', 'shi', '', NULL, '韋使君宅海榴詠 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3aa3e06-2bfd-435e-ada7-fbd1a0b015ec', '送普上人還陽羨', '送普上人還陽羨', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["花宮難久別，道者憶千燈。","殘雪入林路，暮山歸寺僧。","日光依嫩草，泉響滴春冰。","何用求方便，看心是一乘。"]', '["花宮难久別，道者憶千灯。","殘雪入林路，暮山归寺僧。","日光依嫩草，泉响滴春冰。","何用求方便，看心是一乘。"]', '诗', 'shi', '', NULL, '送普上人還陽羨 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae5bb0aa-b924-4c04-8363-53ee18269524', '送李中丞歸本道', '送李中丞归本道', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["上將還專席，雙旌復出秦。","關河三晉路，賓從五原人。","孤戍雲連海，平沙雪度春。"]', '["上將還專席，雙旌复出秦。","关河三晉路，賓從五原人。","孤戍云連海，平沙雪度春。"]', '诗', 'shi', '', NULL, '送李中丞歸本道 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9149aa7c-b352-4a0f-aaeb-85ab10403744', '和謝舍人雪夜寓直', '和謝舍人雪夜寓直', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["禁省夜沈沈，春風雪滿林。","滄洲歸客夢，青瑣近臣心。","揮翰宣鳴玉，承恩在賜金。","建章寒漏起，更助掖垣深。"]', '["禁省夜沈沈，春风雪满林。","滄洲归客梦，青瑣近臣心。","揮翰宣鳴玉，承恩在賜金。","建章寒漏起，更助掖垣深。"]', '诗', 'shi', '', NULL, '和謝舍人雪夜寓直 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('803b76e6-7aed-4569-88a8-7cd6c5b74c6a', '尋劉處士', '尋劉处士', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["幾年人不見，林下掩柴關。","留客當清夜，逢君話舊山。","隔城寒杵急，帶月早鴻還。","南陌雖相近，其如隱者閑。"]', '["幾年人不见，林下掩柴关。","留客當清夜，逢君話旧山。","隔城寒杵急，带月早鴻還。","南陌雖相近，其如隐者闲。"]', '诗', 'shi', '', NULL, '尋劉處士 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8cc31e9-6b51-4a37-818b-7891dfb9677c', '哭陸處士', '哭陸处士', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["從此無期見，柴門對雪開。","二毛逢世難，萬恨掩泉臺。","返照空堂夕，孤城弔客迴。","漢家偏訪道，猶畏鶴書來。"]', '["從此無期见，柴门对雪开。","二毛逢世难，万恨掩泉台。","返照空堂夕，孤城弔客迴。","漢家偏訪道，猶畏鹤书来。"]', '诗', 'shi', '', NULL, '哭陸處士 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('189ab60e-c415-4aa2-b883-e6a899426407', '烏程水樓留別', '烏程水楼留別', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["悠悠千里去，惜此一尊同。","客散高樓上，帆飛細雨中。","山程隨遠水，楚思在青楓。","共說前期易，滄波處處同。"]', '["悠悠千里去，惜此一尊同。","客散高楼上，帆飞細雨中。","山程隨远水，楚思在青楓。","共说前期易，滄波处处同。"]', '诗', 'shi', '', NULL, '烏程水樓留別 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a31f052-4673-4acb-b344-3f421bb6980d', '題贈吳門邕上人', '題贈吳门邕上人', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["春山唯一室，獨坐草萋萋。","身寂心成道，花閑鳥自啼。","細泉松徑裏，返景竹林西。","晚與門人別，依依出虎溪。"]', '["春山唯一室，独坐草萋萋。","身寂心成道，花闲鸟自啼。","細泉松徑裏，返景竹林西。","晚與门人別，依依出虎溪。"]', '诗', 'shi', '', NULL, '題贈吳門邕上人 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bdc3e83-80ca-4977-bbc1-cc1e37918e14', '送陸鴻漸山人採茶回', '送陸鴻漸山人採茶回', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["千峯待逋客，香茗復叢生。","採摘知深處，烟霞羨獨行。","幽期山寺遠，野飯石泉清。","寂寂燃燈夜，相思一磬聲。"]', '["千峯待逋客，香茗复叢生。","採摘知深处，烟霞羨独行。","幽期山寺远，野飯石泉清。","寂寂燃灯夜，相思一磬声。"]', '诗', 'shi', '', NULL, '送陸鴻漸山人採茶回 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('997fc4da-ca67-42e2-99c4-7bd68a155c8a', '寄劉員外長卿', '寄劉員外长卿', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["南憶新安郡，千山帶夕陽。","斷猨知夜久，秋草助江長。","疎髮應成素，青松獨耐霜。","愛才稱漢主，題柱待回鄉。"]', '["南憶新安郡，千山带夕陽。","斷猨知夜久，秋草助江长。","疎髮應成素，青松独耐霜。","愛才稱漢主，題柱待回乡。"]', '诗', 'shi', '', NULL, '寄劉員外長卿 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee1af307-1e4b-4b18-a2d9-1194784cae0a', '寄張仲甫', '寄張仲甫', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["悲風生舊浦，雲嶺隔東田。","伏臘同雞黍，柴門閉雪天。","孤村明夜火，稚子候歸船。","靜者心相憶，離居畏度年。"]', '["悲风生旧浦，云嶺隔东田。","伏臘同雞黍，柴门閉雪天。","孤村明夜火，稚子候归船。","静者心相憶，離居畏度年。"]', '诗', 'shi', '', NULL, '寄張仲甫 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('155165e4-9098-48e4-8965-5484a4983d54', '送元侍御充使湖南', '送元侍御充使湖南', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["雲夢南行盡，三湘萬里流。","山川重分手，徒御亦悲秋。","白簡勞王事，清猨助客愁。","離羣復多病，歲晚憶滄洲。"]', '["云梦南行尽，三湘万里流。","山川重分手，徒御亦悲秋。","白簡勞王事，清猨助客愁。","離羣复多病，歲晚憶滄洲。"]', '诗', 'shi', '', NULL, '送元侍御充使湖南 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48703e8c-71bb-4c72-b21f-9dbde75ee5af', '晚至華陰', '晚至华陰', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["臘盡促歸心，行人及華陰。","雲霞仙掌出，松柏古祠深。","野渡冰生岸，寒川燒隔林。","溫泉看漸近，宮樹晚沈沈。"]', '["臘尽促归心，行人及华陰。","云霞仙掌出，松柏古祠深。","野渡冰生岸，寒川燒隔林。","溫泉看漸近，宮樹晚沈沈。"]', '诗', 'shi', '', NULL, '晚至華陰 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bb0cf37-0685-4b52-b9b5-45e959d05e12', '送孔徵士', '送孔徵士', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["谷口山多處，君歸不可尋。","家貧青史在，身老白雲深。","掃雪開松徑，疏泉過竹林。","餘生負丘壑，相送亦何心。"]', '["谷口山多处，君归不可尋。","家貧青史在，身老白云深。","掃雪开松徑，疏泉過竹林。","餘生負丘壑，相送亦何心。"]', '诗', 'shi', '', NULL, '送孔徵士 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a821e55-d4ca-44ff-a15d-a5c15ce0df81', '秋興', '秋兴', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["流螢與落葉，秋晚共紛紛。","返照城中盡，寒砧雨外聞。","離人見衰鬢，獨鶴暮何羣。","楚客在千里，相思看碧雲。"]', '["流螢與落葉，秋晚共紛紛。","返照城中尽，寒砧雨外闻。","離人见衰鬢，独鹤暮何羣。","楚客在千里，相思看碧云。"]', '诗', 'shi', '', NULL, '秋興 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32c87342-3c08-4cff-952c-67eda7fb9d46', '送歸中丞使新羅', '送归中丞使新羅', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["南幰銜恩去，東夷泛海行。","天遙辭上國，水盡到孤城。","已變炎涼氣，仍愁浩淼程。","雲濤不可極，來往見雙旌。"]', '["南幰銜恩去，东夷泛海行。","天遙辞上国，水尽到孤城。","已变炎涼氣，仍愁浩淼程。","云濤不可極，来往见雙旌。"]', '诗', 'shi', '', NULL, '送歸中丞使新羅 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebb316eb-28f4-4a18-9eb2-07ccf943a7eb', '送少微上人東南遊', '送少微上人东南游', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["石梁人不到，獨往更迢迢。","乞食山家少，尋鐘野寺遙。","松門風自掃，瀑布雪難消。","秋夜聞清梵，餘音逐海潮。"]', '["石梁人不到，独往更迢迢。","乞食山家少，尋鐘野寺遙。","松门风自掃，瀑布雪难消。","秋夜闻清梵，餘音逐海潮。"]', '诗', 'shi', '', NULL, '送少微上人東南遊 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffe2114c-a56d-4f43-bae4-49a13ec043e3', '送韋判官赴閩中', '送韋判官赴閩中', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["孤棹閩中客，雙旌海上軍。","路人從北少，海水向南分。","野鶴傷秋別，林猨忌夜聞。","漢家崇亞相，知子遠邀勳。"]', '["孤棹閩中客，雙旌海上軍。","路人從北少，海水向南分。","野鹤傷秋別，林猨忌夜闻。","漢家崇亞相，知子远邀勳。"]', '诗', 'shi', '', NULL, '送韋判官赴閩中 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebb507f6-cdf8-4ab1-bd60-180f62f78338', '送人還荆州', '送人還荆州', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["草色隨驄馬，悠悠同出秦。","水傳雲夢曉，山接洞庭春。","帆影連三峽，猨聲近四隣。","青門一分手，難見杜陵人。"]', '["草色隨驄马，悠悠同出秦。","水傳云梦晓，山接洞庭春。","帆影連三峽，猨声近四隣。","青门一分手，难见杜陵人。"]', '诗', 'shi', '', NULL, '送人還荆州 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5cbb21b-6545-4746-995f-b084fca74d5e', '寄淨虛上人初至雲門', '寄淨虛上人初至云门', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["寒蹤白雲裏，法侶自提攜。","竹徑通城下，松門隔水西。","方同沃洲去，不似武陵迷。","彷彿方知處，高峯是會稽。"]', '["寒蹤白云裏，法侶自提携。","竹徑通城下，松门隔水西。","方同沃洲去，不似武陵迷。","彷彿方知处，高峯是會稽。"]', '诗', 'shi', '', NULL, '寄淨虛上人初至雲門 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b47c9575-fe60-44e4-92f7-94386b4d512f', '春和杜相公移入長興宅奉呈諸宰執', '春和杜相公移入长兴宅奉呈諸宰執', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["欲向幽偏適，還從絕地移。","秦官鼎食貴，堯世土階卑。","戟戶槐陰滿，書窗竹葉垂。","才分午夜漏，遙隔萬年枝。","北闕深恩在，東林遠夢知。","日斜門掩暎，山遠樹參差。","論道齊鴛翼，題詩憶鳳池。","從公亦何幸，長與珮聲隨。"]', '["欲向幽偏適，還從絕地移。","秦官鼎食貴，堯世土階卑。","戟戶槐陰满，书窗竹葉垂。","才分午夜漏，遙隔万年枝。","北闕深恩在，东林远梦知。","日斜门掩暎，山远樹參差。","論道齊鴛翼，題诗憶鳳池。","從公亦何幸，长與珮声隨。"]', '诗', 'shi', '', NULL, '春和杜相公移入長興宅奉呈諸宰執 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aad0a00e-1871-44e1-ae2a-1a92eab081b4', '路中口號', '路中口號', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["還鄉不見家，年老眼多淚。","車馬上河橋，城中好天氣。"]', '["還乡不见家，年老眼多泪。","车马上河橋，城中好天氣。"]', '诗', 'shi', '', NULL, '路中口號 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('144c623f-415c-4d5f-8474-dcd38e5ae34b', '山下泉', '山下泉', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["漾漾帶山光，澄澄倒林影。","那知石上喧，却憶山中靜。"]', '["漾漾带山光，澄澄倒林影。","那知石上喧，却憶山中静。"]', '诗', 'shi', '', NULL, '山下泉 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e492d9a-f739-4962-84ec-d377838a6ada', '早朝日寄所知', '早朝日寄所知', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["長安雪夜見歸鴻，紫禁朝天拜舞同。","曙色漸分雙闕下，漏聲遙在百花中。","爐煙乍起開仙仗，玉佩纔成引上公。","共荷發生同雨露，不應黃葉久隨風。"]', '["长安雪夜见归鴻，紫禁朝天拜舞同。","曙色漸分雙闕下，漏声遙在百花中。","爐煙乍起开仙仗，玉佩纔成引上公。","共荷發生同雨露，不應黄葉久隨风。"]', '诗', 'shi', '', NULL, '早朝日寄所知 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98ff9839-2561-494c-a2ad-ed70217d0790', '秋夕寄懷契上人', '秋夕寄懷契上人', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["已見槿花朝委露，獨悲孤鶴在人羣。","真僧出世心無事，靜夜名香手自焚。","窗臨絕澗聞流水，客至孤峯掃白雲。","更想清晨誦經處，獨看松上雪紛紛。"]', '["已见槿花朝委露，独悲孤鹤在人羣。","真僧出世心無事，静夜名香手自焚。","窗臨絕澗闻流水，客至孤峯掃白云。","更想清晨誦經处，独看松上雪紛紛。"]', '诗', 'shi', '', NULL, '秋夕寄懷契上人 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('707975d7-671c-4727-9168-3c6103cbdb20', '張芬見訪郊居作', '張芬见訪郊居作', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["林中雨散早涼生，已有迎秋促織聲。","三徑荒蕪羞對客，十年衰老愧稱兄。","愁心自惜江蘺晚，世事方看木槿榮。","君若罷官攜手日，尋山莫算白雲程。"]', '["林中雨散早涼生，已有迎秋促织声。","三徑荒蕪羞对客，十年衰老愧稱兄。","愁心自惜江蘺晚，世事方看木槿榮。","君若罷官携手日，尋山莫算白云程。"]', '诗', 'shi', '', NULL, '張芬見訪郊居作 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39e6e1d3-5d9e-4b3b-90f6-762839b3b8ed', '贈鑒上人', '贈鑒上人', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["律儀傳教誘，僧臘老煙霄。","樹色依禪誦，泉聲入寂寥。","寶龕經末劫，畫壁見南朝。","深竹風開合，寒潭月動搖。","息心歸靜理，愛道坐中宵。","更欲尋真去，乘船過海潮。"]', '["律儀傳教誘，僧臘老煙霄。","樹色依禪誦，泉声入寂寥。","寶龕經末劫，畫壁见南朝。","深竹风开合，寒潭月动搖。","息心归静理，愛道坐中宵。","更欲尋真去，乘船過海潮。"]', '诗', 'shi', '', NULL, '贈鑒上人 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b27b13fb-d8e2-4231-a109-65068e60437d', '奉寄中書王舍人', '奉寄中书王舍人', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["腰金載筆謁承明，至道安禪得此生。","西掖幾年綸綍貴，東山遙夜薜蘿情。","風傳刻漏星河曙，月上梧桐雨露清。","聖主好文誰爲薦，閉門空賦子虛成。"]', '["腰金載笔謁承明，至道安禪得此生。","西掖幾年綸綍貴，东山遙夜薜蘿情。","风傳刻漏星河曙，月上梧桐雨露清。","聖主好文誰爲薦，閉门空賦子虛成。"]', '诗', 'shi', '', NULL, '奉寄中書王舍人 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ceea715-909e-454c-ad89-5cda63cc119d', '送湯中丞和蕃', '送湯中丞和蕃', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["繼好中司出，天心外國知。","已傳堯雨露，更說漢威儀。","隴上應回首，河源復載馳。","孤峯問徒御，空磧見旌麾。","春草鄉愁起，邊城旅夢移。","莫嗟行遠地，此去荅恩私。"]', '["繼好中司出，天心外国知。","已傳堯雨露，更说漢威儀。","隴上應回首，河源复載驰。","孤峯问徒御，空磧见旌麾。","春草乡愁起，邊城旅梦移。","莫嗟行远地，此去荅恩私。"]', '诗', 'shi', '', NULL, '送湯中丞和蕃 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7677c346-7aca-42c9-9bcd-63de4115339d', '送和西蕃使', '送和西蕃使', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["白簡初分命，黃金已在腰。","恩華通外國，徒御發中朝。","雨雪從邊起，旌旗上隴遙。","暮天沙漠漠，空磧馬蕭蕭。","寒路隨河水，關城見柳條。","和戎先罷戰，知勝霍嫖姚。"]', '["白簡初分命，黄金已在腰。","恩华通外国，徒御發中朝。","雨雪從邊起，旌旗上隴遙。","暮天沙漠漠，空磧马蕭蕭。","寒路隨河水，关城见柳條。","和戎先罷戰，知勝霍嫖姚。"]', '诗', 'shi', '', NULL, '送和西蕃使 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9f6dd33-84b8-4c24-b692-75bfef1237ea', '送王相公赴幽州', '送王相公赴幽州', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["台衮兼戎律，勤憂秉化元。","鳳池東掖寵，龍節北方尊。","長路山河轉，前驅鼓角喧。","人安布時令，地遠荅君恩。","暮日平沙迥，秋風大斾翻。","漁陽在天末，戀別信陵門。"]', '["台衮兼戎律，勤憂秉化元。","鳳池东掖寵，龙節北方尊。","长路山河轉，前驱鼓角喧。","人安布时令，地远荅君恩。","暮日平沙迥，秋风大斾翻。","漁陽在天末，戀別信陵门。"]', '诗', 'shi', '', NULL, '送王相公赴幽州 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a9710da-e7ef-4cce-aad2-f7e3c28558d1', '送徐大夫赴南海', '送徐大夫赴南海', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["舊國當分閫，天涯荅聖私。","大軍傳羽檄，老將拜旌旗。","位重登壇後，恩深弄印時。","何年諫獵賦，今日飲泉詩。","海內求民瘼，城隅見島夷。","由來黃霸去，自有上台期。"]', '["旧国當分閫，天涯荅聖私。","大軍傳羽檄，老將拜旌旗。","位重登壇後，恩深弄印时。","何年諫獵賦，今日饮泉诗。","海內求民瘼，城隅见島夷。","由来黄霸去，自有上台期。"]', '诗', 'shi', '', NULL, '送徐大夫赴南海 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4572699f-cc98-457f-8880-7258b363532a', '贈沛禪師', '贈沛禪師', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["南嶽滿湘沅，吾師經利涉。","身歸沃洲老，名與支公接。","淨教傳荆吳，道緣止漁獵。","觀空色不染，對境心自愜。","室中人寂寞，門外山重疊。","天台積幽夢，早晚當負笈。"]', '["南嶽满湘沅，吾師經利涉。","身归沃洲老，名與支公接。","淨教傳荆吳，道緣止漁獵。","观空色不染，对境心自愜。","室中人寂寞，门外山重叠。","天台積幽梦，早晚當負笈。"]', '诗', 'shi', '', NULL, '贈沛禪師 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d00aa80-4a3e-4909-a123-cfdacd14f390', '萼嶺四望', '萼嶺四望', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["漢家仙仗在咸陽，洛水東流出建章。","野老至今猶望幸，離宮秋樹獨蒼蒼。"]', '["漢家仙仗在咸陽，洛水东流出建章。","野老至今猶望幸，離宮秋樹独蒼蒼。"]', '诗', 'shi', '', NULL, '萼嶺四望 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('048ac046-9aad-43f4-ad68-bf6e68032857', '過劉員外長卿別墅', '過劉員外长卿別墅', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["謝客開山後，郊扉積水通。","江湖千里別，衰老一尊同。","返照寒川滿，平田暮雪空。","滄洲自有趣，不便哭途窮。"]', '["謝客开山後，郊扉積水通。","江湖千里別，衰老一尊同。","返照寒川满，平田暮雪空。","滄洲自有趣，不便哭途窮。"]', '诗', 'shi', '', NULL, '過劉員外長卿別墅 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58205c60-2b77-46dd-adb0-2c98a17b1f60', '遇風雨作', '遇风雨作', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["草草理夜裝，涉江又登陸。","望路殊未窮，指期今已促。","傳呼戒徒馭，振轡轉林麓。","陰雲擁巖端，霑雨當山腹。","震雷如在耳，飛電來照目。","獸跡不敢窺，馬蹄惟務速。","虔心若齋禱，濡體如沐浴。","萬竅相怒號，百泉暗奔瀑。","危梁慮足跌，峻坂憂車覆。","問我何以然，前日愛微祿。","轉知人代事，纓組乃徽束。","向若家居時，安枕春夢熟。","遵途稍已近，候吏來相續。","曉霽心始安，林端見初旭。"]', '["草草理夜裝，涉江又登陸。","望路殊未窮，指期今已促。","傳呼戒徒馭，振轡轉林麓。","陰云擁巖端，霑雨當山腹。","震雷如在耳，飞電来照目。","獸跡不敢窺，马蹄惟務速。","虔心若斋禱，濡體如沐浴。","万竅相怒號，百泉暗奔瀑。","危梁慮足跌，峻坂憂车覆。","问我何以然，前日愛微祿。","轉知人代事，纓組乃徽束。","向若家居时，安枕春梦熟。","遵途稍已近，候吏来相續。","晓霽心始安，林端见初旭。"]', '诗', 'shi', '', NULL, '遇風雨作 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02e93ea0-09d8-40da-9d83-10e2549dc21b', '送商州杜中丞赴任', '送商州杜中丞赴任', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["安康地理接商於，帝命專城總賦輿。","夕拜忽辭青瑣闥，晨裝獨捧紫泥書。","深山古驛分騶騎，芳草閑雲逐隼旟。","綺皓清風千古在，因君一爲謝巖居。"]', '["安康地理接商於，帝命專城總賦輿。","夕拜忽辞青瑣闥，晨裝独捧紫泥书。","深山古驛分騶騎，芳草闲云逐隼旟。","綺皓清风千古在，因君一爲謝巖居。"]', '诗', 'shi', '', NULL, '送商州杜中丞赴任 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('258e8498-75f6-4ec4-968f-9043297c7e68', '送著公歸越', '送著公归越', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["誰能愁此別，到越會相逢。","長憶雲門寺，門前千萬峯。","石牀埋積雪，山路倒枯松。","莫學白居士，無人知去蹤。"]', '["誰能愁此別，到越會相逢。","长憶云门寺，门前千万峯。","石牀埋積雪，山路倒枯松。","莫学白居士，無人知去蹤。"]', '诗', 'shi', '', NULL, '送著公歸越 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71448655-65bb-48ff-95e6-e5ccfbb55b12', '送鄭秀才貢舉', '送鄭秀才貢舉', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["西去意如何，知隨貢士科。","吟詩向月路，驅馬出煙蘿。","晚色寒蕪遠，秋聲候雁多。","自憐歸未得，相送一勞歌。"]', '["西去意如何，知隨貢士科。","吟诗向月路，驱马出煙蘿。","晚色寒蕪远，秋声候雁多。","自怜归未得，相送一勞歌。"]', '诗', 'shi', '', NULL, '送鄭秀才貢舉 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0b22e4e-6160-4470-9a8e-1f03f9bd354f', '錫杖歌送明楚上人歸佛川', '錫杖歌送明楚上人归佛川', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["上人遠自西天至，頭陀行遍南朝寺。","口翻貝葉古字經，手持金策聲泠泠。","護法護身惟振錫，石瀨雲溪深寂寂。","乍來松徑風露寒，遙暎霜天月成魄。","後夜空山禪誦時，寥寥挂在枯樹枝。","真法嘗傳心不住，東西南北隨緣路。","佛川此去何時迴，應真莫便遊天台。"]', '["上人远自西天至，头陀行遍南朝寺。","口翻貝葉古字經，手持金策声泠泠。","護法護身惟振錫，石瀨云溪深寂寂。","乍来松徑风露寒，遙暎霜天月成魄。","後夜空山禪誦时，寥寥挂在枯樹枝。","真法嘗傳心不住，东西南北隨緣路。","佛川此去何时迴，應真莫便游天台。"]', '诗', 'shi', '', NULL, '錫杖歌送明楚上人歸佛川 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1c10c13-909a-48d0-af29-f2cf67732f9c', '玉山嶺上作', '玉山嶺上作', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["悠悠驅匹馬，征路上連岡。","晚翠深雲竇，寒臺淨石梁。","秋花偏似雪，楓葉不禁霜。","愁見前程遠，空郊下夕陽。"]', '["悠悠驱匹马，征路上連岡。","晚翠深云竇，寒台淨石梁。","秋花偏似雪，楓葉不禁霜。","愁见前程远，空郊下夕陽。"]', '诗', 'shi', '', NULL, '玉山嶺上作 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82c60214-4e01-4141-9673-b131fa6978b2', '國子柳博士兼領太常博士輙申賀贈', '国子柳博士兼領太常博士輙申賀贈', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["博士本秦官，求才帖職難。","臨風曲臺淨，對月碧池寒。","講學分陰重，齋祠曉漏殘。","朝衣辨色處，雙綬更宜看。"]', '["博士本秦官，求才帖職难。","臨风曲台淨，对月碧池寒。","講学分陰重，斋祠晓漏殘。","朝衣辨色处，雙綬更宜看。"]', '诗', 'shi', '', NULL, '國子柳博士兼領太常博士輙申賀贈 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('898de8fd-d231-41f0-9607-5ebceb7fbad0', '送裴秀才貢舉', '送裴秀才貢舉', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["儒衣羞此別，去抵漢公卿。","賓貢年猶少，篇章藝已成。","臨流惜暮景，話別起鄉情。","離酌不辭醉，西江春草生。"]', '["儒衣羞此別，去抵漢公卿。","賓貢年猶少，篇章藝已成。","臨流惜暮景，話別起乡情。","離酌不辞醉，西江春草生。"]', '诗', 'shi', '', NULL, '送裴秀才貢舉 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7eab571c-451d-4503-b79b-c2e3b26ec178', '贈老將', '贈老將', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["白草黃雲塞上秋，曾隨驃騎出幷州。","轆轤劒折虯髯白，轉戰功多獨不侯。"]', '["白草黄云塞上秋，曾隨驃騎出幷州。","轆轤劒折虯髯白，轉戰功多独不侯。"]', '诗', 'shi', '', NULL, '贈老將 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66fd0cb9-5f5b-4299-b7bd-a2d03ca5c89e', '銅雀妓', '銅雀妓', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["日暮銅雀迥，秋深玉座清。","蕭森松柏望，委鬱綺羅情。","君恩不再得，妾舞爲誰輕。"]', '["日暮銅雀迥，秋深玉座清。","蕭森松柏望，委鬱綺羅情。","君恩不再得，妾舞爲誰轻。"]', '诗', 'shi', '', NULL, '銅雀妓 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be7d571b-09e2-410f-af17-aab2fbc4c371', '塞下曲', '塞下曲', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["結束浮雲駿，翩翩出從戎。","且憑天子怒，復倚將軍雄。","萬鼓雷殷地，千旗火生風。","日輪駐霜戈，月魄懸琱弓。","青海陣雲匝，黑山兵氣衡。","戰酣太白高，戰罷旄頭空。","萬里不惜死，一朝得成功。","畫圖騏麟閣，入朝明光宮。","大笑向文士，一經何足窮。","古人昧此道，往往成老翁。"]', '["結束浮云駿，翩翩出從戎。","且憑天子怒，复倚將軍雄。","万鼓雷殷地，千旗火生风。","日輪駐霜戈，月魄懸琱弓。","青海陣云匝，黑山兵氣衡。","戰酣太白高，戰罷旄头空。","万里不惜死，一朝得成功。","畫圖騏麟閣，入朝明光宮。","大笑向文士，一經何足窮。","古人昧此道，往往成老翁。"]', '诗', 'shi', '', NULL, '塞下曲 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0111fccd-210b-4e0d-b8f7-c4b09ed8476f', '塞上', '塞上', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["東出盧龍塞，浩然客思孤。","亭堠列萬里，漢兵猶備胡。","邊塵漲北溟，虜騎正南驅。","轉鬬豈長策，和親非遠圖。","惟昔李將軍，按節出皇都。","總戎掃大漠，一戰擒單于。","常懷感激心，願效縱橫謨。","倚劒欲誰語，關河空鬱紆。"]', '["东出盧龙塞，浩然客思孤。","亭堠列万里，漢兵猶備胡。","邊塵漲北溟，虜騎正南驱。","轉鬬豈长策，和親非远圖。","惟昔李將軍，按節出皇都。","總戎掃大漠，一戰擒單于。","常懷感激心，願效縱橫謨。","倚劒欲誰語，关河空鬱紆。"]', '诗', 'shi', '', NULL, '塞上 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b44f7786-9795-41c3-b69e-cee35d6154b9', '薊門行五首 一', '薊门行五首 一', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["薊門逢古老，獨立思氛氳。","一身既零丁，頭鬢白紛紛。","勳庸今已矣，不識霍將軍。"]', '["薊门逢古老，独立思氛氳。","一身既零丁，头鬢白紛紛。","勳庸今已矣，不識霍將軍。"]', '诗', 'shi', '', NULL, '薊門行五首 一 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31796009-cfd9-4a91-8baa-85d8509fe93a', '薊門行五首 二', '薊门行五首 二', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["漢家能用武，開拓窮異域。","戍卒厭糠覈，降胡飽衣食。","關亭試一望，吾欲淚沾臆。"]', '["漢家能用武，开拓窮異域。","戍卒厭糠覈，降胡飽衣食。","关亭試一望，吾欲泪沾臆。"]', '诗', 'shi', '', NULL, '薊門行五首 二 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffe3d0db-accb-46d1-ab4c-ac215d65cc82', '薊門行五首 三', '薊门行五首 三', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["邊城十一月，雨雪亂霏霏。","元戎號令嚴，人馬亦輕肥。","羌胡無盡日，征戰幾時歸。"]', '["邊城十一月，雨雪亂霏霏。","元戎號令嚴，人马亦轻肥。","羌胡無尽日，征戰幾时归。"]', '诗', 'shi', '', NULL, '薊門行五首 三 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9788cd7e-a89d-4061-8f6e-fcb4d46f8e3a', '薊門行五首 四', '薊门行五首 四', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["幽州多騎射，結髮重橫行。","一朝事將軍，出入有聲名。","紛紛獵秋草，相向角弓鳴。"]', '["幽州多騎射，結髮重橫行。","一朝事將軍，出入有声名。","紛紛獵秋草，相向角弓鳴。"]', '诗', 'shi', '', NULL, '薊門行五首 四 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6145d02d-f6db-4a7e-be04-03535abd63c3', '薊門行五首 五', '薊门行五首 五', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["黯黯長城外，日沒更煙塵。","胡騎雖憑陵，漢兵不顧身。","古樹滿空塞，黃雲愁殺人。"]', '["黯黯长城外，日沒更煙塵。","胡騎雖憑陵，漢兵不顧身。","古樹满空塞，黄云愁殺人。"]', '诗', 'shi', '', NULL, '薊門行五首 五 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('271fe949-a658-4f90-b142-866081137549', '效古贈崔二', '效古贈崔二', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["十月河洲時，一看有歸思。","風飆生慘烈，雨雪暗天地。","我輩今胡爲，浩哉迷所至。","緬懷當塗者，濟濟居聲位。","邈然在雲霄，寧肯更淪躓。","周旋多燕樂，門館列車騎。","美人芙蓉姿，狹室蘭麝氣。","金鑪陳獸炭，談笑正得意。","豈論草澤中，有此枯槁士。","我慙經濟策，久欲甘棄置。","君負縱橫才，如何尚顦顇。","長歌增鬱怏，對酒不能醉。","窮達自有時，夫子莫下淚。"]', '["十月河洲时，一看有归思。","风飆生慘烈，雨雪暗天地。","我輩今胡爲，浩哉迷所至。","緬懷當塗者，濟濟居声位。","邈然在云霄，寧肯更淪躓。","周旋多燕乐，门館列车騎。","美人芙蓉姿，狹室蘭麝氣。","金鑪陳獸炭，談笑正得意。","豈論草澤中，有此枯槁士。","我慙經濟策，久欲甘棄置。","君負縱橫才，如何尚顦顇。","长歌增鬱怏，对酒不能醉。","窮達自有时，夫子莫下泪。"]', '诗', 'shi', '', NULL, '效古贈崔二 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f85038c4-be28-4117-afab-a023a2f18b59', '鉅鹿贈李少府', '鉅鹿贈李少府', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["李侯雖薄宦，時譽何籍籍。","駿馬常借人，黃金每留客。","投壺華館靜，縱酒涼風夕。","即此遇神仙，吾欣知損益。"]', '["李侯雖薄宦，时譽何籍籍。","駿马常借人，黄金每留客。","投壺华館静，縱酒涼风夕。","即此遇神仙，吾欣知損益。"]', '诗', 'shi', '', NULL, '鉅鹿贈李少府 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('451fc40e-4dad-47ec-88e7-bb54fbc6bb60', '東平留贈狄司馬', '东平留贈狄司马', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["古人無宿諾，茲道以爲難。","萬里赴知己，一言誠可歎。","馬蹄經月窟，劒術指樓蘭。","地出北庭盡，城臨西海寒。","森然瞻武庫，則是弄儒翰。","入幕綰銀綬，乘軺兼鐵冠。","練兵日精銳，殺敵無遺殘。","獻捷見天子，論功俘可汗。","激昂丹墀下，顧盼青雲端。","誰謂縱橫策，翻爲權勢干。","將軍既坎壈，使者亦辛酸。","耿介挹三事，羇離從一官。","知君不得意，他日會鵬摶。"]', '["古人無宿諾，茲道以爲难。","万里赴知己，一言誠可歎。","马蹄經月窟，劒術指楼蘭。","地出北庭尽，城臨西海寒。","森然瞻武庫，則是弄儒翰。","入幕綰銀綬，乘軺兼鐵冠。","練兵日精銳，殺敵無遺殘。","獻捷见天子，論功俘可汗。","激昂丹墀下，顧盼青云端。","誰謂縱橫策，翻爲權勢干。","將軍既坎壈，使者亦辛酸。","耿介挹三事，羇離從一官。","知君不得意，他日會鵬摶。"]', '诗', 'shi', '', NULL, '東平留贈狄司馬 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b4a2ac4-56be-43c9-83e4-753081c0caf0', '過盧明府有贈', '過盧明府有贈', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["良吏不易得，古人今可傳。","靜然本諸已，以此知其賢。","我行挹高風，羨爾兼少年。","胸懷豁清夜，史漢如流泉。","明日復行春，逶迤出郊壇。","登高見百里，桑野鬱芊芊。","時平俯鵲巢，歲熟多人烟。","奸猾唯閉戶，逃亡歸種田。","廻軒自郭南，老幼滿馬前。","皆賀蠶農至，而無徭役牽。","君觀黎庶心，撫之誠萬全。","何幸逢大道，願言烹小鮮。","能奏明廷主，一試武城弦。"]', '["良吏不易得，古人今可傳。","静然本諸已，以此知其賢。","我行挹高风，羨爾兼少年。","胸懷豁清夜，史漢如流泉。","明日复行春，逶迤出郊壇。","登高见百里，桑野鬱芊芊。","时平俯鵲巢，歲熟多人烟。","奸猾唯閉戶，逃亡归種田。","廻軒自郭南，老幼满马前。","皆賀蠶農至，而無徭役牽。","君观黎庶心，撫之誠万全。","何幸逢大道，願言烹小鲜。","能奏明廷主，一試武城弦。"]', '诗', 'shi', '', NULL, '過盧明府有贈 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfec06fe-678e-45b9-8da3-93ed36cb9f9e', '單父逢鄧司倉覆倉庫因而有贈', '單父逢鄧司倉覆倉庫因而有贈', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["邦牧今坐嘯，羣賢趨紀綱。","四人忽不擾，耕者遙相望。","粲粲府中妙，授詞如履霜。","炎炎伏熱時，草木無晶光。","匹馬度睢水，清風何激揚。","校緡閱帑藏，發廩欣斯箱。","邂逅得相逢，歡言至夕陽。","開襟自公餘，載酒登琴堂。","舉桮挹山川，寓目窮毫芒。","白鳥向田盡，青蟬歸路長。","醉中不惜別，況乃正遊梁。"]', '["邦牧今坐嘯，羣賢趨紀綱。","四人忽不擾，耕者遙相望。","粲粲府中妙，授词如履霜。","炎炎伏熱时，草木無晶光。","匹马度睢水，清风何激揚。","校緡閱帑藏，發廩欣斯箱。","邂逅得相逢，歡言至夕陽。","开襟自公餘，載酒登琴堂。","舉桮挹山川，寓目窮毫芒。","白鸟向田尽，青蟬归路长。","醉中不惜別，況乃正游梁。"]', '诗', 'shi', '', NULL, '單父逢鄧司倉覆倉庫因而有贈 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0256412-ab0a-4c8c-a3e1-09e8434506c1', '薊門不遇王之[渙]郭密之因以留贈', '薊门不遇王之[渙]郭密之因以留贈', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["適遠登薊丘，茲晨獨搔屑。","賢交不可見，吾願終難說。","迢遞千里遊，羇離十年別。","才華仰清興，功業嗟芳節。","曠蕩阻雲海，蕭條帶風雪。","逢時事多謬，失路心彌折。","行矣勿重陳，懷君但愁絕。"]', '["適远登薊丘，茲晨独搔屑。","賢交不可见，吾願終难说。","迢遞千里游，羇離十年別。","才华仰清兴，功業嗟芳節。","曠蕩阻云海，蕭條带风雪。","逢时事多謬，失路心彌折。","行矣勿重陳，懷君但愁絕。"]', '诗', 'shi', '', NULL, '薊門不遇王之[渙]郭密之因以留贈 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a3ab918-5792-4cc1-b05d-bcf0acd26e54', '寄孟五少府', '寄孟五少府', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["秋氣落窮巷，離憂兼暮蟬。","後時已如此，高興亦徒然。","知君念淹泊，憶我屢周旋。","征路見來雁，歸人悲遠天。","平生感千里，相望在貞堅。"]', '["秋氣落窮巷，離憂兼暮蟬。","後时已如此，高兴亦徒然。","知君念淹泊，憶我屢周旋。","征路见来雁，归人悲远天。","平生感千里，相望在貞堅。"]', '诗', 'shi', '', NULL, '寄孟五少府 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20aa930c-017e-4a7d-8909-0782047d574d', '苦雨寄房四昆季', '苦雨寄房四昆季', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["獨坐見多雨，況茲兼索居。","茫茫十月交，窮陰千里餘。","彌望無端倪，北風擊林箊。","白日渺難覩，黃雲爭卷舒。","安得造化功，曠然一掃除。","滴瀝簷宇愁，寥寥談笑疎。","泥塗擁城郭，水潦盤丘墟。","惆悵憫田農，裴回傷里閭。","曾是力井稅，曷爲無斗儲。","萬事切中懷，十年思上書。","君門嗟緬邈，身計念居諸。","沈吟顧草茅，鬱怏任盈虛。","黃鵠不可羨，雞鳴時起予。","故人平臺側，高館臨通衢。","兄弟方荀陳，才華冠應徐。","彈棊自多暇，飲酒更何如。","知人想林宗，直道慙史魚。","攜手風流在，開襟鄙吝祛。","寧能訪窮巷，相與對園蔬。"]', '["独坐见多雨，況茲兼索居。","茫茫十月交，窮陰千里餘。","彌望無端倪，北风擊林箊。","白日渺难覩，黄云爭卷舒。","安得造化功，曠然一掃除。","滴瀝簷宇愁，寥寥談笑疎。","泥塗擁城郭，水潦盤丘墟。","惆悵憫田農，裴回傷里閭。","曾是力井稅，曷爲無斗儲。","万事切中懷，十年思上书。","君门嗟緬邈，身計念居諸。","沈吟顧草茅，鬱怏任盈虛。","黄鵠不可羨，雞鳴时起予。","故人平台側，高館臨通衢。","兄弟方荀陳，才华冠應徐。","彈棊自多暇，饮酒更何如。","知人想林宗，直道慙史鱼。","携手风流在，开襟鄙吝祛。","寧能訪窮巷，相與对园蔬。"]', '诗', 'shi', '', NULL, '苦雨寄房四昆季 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec8e6f54-f69f-43a9-ab8b-155ff46ce8f2', '和賀蘭判官望北海作', '和賀蘭判官望北海作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["聖代務平典，輶軒推上才。","迢遙溟海際，曠望滄波開。","四牡未遑息，三山安在哉。","巨鼇不可釣，高浪何崔嵬。","湛湛朝百谷，茫茫連九垓。","挹流納廣大，觀異增遲廻。","日出見魚目，月圓知蚌胎。","跡非想像到，心以精靈猜。","遠色帶孤嶼，虛聲涵殷雷。","風行越裳貢，水遏天吳災。","攬轡隼將擊，忘機鷗復來。","緣情韻騷雅，獨立遺塵埃。","吏道竟殊用，翰林仍忝陪。","長鳴謝知己，所媿非龍媒。"]', '["聖代務平典，輶軒推上才。","迢遙溟海際，曠望滄波开。","四牡未遑息，三山安在哉。","巨鼇不可釣，高浪何崔嵬。","湛湛朝百谷，茫茫連九垓。","挹流納廣大，观異增遲廻。","日出见鱼目，月圓知蚌胎。","跡非想像到，心以精靈猜。","远色带孤嶼，虛声涵殷雷。","风行越裳貢，水遏天吳災。","攬轡隼將擊，忘機鷗复来。","緣情韻騷雅，独立遺塵埃。","吏道竟殊用，翰林仍忝陪。","长鳴謝知己，所媿非龙媒。"]', '诗', 'shi', '', NULL, '和賀蘭判官望北海作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5653ac5-0da7-42d7-b638-9b818b3567ed', '和崔二少府登楚丘城作', '和崔二少府登楚丘城作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["故人亦不遇，異縣久棲託。","辛勤失路意，感歎登樓作。","清晨眺原野，獨立窮寥廓。","雲散芒碭山，水還睢陽郭。","繞梁即襟帶，封衛多漂泊。","事古悲城池，年豐愛墟落。","相逢俱未展，攜手空蕭索。","何意千里心，仍求百金諾。","公侯皆我輩，動用在謀略。","聖心思賢才，朅來刈葵藿。"]', '["故人亦不遇，異縣久棲託。","辛勤失路意，感歎登楼作。","清晨眺原野，独立窮寥廓。","云散芒碭山，水還睢陽郭。","繞梁即襟带，封衛多漂泊。","事古悲城池，年豐愛墟落。","相逢俱未展，携手空蕭索。","何意千里心，仍求百金諾。","公侯皆我輩，动用在謀略。","聖心思賢才，朅来刈葵藿。"]', '诗', 'shi', '', NULL, '和崔二少府登楚丘城作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7eb94c0-2bf9-4da6-ba0a-7af47801b062', '酬司空璲少府', '酬司空璲少府', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["飄颻未得意，感激與誰論。","昨日遇夫子，仍欣吾道存。","江山滿詞賦，札翰起涼溫。","吾見風雅作，人知德業尊。","驚飆蕩萬木，秋氣屯高原。","燕趙何蒼茫，鴻雁來翩翻。","此時與君別，握手欲無言。"]', '["飄颻未得意，感激與誰論。","昨日遇夫子，仍欣吾道存。","江山满词賦，札翰起涼溫。","吾见风雅作，人知德業尊。","驚飆蕩万木，秋氣屯高原。","燕趙何蒼茫，鴻雁来翩翻。","此时與君別，握手欲無言。"]', '诗', 'shi', '', NULL, '酬司空璲少府 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5561dd82-ac19-4c72-ba0c-a941cec526c8', '酬李少府', '酬李少府', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["出塞魂屢驚，懷賢意難說。","誰知吾道間，乃在客中別。","日夕捧瓊瑤，相思無休歇。","伊人雖薄宦，舉代推高節。","述作凌江山，聲華滿冰雪。","一登薊丘上，四顧何慘烈。","來雁無盡時，邊風正騷屑。","將從崖谷遁，且與沈浮絕。","君若登青雲，余當投魏闕。"]', '["出塞魂屢驚，懷賢意难说。","誰知吾道间，乃在客中別。","日夕捧瓊瑤，相思無休歇。","伊人雖薄宦，舉代推高節。","述作凌江山，声华满冰雪。","一登薊丘上，四顧何慘烈。","来雁無尽时，邊风正騷屑。","將從崖谷遁，且與沈浮絕。","君若登青云，余當投魏闕。"]', '诗', 'shi', '', NULL, '酬李少府 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea341c3a-1c84-49ef-9458-64f84f5e7eac', '酬裴秀才', '酬裴秀才', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["男兒貴得意，何必相知早。","飄蕩與物永，躊跎覺年老。","長卿無產業，季子慙妻嫂。","此事難重陳，未於衆人道。"]', '["男兒貴得意，何必相知早。","飄蕩與物永，躊跎覺年老。","长卿無產業，季子慙妻嫂。","此事难重陳，未於衆人道。"]', '诗', 'shi', '', NULL, '酬裴秀才 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb1ed1bb-9a23-42f5-94b7-fb065fa6d411', '酬陸少府', '酬陸少府', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["朝臨淇水岸，還望衛人邑。","別意在山阿，征途背原隰。","蕭蕭前村口，唯見轉蓬入。","水渚人去遲，霜天雁飛急。","固應不遠別，所與路未及。","欲濟川上舟，相思空佇立。"]', '["朝臨淇水岸，還望衛人邑。","別意在山阿，征途背原隰。","蕭蕭前村口，唯见轉蓬入。","水渚人去遲，霜天雁飞急。","固應不远別，所與路未及。","欲濟川上舟，相思空佇立。"]', '诗', 'shi', '', NULL, '酬陸少府 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb4a1d16-2a2e-4a68-9732-77e2bfafde5e', '奉酬北海李太守丈人夏日平陰亭', '奉酬北海李太守丈人夏日平陰亭', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["天子股肱守，丈人山嶽靈。","出身侍丹墀，舉翮凌青冥。","當昔皇運否，人神俱未寧。","諫官莫敢議，酷吏方專刑。","谷永獨言事，匡衡多引經。","兩朝納深衷，萬乘無不聽。","盛烈播南史，雄詞豁東溟。","誰謂整隼旟，翻然憶柴扃。","寄書汶陽客，廻首平陰亭。","開封見千里，結念存百齡。","隱軫江山麗，氛氳蘭茝馨。","自憐遇時休，漂泊隨流萍。","春野變木德，夏天臨火星。","一生徒羨魚，四十猶聚螢。","從此日閑放，焉能懷拾青。"]', '["天子股肱守，丈人山嶽靈。","出身侍丹墀，舉翮凌青冥。","當昔皇運否，人神俱未寧。","諫官莫敢議，酷吏方專刑。","谷永独言事，匡衡多引經。","兩朝納深衷，万乘無不听。","盛烈播南史，雄词豁东溟。","誰謂整隼旟，翻然憶柴扃。","寄书汶陽客，廻首平陰亭。","开封见千里，結念存百齡。","隐軫江山丽，氛氳蘭茝馨。","自怜遇时休，漂泊隨流萍。","春野变木德，夏天臨火星。","一生徒羨鱼，四十猶聚螢。","從此日闲放，焉能懷拾青。"]', '诗', 'shi', '', NULL, '奉酬北海李太守丈人夏日平陰亭 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff7aca6e-232d-464f-91cf-75f019591e69', '酬馬八效古見贈', '酬马八效古见贈', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["深崖無綠竹，秀色徒氛氳。","時代種桃李，無人顧此君。","奈何冰雪操，尚與蒿萊羣。","願託靈仙子，一聲吹入雲。"]', '["深崖無綠竹，秀色徒氛氳。","时代種桃李，無人顧此君。","奈何冰雪操，尚與蒿萊羣。","願託靈仙子，一声吹入云。"]', '诗', 'shi', '', NULL, '酬馬八效古見贈 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bb52f17-5109-4d2a-93b9-7e1074dbb45b', '酬鴻臚裴主簿雨後睢陽北樓見贈之作', '酬鴻臚裴主簿雨後睢陽北楼见贈之作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["暮霞照新晴，歸雲猶相逐。","有懷晨昏暇，相見登眺目。","問禮侍彤襜，題詩訪茅屋。","高樓多古今，陳事滿陵谷。","地久微子封，臺餘孝王築。","裴回顧霄漢，豁達俯川陸。","遠水對秋城，長天向喬木。","公門何清淨，列戟森已肅。","不歎攜手稀，恆思着鞭速。","終當拂羽翰，輕舉隨鴻鵠。"]', '["暮霞照新晴，归云猶相逐。","有懷晨昏暇，相见登眺目。","问禮侍彤襜，題诗訪茅屋。","高楼多古今，陳事满陵谷。","地久微子封，台餘孝王築。","裴回顧霄漢，豁達俯川陸。","远水对秋城，长天向喬木。","公门何清淨，列戟森已肅。","不歎携手稀，恆思着鞭速。","終當拂羽翰，轻舉隨鴻鵠。"]', '诗', 'shi', '', NULL, '酬鴻臚裴主簿雨後睢陽北樓見贈之作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ca5eb72-69e6-47f0-a27d-06034645217d', '酬裴員外以詩代書', '酬裴員外以诗代书', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["少時方浩蕩，遇物猶塵埃。","脫略身外事，交遊天下才。","單車入燕趙，獨立心悠哉。","寧知戎馬間，忽展平生懷。","且欣清論高，豈顧夕陽頹。","題詩碣石館，縱酒燕王臺。","北望沙漠垂，漫天雪皚皚。","臨邊無策略，覽古空裴回。","樂毅吾所憐，拔齊翻見猜。","荆卿吾所悲，適秦不復廻。","然諾多死地，公忠成禍胎。","與君從此辭，每恐流年催。","如何俱老大，始復忘形骸。","兄弟真二陸，聲名連八裴。","乙未將星變，賊臣候天災。","胡騎犯龍山，乘輿經馬嵬。","千官無倚着，萬姓徒悲哀。","誅呂鬼神動，安劉天地開。","奔波走風塵，倏忽值雲雷。","擁旄出淮甸，入幕徵楚材。","誓當剪鯨鯢，永以竭駑駘。","小人胡不仁，讒我成死灰。","賴得日月明，照耀無不該。","留司洛陽宮，詹府唯蒿萊。","是時掃氛祲，尚未殲渠魁。","背河列長圍，師老將亦乖。","歸軍劇風火，散卒爭椎埋。","一夕瀍洛空，生靈悲曝腮。","衣冠投草莽，予欲馳江淮。","登頓宛葉下，棲遑襄鄧隈。","城池何蕭條，邑屋更崩摧。","縱橫荆棘叢，但見瓦礫堆。","行人無血色，戰骨多青苔。","遂除彭門守，因得朝玉階。","激昂仰鵷鷺，獻替欣鹽梅。","驅傳及遠蕃，憂思鬱難排。","罷人紛爭訟，賦稅如山崖。","所思在畿甸，曾是魯宓儕。","自從拜郎官，列宿煥天街。","那能訪遐僻，還復寄瓊瓌。","金玉本高價，塤箎終易諧。","朗詠臨清秋，涼風下庭槐。","何意寇盜間，獨稱名義偕。","辛酸陳侯誄，歎息季鷹杯。","白日屢分手，青春不再來。","臥看中散論，愁憶太常齋。","酬贈徒爲爾，長歌還自咍。"]', '["少时方浩蕩，遇物猶塵埃。","脫略身外事，交游天下才。","單车入燕趙，独立心悠哉。","寧知戎马间，忽展平生懷。","且欣清論高，豈顧夕陽頹。","題诗碣石館，縱酒燕王台。","北望沙漠垂，漫天雪皚皚。","臨邊無策略，覽古空裴回。","乐毅吾所怜，拔齊翻见猜。","荆卿吾所悲，適秦不复廻。","然諾多死地，公忠成禍胎。","與君從此辞，每恐流年催。","如何俱老大，始复忘形骸。","兄弟真二陸，声名連八裴。","乙未將星变，賊臣候天災。","胡騎犯龙山，乘輿經马嵬。","千官無倚着，万姓徒悲哀。","誅呂鬼神动，安劉天地开。","奔波走风塵，倏忽值云雷。","擁旄出淮甸，入幕徵楚材。","誓當剪鯨鯢，永以竭駑駘。","小人胡不仁，讒我成死灰。","賴得日月明，照耀無不該。","留司洛陽宮，詹府唯蒿萊。","是时掃氛祲，尚未殲渠魁。","背河列长圍，師老將亦乖。","归軍劇风火，散卒爭椎埋。","一夕瀍洛空，生靈悲曝腮。","衣冠投草莽，予欲驰江淮。","登頓宛葉下，棲遑襄鄧隈。","城池何蕭條，邑屋更崩摧。","縱橫荆棘叢，但见瓦礫堆。","行人無血色，戰骨多青苔。","遂除彭门守，因得朝玉階。","激昂仰鵷鷺，獻替欣鹽梅。","驱傳及远蕃，憂思鬱难排。","罷人紛爭訟，賦稅如山崖。","所思在畿甸，曾是魯宓儕。","自從拜郎官，列宿煥天街。","那能訪遐僻，還复寄瓊瓌。","金玉本高價，塤箎終易諧。","朗詠臨清秋，涼风下庭槐。","何意寇盜间，独稱名義偕。","辛酸陳侯誄，歎息季鷹杯。","白日屢分手，青春不再来。","臥看中散論，愁憶太常斋。","酬贈徒爲爾，长歌還自咍。"]', '诗', 'shi', '', NULL, '酬裴員外以詩代書 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6a2e130-f45f-49a4-a7da-e0441d1578cd', '酬龐十兵曹', '酬龐十兵曹', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["憶昔遊京華，自言生羽翼。","懷書訪知己，末路空相識。","許國不成名，還家有慙色。","託身從𤱶畝，浪跡初自得。","雨澤感天時，耕耘忘帝力。","同人洛陽至，問我睢水北。","遂爾款津涯，淨然見胸臆。","高談懸物象，逸韻投翰墨。","別岸迥無垠，海鶴鳴不息。","梁城多古意，攜手共悽惻。","懷賢想鄒枚，登高思荆棘。","世情惡疵賤，之子憐孤直。","酬贈感幷深，離憂豈終極。"]', '["憶昔游京华，自言生羽翼。","懷书訪知己，末路空相識。","許国不成名，還家有慙色。","託身從𤱶畝，浪跡初自得。","雨澤感天时，耕耘忘帝力。","同人洛陽至，问我睢水北。","遂爾款津涯，淨然见胸臆。","高談懸物象，逸韻投翰墨。","別岸迥無垠，海鹤鳴不息。","梁城多古意，携手共悽惻。","懷賢想鄒枚，登高思荆棘。","世情惡疵賤，之子怜孤直。","酬贈感幷深，離憂豈終極。"]', '诗', 'shi', '', NULL, '酬龐十兵曹 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8133806-1aeb-44d9-8b5e-6309fe6bd8cb', '同呂員外酬田著作幕門軍西宿盤山秋夜作', '同呂員外酬田著作幕门軍西宿盤山秋夜作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["磧路天早秋，邊城夜應永。","遙傳戎旅作，已報關山冷。","上將頓盤阪，諸軍徧泉井。","綢繆閫外書，慷慨幕中請。","能使勳業高，動令氛霧屏。","遠途能自致，短步終難騁。","羽翮時一看，窮愁始三省。","人生感然諾，何啻若形影。","白髮知苦心，陽春見佳境。","星河連塞絡，刁斗兼山靜。","憶君霜露時，使我空引領。"]', '["磧路天早秋，邊城夜應永。","遙傳戎旅作，已報关山冷。","上將頓盤阪，諸軍徧泉井。","綢繆閫外书，慷慨幕中請。","能使勳業高，动令氛霧屏。","远途能自致，短步終难騁。","羽翮时一看，窮愁始三省。","人生感然諾，何啻若形影。","白髮知苦心，陽春见佳境。","星河連塞絡，刁斗兼山静。","憶君霜露时，使我空引領。"]', '诗', 'shi', '', NULL, '同呂員外酬田著作幕門軍西宿盤山秋夜作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('276d7c1f-d89d-48fd-a8f5-777b9efd9d23', '酬祕書弟兼寄幕下諸公', '酬祕书弟兼寄幕下諸公', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["亞相膺時傑，羣才遇良工。","翩翩幕下來，拜賜甘泉宮。","信知命世奇，適會非常功。","侍御執邦憲，清詞煥春叢。","末路望繡衣，他時常發蒙。","孰云三軍壯，懼我彈射雄。","誰謂萬里遙，在我樽俎中。","光祿經濟器，精微自深衷。","前席屢榮問，長城兼在躬。","高縱激頹波，逸翮馳蒼穹。","將副節制籌，欲令沙漠空。","司業志應徐，雅度思沖融。","相思三十年，憶昨猶兒童。","今來抱青紫，忽若披鵷鴻。","說劒增慷慨，論交持始終。","祕書即吾門，虛白無不通。","多才陸平原，碩學鄭司農。","獻封到關西，獨步歸山東。","永意久知處，嘉言能亢宗。","客從梁宋來，行役隨轉蓬。","酬贈欣元弟，憶賢瞻數公。","游鱗戲滄浪，鳴鳳棲梧桐。","並負垂天翼，俱乘破浪風。","眈眈天府間，偃仰誰敢同。","何意搆廣廈，翻然顧雕蟲。","應知阮步兵，惆悵此途窮。"]', '["亞相膺时傑，羣才遇良工。","翩翩幕下来，拜賜甘泉宮。","信知命世奇，適會非常功。","侍御執邦憲，清词煥春叢。","末路望繡衣，他时常發蒙。","孰云三軍壯，懼我彈射雄。","誰謂万里遙，在我樽俎中。","光祿經濟器，精微自深衷。","前席屢榮问，长城兼在躬。","高縱激頹波，逸翮驰蒼穹。","將副節制籌，欲令沙漠空。","司業志應徐，雅度思沖融。","相思三十年，憶昨猶兒童。","今来抱青紫，忽若披鵷鴻。","说劒增慷慨，論交持始終。","祕书即吾门，虛白無不通。","多才陸平原，碩学鄭司農。","獻封到关西，独步归山东。","永意久知处，嘉言能亢宗。","客從梁宋来，行役隨轉蓬。","酬贈欣元弟，憶賢瞻數公。","游鱗戲滄浪，鳴鳳棲梧桐。","並負垂天翼，俱乘破浪风。","眈眈天府间，偃仰誰敢同。","何意搆廣廈，翻然顧雕蟲。","應知阮步兵，惆悵此途窮。"]', '诗', 'shi', '', NULL, '酬祕書弟兼寄幕下諸公 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13619ace-57d2-4444-ac03-15481045fff6', '淇上酬薛三據兼寄郭少府微', '淇上酬薛三據兼寄郭少府微', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["自從別京華，我心乃蕭索。","十年守章句，萬事空寥落。","北上登薊門，茫茫見沙漠。","倚劒對風塵，慨然思衛霍。","拂衣去燕趙，驅馬悵不樂。","天長滄洲路，日暮邯鄲郭。","酒肆或淹留，漁潭屢棲泊。","獨行備艱險，所見窮善惡。","永願拯芻蕘，孰云干鼎鑊。","皇情念淳古，時俗何浮薄。","理道資任賢，安人在求瘼。","故交負靈奇，逸氣抱謇諤。","隱軫經濟具，縱橫建安作。","才望忽先鳴，風期無宿諾。","飄颻勞州縣，迢遞限言謔。","東馳眇貝丘，西顧彌虢略。","淇水徒自流，浮雲不堪託。","吾謀適可用，天路豈寥廓。","不然買山田，一身與耕鑿。","且欲同鷦鷯，焉能志鴻鵠。"]', '["自從別京华，我心乃蕭索。","十年守章句，万事空寥落。","北上登薊门，茫茫见沙漠。","倚劒对风塵，慨然思衛霍。","拂衣去燕趙，驱马悵不乐。","天长滄洲路，日暮邯鄲郭。","酒肆或淹留，漁潭屢棲泊。","独行備艱險，所见窮善惡。","永願拯芻蕘，孰云干鼎鑊。","皇情念淳古，时俗何浮薄。","理道資任賢，安人在求瘼。","故交負靈奇，逸氣抱謇諤。","隐軫經濟具，縱橫建安作。","才望忽先鳴，风期無宿諾。","飄颻勞州縣，迢遞限言謔。","东驰眇貝丘，西顧彌虢略。","淇水徒自流，浮云不堪託。","吾謀適可用，天路豈寥廓。","不然買山田，一身與耕鑿。","且欲同鷦鷯，焉能志鴻鵠。"]', '诗', 'shi', '', NULL, '淇上酬薛三據兼寄郭少府微 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf44f6f5-acdc-449d-b10e-3096bfde8eed', '酬岑二十主簿秋夜見贈之作', '酬岑二十主簿秋夜见贈之作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["舍下蛩亂鳴，居然自蕭索。","緬懷高秋興，忽枉清夜作。","感物我心勞，涼風驚二毛。","池枯菡萏死，月出梧桐高。","如何異鄉縣，復得交才彥。","汨沒嗟後時，蹉跎耻相見。","箕山別來久，魏闕誰不戀。","獨有江海心，悠悠未嘗倦。"]', '["舍下蛩亂鳴，居然自蕭索。","緬懷高秋兴，忽枉清夜作。","感物我心勞，涼风驚二毛。","池枯菡萏死，月出梧桐高。","如何異乡縣，复得交才彥。","汨沒嗟後时，蹉跎耻相见。","箕山別来久，魏闕誰不戀。","独有江海心，悠悠未嘗倦。"]', '诗', 'shi', '', NULL, '酬岑二十主簿秋夜見贈之作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a76b6ea-07ee-44b6-ac20-a87d18203810', '答侯少府', '答侯少府', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["常日好讀書，晚年學垂綸。","漆園多喬木，睢水清粼粼。","詔書下柴門，天命敢逡巡。","赫赫三伏時，十日到咸秦。","褐衣不得見，黃綬翻在身。","吏道頓羈束，生涯難重陳。","北使經大寒，關山饒苦辛。","邊兵若芻狗，戰骨成埃塵。","行矣勿復言，歸歟傷我神。","如何燕趙陲，忽遇平生親。","開館納征騎，彈絃娛遠賓。","飄颻天地間，一別方茲晨。","東道有佳作，南朝無此人。","性靈出萬象，風骨超常倫。","吾黨謝王粲，羣賢推郄詵。","明時取秀才，落日過蒲津。","節苦名已富，祿微家轉貧。","相逢愧薄遊，撫己荷陶鈞。","心事正堪盡，離居寧太頻。","兩河歸路遙，二月芳草新。","柳接滹沱暗，鶯連渤海春。","誰謂行路難，猥當希代珍。","提握每終日，相思猶比鄰。","江海有扁舟，丘園有角巾。","君意定何適，我懷知所遵。","浮沈各異宜，老大貴全真。","莫作雲霄計，遑遑隨縉紳。"]', '["常日好读书，晚年学垂綸。","漆园多喬木，睢水清粼粼。","詔书下柴门，天命敢逡巡。","赫赫三伏时，十日到咸秦。","褐衣不得见，黄綬翻在身。","吏道頓羈束，生涯难重陳。","北使經大寒，关山饒苦辛。","邊兵若芻狗，戰骨成埃塵。","行矣勿复言，归歟傷我神。","如何燕趙陲，忽遇平生親。","开館納征騎，彈絃娛远賓。","飄颻天地间，一別方茲晨。","东道有佳作，南朝無此人。","性靈出万象，风骨超常倫。","吾黨謝王粲，羣賢推郄詵。","明时取秀才，落日過蒲津。","節苦名已富，祿微家轉貧。","相逢愧薄游，撫己荷陶鈞。","心事正堪尽，離居寧太頻。","兩河归路遙，二月芳草新。","柳接滹沱暗，鶯連渤海春。","誰謂行路难，猥當希代珍。","提握每終日，相思猶比鄰。","江海有扁舟，丘园有角巾。","君意定何適，我懷知所遵。","浮沈各異宜，老大貴全真。","莫作云霄計，遑遑隨縉紳。"]', '诗', 'shi', '', NULL, '答侯少府 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efc46322-baf5-49cd-9988-7c7333a99a2b', '宋中別周梁李三子', '宋中別周梁李三子', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["曾是不得意，適來兼別離。","如何一尊酒，翻作滿堂悲。","周子負高價，梁生多逸詞。","周旋梁宋間，感激建安時。","白雪正如此，青雲無自疑。","李侯懷英雄，骯髒乃天資。","方寸且無間，衣冠當在斯。","俱爲千里遊，忽念兩鄉辭。","且見壯心在，莫嗟攜手遲。","涼風吹北原，落日滿西陂。","露下草初白，天長雲屢滋。","我心不可問，君去定何之。","京洛多知己，誰能憶左思。"]', '["曾是不得意，適来兼別離。","如何一尊酒，翻作满堂悲。","周子負高價，梁生多逸词。","周旋梁宋间，感激建安时。","白雪正如此，青云無自疑。","李侯懷英雄，骯髒乃天資。","方寸且無间，衣冠當在斯。","俱爲千里游，忽念兩乡辞。","且见壯心在，莫嗟携手遲。","涼风吹北原，落日满西陂。","露下草初白，天长云屢滋。","我心不可问，君去定何之。","京洛多知己，誰能憶左思。"]', '诗', 'shi', '', NULL, '宋中別周梁李三子 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c12a5688-d65f-4e18-a9c6-6f5be6510e1c', '宋中別李八', '宋中別李八', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["歲晏誰不歸，君歸意可說。","將趨倚門望，還念同人別。","駐馬臨長亭，飄然事明發。","蒼茫眺千里，正值苦寒節。","舊國多轉蓬，平臺下明月。","世情薄疵賤，夫子懷賢哲。","行矣各勉旃，吾當挹餘烈。"]', '["歲晏誰不归，君归意可说。","將趨倚门望，還念同人別。","駐马臨长亭，飄然事明發。","蒼茫眺千里，正值苦寒節。","旧国多轉蓬，平台下明月。","世情薄疵賤，夫子懷賢哲。","行矣各勉旃，吾當挹餘烈。"]', '诗', 'shi', '', NULL, '宋中別李八 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('944aa163-f965-4396-9cea-d4fd8746eaf7', '別王徹', '別王徹', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["歸客自南楚，悵然思北林。","蕭條秋風暮，廻首江淮深。","留君終日歡，或爲梁父吟。","時輩想鵬舉，他人嗟陸沈。","載酒登平臺，贈君千里心。","浮雲暗長路，落日有歸禽。","離別未足悲，辛勤當自任。","吾知十年後，季子多黃金。"]', '["归客自南楚，悵然思北林。","蕭條秋风暮，廻首江淮深。","留君終日歡，或爲梁父吟。","时輩想鵬舉，他人嗟陸沈。","載酒登平台，贈君千里心。","浮云暗长路，落日有归禽。","離別未足悲，辛勤當自任。","吾知十年後，季子多黄金。"]', '诗', 'shi', '', NULL, '別王徹 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c64926d8-1757-4e1f-8096-dd24190f1ba1', '送蕭十八與房侍御廻還', '送蕭十八與房侍御廻還', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["常苦古人遠，今見斯人古。","澹泊遺聲華，周旋必鄒魯。","故交在梁宋，遊方出庭戶。","匹馬鳴朔風，一身濟河滸。","辛勤采蘭詠，款曲翰林主。","歲月催別離，庭圍遠風土。","寥寥寒煙靜，莽莽夕陰吐。","明發不在茲，青天眇難覩。"]', '["常苦古人远，今见斯人古。","澹泊遺声华，周旋必鄒魯。","故交在梁宋，游方出庭戶。","匹马鳴朔风，一身濟河滸。","辛勤采蘭詠，款曲翰林主。","歲月催別離，庭圍远风土。","寥寥寒煙静，莽莽夕陰吐。","明發不在茲，青天眇难覩。"]', '诗', 'shi', '', NULL, '送蕭十八與房侍御廻還 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9b7af05-49db-4fac-8c70-6f300183e59f', '宋中送族姪式顏', '宋中送族姪式顏', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["大夫擊東胡，胡塵不敢起。","胡人山下哭，胡馬海邊死。","部曲盡公侯，輿臺亦朱紫。","當時有勳業，末路遭讒毀。","轉斾燕趙間，剖符括蒼裏。","弟兄莫相見，親族遠枌梓。","不改青雲心，仍招布衣士。","平生懷感激，本欲候知己。","去矣難重陳，飄然自茲始。","遊梁且未遇，適越今何以。","鄉山西北愁，竹箭東南美。","崢嶸縉雲外，蒼莽幾千里。","旅雁悲啾啾，朝昏孰云已。","登臨多瘴癘，動息在風水。","雖有賢主人，終爲客行子。","我攜一尊酒，滿酌聊勸爾。","勸爾惟一言，家聲勿淪滓。"]', '["大夫擊东胡，胡塵不敢起。","胡人山下哭，胡马海邊死。","部曲尽公侯，輿台亦朱紫。","當时有勳業，末路遭讒毀。","轉斾燕趙间，剖符括蒼裏。","弟兄莫相见，親族远枌梓。","不改青云心，仍招布衣士。","平生懷感激，本欲候知己。","去矣难重陳，飄然自茲始。","游梁且未遇，適越今何以。","乡山西北愁，竹箭东南美。","崢嶸縉云外，蒼莽幾千里。","旅雁悲啾啾，朝昏孰云已。","登臨多瘴癘，动息在风水。","雖有賢主人，終爲客行子。","我携一尊酒，满酌聊勸爾。","勸爾惟一言，家声勿淪滓。"]', '诗', 'shi', '', NULL, '宋中送族姪式顏 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e108405-df95-4dca-abfe-9357e312eae6', '又送族姪式顏', '又送族姪式顏', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["惜君才未遇，愛君才若此。","世上五百年，吾家一千里。","俱遊帝城下，忽在梁園裏。","我今行山東，離憂不能已。"]', '["惜君才未遇，愛君才若此。","世上五百年，吾家一千里。","俱游帝城下，忽在梁园裏。","我今行山东，離憂不能已。"]', '诗', 'shi', '', NULL, '又送族姪式顏 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bb37684-e982-4765-bce8-fbfe3b87dc15', '贈別王十七管記', '贈別王十七管記', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["故交吾未測，薄宦空年歲。","晚節蹤曩賢，雄詞冠當世。","堂中皆食客，門外多酒債。","產業曾未言，衣裘與人敝。","飄颻戎幕下，出入關山際。","轉戰輕壯心，立談有邊計。","雲沙自廻合，天海空迢遞。","星高漢將驕，月盛胡兵銳。","沙深冷陘斷，雪暗遼陽閉。","亦謂掃欃槍，旋驚陷蜂蠆。","歸旌告東捷，鬬騎傳西敗。","遙飛絕漢書，已築長安第。","畫龍俱在葉，寵鶴先居衛。","勿辭部曲勳，不藉將軍勢。","相逢季冬月，倀望窮海裔。","折劒留贈人，嚴裝遂云邁。","我行將悠𥾝，及此還羈滯。","曾非濟代謀，且有臨深誡。","隨波混清濁，與物同醜麗。","眇憶青巖棲，寧忘褐衣拜。","自言愛水石，本欲親蘭蕙。","何意薄松筠，翻然重菅蒯。","恆深取與分，孰慢平生契。","欵曲雞黍期，酸辛別離袂。","逢時愧名節，遇坎悲淪替。","適趙非解紛，遊燕往無說。","浩歌方振蕩，逸翮思凌勵。","倏若異鵬摶，吾當學蟬蛻。"]', '["故交吾未測，薄宦空年歲。","晚節蹤曩賢，雄词冠當世。","堂中皆食客，门外多酒債。","產業曾未言，衣裘與人敝。","飄颻戎幕下，出入关山際。","轉戰轻壯心，立談有邊計。","云沙自廻合，天海空迢遞。","星高漢將驕，月盛胡兵銳。","沙深冷陘斷，雪暗遼陽閉。","亦謂掃欃槍，旋驚陷蜂蠆。","归旌告东捷，鬬騎傳西敗。","遙飞絕漢书，已築长安第。","畫龙俱在葉，寵鹤先居衛。","勿辞部曲勳，不藉將軍勢。","相逢季冬月，倀望窮海裔。","折劒留贈人，嚴裝遂云邁。","我行將悠𥾝，及此還羈滯。","曾非濟代謀，且有臨深誡。","隨波混清濁，與物同醜丽。","眇憶青巖棲，寧忘褐衣拜。","自言愛水石，本欲親蘭蕙。","何意薄松筠，翻然重菅蒯。","恆深取與分，孰慢平生契。","欵曲雞黍期，酸辛別離袂。","逢时愧名節，遇坎悲淪替。","適趙非解紛，游燕往無说。","浩歌方振蕩，逸翮思凌勵。","倏若異鵬摶，吾當学蟬蛻。"]', '诗', 'shi', '', NULL, '贈別王十七管記 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18c3e26e-8080-4a15-abf7-5b92cc862711', '漣上別王秀才', '漣上別王秀才', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["飄颻經遠道，客思滿窮秋。","浩蕩對長漣，君行殊未休。","崎嶇山海側，想像無前儔。","何意照乘珠，忽然欲暗投。","東路方蕭條，楚歌復悲愁。","暮帆使人感，去鳥兼離憂。","行矣當自愛，壯年莫悠悠。","余亦從此辭，異鄉難久留。","贈言豈終極，慎勿滯滄洲。"]', '["飄颻經远道，客思满窮秋。","浩蕩对长漣，君行殊未休。","崎嶇山海側，想像無前儔。","何意照乘珠，忽然欲暗投。","东路方蕭條，楚歌复悲愁。","暮帆使人感，去鸟兼離憂。","行矣當自愛，壯年莫悠悠。","余亦從此辞，異乡难久留。","贈言豈終極，慎勿滯滄洲。"]', '诗', 'shi', '', NULL, '漣上別王秀才 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27246964-80bd-4b60-ae59-0921b0832948', '贈別沈四逸人', '贈別沈四逸人', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["沈侯未可測，其況信浮沈。","十載常獨坐，幾人知此心。","乘舟蹈滄海，買劒投黃金。","世務不足煩，有田西山岑。","我來遇知己，遂得開清襟。","何意閫閾間，沛然江海深。","疾風掃秋樹，濮上多鳴砧。","耿耿尊酒前，聯雁飛愁音。","平生重離別，感激對孤琴。"]', '["沈侯未可測，其況信浮沈。","十載常独坐，幾人知此心。","乘舟蹈滄海，買劒投黄金。","世務不足煩，有田西山岑。","我来遇知己，遂得开清襟。","何意閫閾间，沛然江海深。","疾风掃秋樹，濮上多鳴砧。","耿耿尊酒前，聯雁飞愁音。","平生重離別，感激对孤琴。"]', '诗', 'shi', '', NULL, '贈別沈四逸人 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6956d17b-9f62-4b03-876f-07ff4e278c15', '送韓九', '送韓九', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["惆悵別離日，裴回岐路前。","歸人望獨樹，匹馬隨秋蟬。","常與天下士，許君兄弟賢。","良時正可用，行矣莫徒然。"]', '["惆悵別離日，裴回岐路前。","归人望独樹，匹马隨秋蟬。","常與天下士，許君兄弟賢。","良时正可用，行矣莫徒然。"]', '诗', 'shi', '', NULL, '送韓九 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a966ed0-e64c-4cd4-9361-c79dbe37c05f', '送崔錄事赴宣城', '送崔錄事赴宣城', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["大國非不理，小官皆用才。","欲行宣城印，住飲洛陽桮。","晚景爲人別，長天無鳥廻。","舉帆風波渺，倚櫂江山來。","羨爾兼乘興，蕪湖千里開。"]', '["大国非不理，小官皆用才。","欲行宣城印，住饮洛陽桮。","晚景爲人別，长天無鸟廻。","舉帆风波渺，倚櫂江山来。","羨爾兼乘兴，蕪湖千里开。"]', '诗', 'shi', '', NULL, '送崔錄事赴宣城 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5e21ddd-ceac-4c68-84c6-1de487ea4216', '別張少府', '別張少府', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["歸客留不住，朝雲縱復橫。","馬頭向春草，斗柄臨高城。","嗟我久離別，羨君看弟兄。","歸心更難道，回首一傷情。"]', '["归客留不住，朝云縱复橫。","马头向春草，斗柄臨高城。","嗟我久離別，羨君看弟兄。","归心更难道，回首一傷情。"]', '诗', 'shi', '', NULL, '別張少府 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d43c8384-8c19-4dd5-814a-14e14e0f7803', '淇上別劉少府子英', '淇上別劉少府子英', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["近來住淇上，蕭條惟空林。","又非耕種時，閑散多自任。","伊君獨知我，驅馬欲招尋。","千里忽攜手，十年同苦心。","求仁見交態，於道喜甘臨。","逸思乃天縱，微才應陸沈。","飄然歸故鄉，不復問離襟。","南登黎陽渡，莽蒼寒雲陰。","桑葉原上起，河淩山下深。","途窮更遠別，相對益悲吟。"]', '["近来住淇上，蕭條惟空林。","又非耕種时，闲散多自任。","伊君独知我，驱马欲招尋。","千里忽携手，十年同苦心。","求仁见交態，於道喜甘臨。","逸思乃天縱，微才應陸沈。","飄然归故乡，不复问離襟。","南登黎陽渡，莽蒼寒云陰。","桑葉原上起，河淩山下深。","途窮更远別，相对益悲吟。"]', '诗', 'shi', '', NULL, '淇上別劉少府子英 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6491c82-16cc-417f-bc8d-4cf938aa4ed4', '別耿都尉', '別耿都尉', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["四十能學劒，時人無此心。","如何耿夫子，感激投知音。","翩翩白馬來，二月青草深。","別易小千里，興酣傾百金。"]', '["四十能学劒，时人無此心。","如何耿夫子，感激投知音。","翩翩白马来，二月青草深。","別易小千里，兴酣傾百金。"]', '诗', 'shi', '', NULL, '別耿都尉 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83de3747-2242-4ae3-be3e-56a7b040aae2', '宋中遇林盧楊十七山人因而有別', '宋中遇林盧楊十七山人因而有別', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["昔余涉漳水，驅車行鄴西。","遙見林慮山，蒼蒼戛天倪。","邂逅逢爾曹，說君彼巖棲。","蘿徑垂野蔓，石房倚雲梯。","秋韭何青青，藥苗數百畦。","栗林隘谷口，栝樹森廻谿。","耕耘有山田，紡績有山妻。","人生苟如此，何必組與珪。","誰謂遠相訪，曩情殊不迷。","簷前舉醇醪，竈下烹雙雞。","朔風忽振蕩，昨夜寒螿啼。","遊子益思歸，罷琴傷解攜。","出門盡原野，白日黯已低。","始驚道路難，終念言笑暌。","因聲謝岑壑，歲暮一攀躋。"]', '["昔余涉漳水，驱车行鄴西。","遙见林慮山，蒼蒼戛天倪。","邂逅逢爾曹，说君彼巖棲。","蘿徑垂野蔓，石房倚云梯。","秋韭何青青，藥苗數百畦。","栗林隘谷口，栝樹森廻谿。","耕耘有山田，紡績有山妻。","人生苟如此，何必組與珪。","誰謂远相訪，曩情殊不迷。","簷前舉醇醪，竈下烹雙雞。","朔风忽振蕩，昨夜寒螿啼。","游子益思归，罷琴傷解携。","出门尽原野，白日黯已低。","始驚道路难，終念言笑暌。","因声謝岑壑，歲暮一攀躋。"]', '诗', 'shi', '', NULL, '宋中遇林盧楊十七山人因而有別 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b458468f-a5c3-44a5-aa38-29e8ab8f3533', '酬別薛三蔡大留簡韓十四主簿', '酬別薛三蔡大留簡韓十四主簿', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["迢遞辭京華，辛勤異鄉縣。","登高俯滄海，廻首淚如霰。","同人久離別，失路還相見。","薛侯懷直道，德業應時選。","蔡子負清才，當年擢賓薦。","韓公有奇節，詞賦凌羣彥。","讀書嵩岑間，作吏滄海甸。","伊余寡棲託，感激多慍見。","縱誕非爾情，飄淪任疵賤。","忽枉瓊瑤作，乃深平生眷。","始謂吾道存，終嗟客遊倦。","歸心無晝夜，別事除言宴。","復值涼風時，蒼茫夏雲變。"]', '["迢遞辞京华，辛勤異乡縣。","登高俯滄海，廻首泪如霰。","同人久離別，失路還相见。","薛侯懷直道，德業應时選。","蔡子負清才，當年擢賓薦。","韓公有奇節，词賦凌羣彥。","读书嵩岑间，作吏滄海甸。","伊余寡棲託，感激多慍见。","縱誕非爾情，飄淪任疵賤。","忽枉瓊瑤作，乃深平生眷。","始謂吾道存，終嗟客游倦。","归心無晝夜，別事除言宴。","复值涼风时，蒼茫夏云变。"]', '诗', 'shi', '', NULL, '酬別薛三蔡大留簡韓十四主簿 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01f00674-7790-44fb-86fb-40ba014c2bd2', '送虞城劉明府謁魏郡苗太守', '送虞城劉明府謁魏郡苗太守', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["天官蒼生望，出入承明廬。","肅肅領舊藩，皇皇降璽書。","茂宰多感激，良將復吹噓。","永懷一言合，誰謂千里疎。","對酒忽命駕，茲情何起予。","炎天晝如火，極目無行車。","長路出雷澤，浮雲歸孟諸。","魏郡十萬家，歌鐘喧里閭。","傳道賢君至，閉關常晏如。","君將挹高論，定是問樵漁。","今日逢明聖，吾爲陶隱居。"]', '["天官蒼生望，出入承明廬。","肅肅領旧藩，皇皇降璽书。","茂宰多感激，良將复吹噓。","永懷一言合，誰謂千里疎。","对酒忽命駕，茲情何起予。","炎天晝如火，極目無行车。","长路出雷澤，浮云归孟諸。","魏郡十万家，歌鐘喧里閭。","傳道賢君至，閉关常晏如。","君將挹高論，定是问樵漁。","今日逢明聖，吾爲陶隐居。"]', '诗', 'shi', '', NULL, '送虞城劉明府謁魏郡苗太守 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('108dcb9b-73b4-4157-9269-32514cd5dc3e', '途中酬李少府贈別之作', '途中酬李少府贈別之作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["西上逢節換，東征私自憐。","故人今臥疾，欲別還留連。","舉酒臨南軒，夕陽滿中筵。","寧知江上興，乃在河梁偏。","行李多光輝，札翰忽相鮮。","誰謂歲月晚，交情尚貞堅。","終嗟州縣勞，官謗復迍邅。","雖負忠信美，其如方寸懸。","連帥扇清風，千里猶眼前。","曾是趨藻鏡，不應翻棄捐。","日來知自強，風氣殊未痊。","可以加藥物，胡爲輙憂煎。","驅馬出大梁，原野一悠然。","柳色感行客，雲陰愁遠天。","皇明燭幽遐，德澤普照宣。","鵷鴻列霄漢，燕雀何翩翩。","余亦愜所從，漁樵十二年。","種瓜漆園裏，鑿井盧門邊。","去去勿重陳，生涯難勉旃。","或期遇春事，與爾復周旋。","投報空回首，狂歌謝比肩。"]', '["西上逢節換，东征私自怜。","故人今臥疾，欲別還留連。","舉酒臨南軒，夕陽满中筵。","寧知江上兴，乃在河梁偏。","行李多光輝，札翰忽相鲜。","誰謂歲月晚，交情尚貞堅。","終嗟州縣勞，官謗复迍邅。","雖負忠信美，其如方寸懸。","連帥扇清风，千里猶眼前。","曾是趨藻镜，不應翻棄捐。","日来知自強，风氣殊未痊。","可以加藥物，胡爲輙憂煎。","驱马出大梁，原野一悠然。","柳色感行客，云陰愁远天。","皇明燭幽遐，德澤普照宣。","鵷鴻列霄漢，燕雀何翩翩。","余亦愜所從，漁樵十二年。","種瓜漆园裏，鑿井盧门邊。","去去勿重陳，生涯难勉旃。","或期遇春事，與爾复周旋。","投報空回首，狂歌謝比肩。"]', '诗', 'shi', '', NULL, '途中酬李少府贈別之作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fc37ad3-7f3b-466e-aad1-e00a080fdf1d', '睢陽酬別暢大判官', '睢陽酬別暢大判官', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["吾友遇知己，策名逢聖朝。","高才擅白雪，逸翰懷青霄。","承詔選嘉賓，慨然即馳軺。","清晝下公館，尺書忽相邀。","留歡惜別離，畢景駐行鑣。","言及沙漠事，益令胡馬驕。","丈夫拔東蕃，聲冠霍嫖姚。","兜鍪衝矢石，鐵甲生風飆。","諸將出冷陘，連營濟石橋。","酋豪盡俘馘，子弟輸征徭。","邊庭絕刁斗，戰地成漁樵。","榆關夜不扃，塞口長蕭蕭。","降胡滿薊門，一一能射鵰。","軍中多宴樂，馬上何輕趫。","戎狄本無厭，羇縻非一朝。","飢附誠足用，飽飛安可招。","李牧制儋藍，遺風豈寂寥。","君還謝幕府，慎勿輕芻蕘。"]', '["吾友遇知己，策名逢聖朝。","高才擅白雪，逸翰懷青霄。","承詔選嘉賓，慨然即驰軺。","清晝下公館，尺书忽相邀。","留歡惜別離，畢景駐行鑣。","言及沙漠事，益令胡马驕。","丈夫拔东蕃，声冠霍嫖姚。","兜鍪衝矢石，鐵甲生风飆。","諸將出冷陘，連營濟石橋。","酋豪尽俘馘，子弟輸征徭。","邊庭絕刁斗，戰地成漁樵。","榆关夜不扃，塞口长蕭蕭。","降胡满薊门，一一能射鵰。","軍中多宴乐，马上何轻趫。","戎狄本無厭，羇縻非一朝。","飢附誠足用，飽飞安可招。","李牧制儋藍，遺风豈寂寥。","君還謝幕府，慎勿轻芻蕘。"]', '诗', 'shi', '', NULL, '睢陽酬別暢大判官 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('482ab10e-32bb-455b-8208-204f55f6d37f', '宴韋司戶山亭院', '宴韋司戶山亭院', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["人幽想靈山，意愜憐遠水。","習靜務爲適，所居還復爾。","汲流漲華池，開酌宴君子。","苔逕試窺踐，石屏可攀倚。","入門見中峰，攜手如萬里。","橫琴了無事，垂釣應有以。","高館何沈沈，颯然涼風起。"]', '["人幽想靈山，意愜怜远水。","習静務爲適，所居還复爾。","汲流漲华池，开酌宴君子。","苔逕試窺踐，石屏可攀倚。","入门见中峰，携手如万里。","橫琴了無事，垂釣應有以。","高館何沈沈，颯然涼风起。"]', '诗', 'shi', '', NULL, '宴韋司戶山亭院 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a491ab1b-43b6-4757-b3bb-9e984de2b5d9', '同諸公登慈恩寺浮圖', '同諸公登慈恩寺浮圖', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["香界泯羣有，浮圖豈諸相。","登臨駭孤高，披拂欣大壯。","言是羽翼生，迥出虛空上。","頓疑身世別，乃覺形神王。","宮闕皆戶前，山河盡簷向。","秋風昨夜至，秦塞多清曠。","千里何蒼蒼，五陵鬱相望。","盛時慙阮步，末宦知周防。","輸效獨無因，斯焉可遊放。"]', '["香界泯羣有，浮圖豈諸相。","登臨駭孤高，披拂欣大壯。","言是羽翼生，迥出虛空上。","頓疑身世別，乃覺形神王。","宮闕皆戶前，山河尽簷向。","秋风昨夜至，秦塞多清曠。","千里何蒼蒼，五陵鬱相望。","盛时慙阮步，末宦知周防。","輸效独無因，斯焉可游放。"]', '诗', 'shi', '', NULL, '同諸公登慈恩寺浮圖 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c75cce0-2e86-4277-bef4-dd0fe6b1c1aa', '同薛司直諸公秋霽曲江俯見南山作', '同薛司直諸公秋霽曲江俯见南山作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["南山鬱初霽，曲江湛不流。","若臨瑤池前，想望崑崙丘。","廻首見黛色，眇然波上秋。","深沈俯崢嶸，清淺延阻修。","連潭萬木影，插岸千巖幽。","杳靄信難測，淵淪無暗投。","片雲對漁父，獨鳥隨虛舟。","我心寄青霞，世事慙白鷗。","得意在乘興，忘懷非外求。","良辰自多暇，欣與數子遊。"]', '["南山鬱初霽，曲江湛不流。","若臨瑤池前，想望崑崙丘。","廻首见黛色，眇然波上秋。","深沈俯崢嶸，清淺延阻修。","連潭万木影，插岸千巖幽。","杳靄信难測，淵淪無暗投。","片云对漁父，独鸟隨虛舟。","我心寄青霞，世事慙白鷗。","得意在乘兴，忘懷非外求。","良辰自多暇，欣與數子游。"]', '诗', 'shi', '', NULL, '同薛司直諸公秋霽曲江俯見南山作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98c02d61-b06c-46b4-b775-bf43c1362cde', '登廣陵棲靈寺塔', '登廣陵棲靈寺塔', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["淮南富登臨，茲塔信奇最。","直上造雲族，憑虛納天籟。","迥然碧海西，獨立飛鳥外。","始知高興盡，適與賞心會。","連山黯吳門，喬木吞楚塞。","城池滿窗下，物象歸掌內。","遠思駐江帆，暮時結春靄。","軒車疑蠢動，造化資大塊。","何必了無身，然後知所退。"]', '["淮南富登臨，茲塔信奇最。","直上造云族，憑虛納天籟。","迥然碧海西，独立飞鸟外。","始知高兴尽，適與賞心會。","連山黯吳门，喬木吞楚塞。","城池满窗下，物象归掌內。","远思駐江帆，暮时結春靄。","軒车疑蠢动，造化資大塊。","何必了無身，然後知所退。"]', '诗', 'shi', '', NULL, '登廣陵棲靈寺塔 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d42cb59a-2f8d-4fe9-9db7-1e973995ef42', '登百丈峰二首 一', '登百丈峰二首 一', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["朝登百丈峰，遙望燕支道。","漢壘青冥間，胡天白如掃。","憶昔霍將軍，連年此征討。","匈奴終不滅，寒山徒草草。","唯見鴻雁飛，令人傷懷抱。"]', '["朝登百丈峰，遙望燕支道。","漢壘青冥间，胡天白如掃。","憶昔霍將軍，連年此征討。","匈奴終不滅，寒山徒草草。","唯见鴻雁飞，令人傷懷抱。"]', '诗', 'shi', '', NULL, '登百丈峰二首 一 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2163cf8-fdf0-4c2b-a57e-feee532938a4', '登百丈峰二首 二', '登百丈峰二首 二', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["晉武輕後事，惠皇終已昏。","豺狼塞瀍洛，胡羯爭乾坤。","四海如鼎沸，五原徒自尊。","而今白庭路，猶對青陽門。","朝市不足問，君臣隨草根。"]', '["晉武轻後事，惠皇終已昏。","豺狼塞瀍洛，胡羯爭乾坤。","四海如鼎沸，五原徒自尊。","而今白庭路，猶对青陽门。","朝市不足问，君臣隨草根。"]', '诗', 'shi', '', NULL, '登百丈峰二首 二 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b86dfe06-639c-446e-ac96-298a1403d16e', '同羣公秋登琴臺', '同羣公秋登琴台', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["古跡使人感，琴臺空寂寥。","靜然顧遺塵，千載如昨朝。","臨眺自茲始，羣賢久相邀。","德與形神高，孰知天地遙。","四時何倏忽，六月鳴秋蜩。","萬象歸白帝，平川橫赤霄。","猶是對夏伏，幾時有涼飆。","燕雀滿簷楹，鴻鵠摶扶搖。","物性各自得，我心在漁樵。","兀然還復醉，尚握尊中瓢。"]', '["古跡使人感，琴台空寂寥。","静然顧遺塵，千載如昨朝。","臨眺自茲始，羣賢久相邀。","德與形神高，孰知天地遙。","四时何倏忽，六月鳴秋蜩。","万象归白帝，平川橫赤霄。","猶是对夏伏，幾时有涼飆。","燕雀满簷楹，鴻鵠摶扶搖。","物性各自得，我心在漁樵。","兀然還复醉，尚握尊中瓢。"]', '诗', 'shi', '', NULL, '同羣公秋登琴臺 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6078251-050b-4d8b-b77c-f416392eecf8', '同羣公出獵海上', '同羣公出獵海上', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["畋獵自古昔，況伊心賞俱。","偶與羣公遊，曠然出平蕪。","層陰漲溟海，殺氣窮幽都。","鷹隼何翩翩，馳驟相傳呼。","豺狼竄榛莽，麋鹿罹艱虞。","高鳥下騂弓，困獸鬬匹夫。","塵驚大澤晦，火燎深林枯。","失之有餘恨，獲者無全軀。","咄彼工拙間，恨非指蹤徒。","猶懷老氏訓，感歎此歡娛。"]', '["畋獵自古昔，況伊心賞俱。","偶與羣公游，曠然出平蕪。","層陰漲溟海，殺氣窮幽都。","鷹隼何翩翩，驰驟相傳呼。","豺狼竄榛莽，麋鹿罹艱虞。","高鸟下騂弓，困獸鬬匹夫。","塵驚大澤晦，火燎深林枯。","失之有餘恨，獲者無全軀。","咄彼工拙间，恨非指蹤徒。","猶懷老氏訓，感歎此歡娛。"]', '诗', 'shi', '', NULL, '同羣公出獵海上 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b0eb975-d6fd-4b70-b6e6-a8ee5bbd6563', '同羣公題鄭少府田家', '同羣公題鄭少府田家', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["鄭侯應悽惶，五十頭盡白。","昔爲南昌尉，今作東郡客。","與語多遠情，論心知所益。","秋林既清曠，窮巷空淅瀝。","蝶舞園更閑，雞鳴日云夕。","男兒未稱意，其道固無適。","勸君且杜門，勿歎人事隔。"]', '["鄭侯應悽惶，五十头尽白。","昔爲南昌尉，今作东郡客。","與語多远情，論心知所益。","秋林既清曠，窮巷空淅瀝。","蝶舞园更闲，雞鳴日云夕。","男兒未稱意，其道固無適。","勸君且杜门，勿歎人事隔。"]', '诗', 'shi', '', NULL, '同羣公題鄭少府田家 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36dc18a5-470c-48eb-adb5-3c3c151851fb', '同羣公題中山寺', '同羣公題中山寺', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["平原十里外，稍稍雲巖深。","遂及清淨所，都無人世心。","名僧既禮謁，高閣復登臨。","石壁倚松徑，山田多栗林。","超遙盡巘崿，逼側仍嶇嶔。","吾欲休世事，於焉聊自任。"]', '["平原十里外，稍稍云巖深。","遂及清淨所，都無人世心。","名僧既禮謁，高閣复登臨。","石壁倚松徑，山田多栗林。","超遙尽巘崿，逼側仍嶇嶔。","吾欲休世事，於焉聊自任。"]', '诗', 'shi', '', NULL, '同羣公題中山寺 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d968574-77fb-46e2-9594-d31f60408227', '同羣公宿開善寺贈陳十六所居', '同羣公宿开善寺贈陳十六所居', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["駕車出人境，避暑投僧家。","裴回龍象側，始見香林花。","讀書不及經，飲酒不勝茶。","知君悟此道，所未搜袈裟。","談空忘外物，持誡破諸邪。","則是無心地，相看唯月華。"]', '["駕车出人境，避暑投僧家。","裴回龙象側，始见香林花。","读书不及經，饮酒不勝茶。","知君悟此道，所未搜袈裟。","談空忘外物，持誡破諸邪。","則是無心地，相看唯月华。"]', '诗', 'shi', '', NULL, '同羣公宿開善寺贈陳十六所居 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9c7a087-4ff1-4367-a310-79116ad7f9bd', '同韓四薛三東亭翫月', '同韓四薛三东亭翫月', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["遠遊悵不樂，茲賞吾道存。","款曲故人意，辛勤清夜言。","東亭何寥寥，佳境無朝昏。","堦墀近洲渚，戶牖當郊原。","矧乃窮周旋，游時怡討論。","樹陰蕩瑤瑟，月氣延清尊。","明河帶飛雁，野火連荒村。","對此更愁予，悠哉懷故園。"]', '["远游悵不乐，茲賞吾道存。","款曲故人意，辛勤清夜言。","东亭何寥寥，佳境無朝昏。","堦墀近洲渚，戶牖當郊原。","矧乃窮周旋，游时怡討論。","樹陰蕩瑤瑟，月氣延清尊。","明河带飞雁，野火連荒村。","对此更愁予，悠哉懷故园。"]', '诗', 'shi', '', NULL, '同韓四薛三東亭翫月 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7fe9e63-321b-4afd-8a47-3dc37dbf7ba6', '同敬八盧五汎河間清河', '同敬八盧五汎河间清河', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["清川在城下，沿汎多所宜。","同濟愜數公，翫物欣良時。","飄颻波上興，燕婉舟中詞。","昔陟乃平原，今來忽漣漪。","東流達滄海，西流延滹池。","雲樹共晦明，井邑相逶迤。","稍隨歸月帆，若與沙鷗期。","漁父更留我，前潭水未滋。"]', '["清川在城下，沿汎多所宜。","同濟愜數公，翫物欣良时。","飄颻波上兴，燕婉舟中词。","昔陟乃平原，今来忽漣漪。","东流達滄海，西流延滹池。","云樹共晦明，井邑相逶迤。","稍隨归月帆，若與沙鷗期。","漁父更留我，前潭水未滋。"]', '诗', 'shi', '', NULL, '同敬八盧五汎河間清河 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f38c1894-0609-4b47-b3d9-48e1b6543efe', '同房侍御山園新亭與邢判官同遊', '同房侍御山园新亭與邢判官同游', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["隱隱春城外，朦朧陳跡深。","君子顧榛莽，興言傷古今。","決河導新流，疏逕蹤舊林。","開亭俯川陸，時景宜招尋。","肅穆逢使軒，夤緣事登臨。","忝遊芝蘭室，還對桃李陰。","岸遠白波來，氣喧黃鳥吟。","因睹歌頌作，始知經濟心。","灌壇有遺風，單父多鳴琴。","誰爲久州縣，蒼生懷德音。"]', '["隐隐春城外，朦朧陳跡深。","君子顧榛莽，兴言傷古今。","決河導新流，疏逕蹤旧林。","开亭俯川陸，时景宜招尋。","肅穆逢使軒，夤緣事登臨。","忝游芝蘭室，還对桃李陰。","岸远白波来，氣喧黄鸟吟。","因睹歌頌作，始知經濟心。","灌壇有遺风，單父多鳴琴。","誰爲久州縣，蒼生懷德音。"]', '诗', 'shi', '', NULL, '同房侍御山園新亭與邢判官同遊 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b39ad3db-8f27-43c9-a11d-9b16e5259431', '同馬太守聽九思法師講金剛經', '同马太守听九思法師講金剛經', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["吾師晉陽寶，傑出山河最。","途經世諦間，心到空王外。","鳴鐘山虎伏，說法天龍會。","了義同建瓴，梵法若吹籟。","深知億劫苦，善喻恆沙大。","捨施割肌膚，攀緣去親愛。","招提何清淨，良牧駐輕蓋。","露冕衆香中，臨人覺苑內。","心持佛印久，標割魔軍退。","願開初地因，永奉彌天對。"]', '["吾師晉陽寶，傑出山河最。","途經世諦间，心到空王外。","鳴鐘山虎伏，说法天龙會。","了義同建瓴，梵法若吹籟。","深知億劫苦，善喻恆沙大。","捨施割肌膚，攀緣去親愛。","招提何清淨，良牧駐轻蓋。","露冕衆香中，臨人覺苑內。","心持佛印久，標割魔軍退。","願开初地因，永奉彌天对。"]', '诗', 'shi', '', NULL, '同馬太守聽九思法師講金剛經 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50d852c5-4091-413a-a002-bb048d74dcc7', '漣上題樊氏水亭', '漣上題樊氏水亭', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["漣上非所趣，偶爲世務牽。","經時駐歸棹，日夕對平川。","莫論行子愁，且得主人賢。","亭上酒初熟，廚中魚每鮮。","自說宦遊來，因之居住偏。","煮鹽滄海曲，種稻長淮邊。","四時常晏如，百口無飢年。","菱芋藩籬下，漁樵耳目前。","異縣少朋從，我行復迍邅。","向不逢此君，孤舟已言旋。","明日又分首，風濤還眇然。"]', '["漣上非所趣，偶爲世務牽。","經时駐归棹，日夕对平川。","莫論行子愁，且得主人賢。","亭上酒初熟，廚中鱼每鲜。","自说宦游来，因之居住偏。","煮鹽滄海曲，種稻长淮邊。","四时常晏如，百口無飢年。","菱芋藩籬下，漁樵耳目前。","異縣少朋從，我行复迍邅。","向不逢此君，孤舟已言旋。","明日又分首，风濤還眇然。"]', '诗', 'shi', '', NULL, '漣上題樊氏水亭 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e07c9276-01df-4b93-9d66-6d0f5d3904e6', '同呂判官從哥舒大夫破洪濟城廻登積石軍多福七級浮圖', '同呂判官從哥舒大夫破洪濟城廻登積石軍多福七級浮圖', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["塞口連濁河，轅門對山寺。","寧知鞍馬上，獨有登臨事。","七級凌太清，千崖列蒼翠。","飄飄方寓目，想像見深意。","高興殊未平，涼風颯然至。","拔城陣雲合，轉斾胡星墜。","大將何英靈，官軍動天地。","君懷生羽翼，本欲附騏驥。","款段苦不前，清冥信難致。","一歌陽春後，三歎終自愧。"]', '["塞口連濁河，轅门对山寺。","寧知鞍马上，独有登臨事。","七級凌太清，千崖列蒼翠。","飄飄方寓目，想像见深意。","高兴殊未平，涼风颯然至。","拔城陣云合，轉斾胡星墜。","大將何英靈，官軍动天地。","君懷生羽翼，本欲附騏驥。","款段苦不前，清冥信难致。","一歌陽春後，三歎終自愧。"]', '诗', 'shi', '', NULL, '同呂判官從哥舒大夫破洪濟城廻登積石軍多福七級浮圖 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ae7f676-2137-47e6-ae10-7cc96deddd94', '三君詠 魏鄭公', '三君詠 魏鄭公', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["鄭公經綸日，隋氏風塵昏。","濟代取高位，逢時敢直言。","道光先帝業，義激舊君恩。","寂寞臥龍處，英靈千載魂。"]', '["鄭公經綸日，隋氏风塵昏。","濟代取高位，逢时敢直言。","道光先帝業，義激旧君恩。","寂寞臥龙处，英靈千載魂。"]', '诗', 'shi', '', NULL, '三君詠 魏鄭公 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c521179-7dd9-49a9-8b29-c7331d8870d0', '三君詠 郭代公', '三君詠 郭代公', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["代公實英邁，津涯浩難識。","擁兵抗矯徵，仗節歸有德。","縱橫負才智，顧盻安社稷。","流落勿重陳，懷哉爲悽惻。"]', '["代公實英邁，津涯浩难識。","擁兵抗矯徵，仗節归有德。","縱橫負才智，顧盻安社稷。","流落勿重陳，懷哉爲悽惻。"]', '诗', 'shi', '', NULL, '三君詠 郭代公 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f069771-1d5d-48e9-abb5-3ecbb9167700', '三君詠 狄梁公', '三君詠 狄梁公', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["梁公乃貞固，勳烈垂竹帛。","昌言太后朝，潛運儲君策。","待賢開相府，共理登方伯。","至今青雲人，猶是門下客。"]', '["梁公乃貞固，勳烈垂竹帛。","昌言太后朝，潛運儲君策。","待賢开相府，共理登方伯。","至今青云人，猶是门下客。"]', '诗', 'shi', '', NULL, '三君詠 狄梁公 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caeb5c1f-6a0e-4701-9158-9f403db9c47e', '宓公琴臺詩三首 一', '宓公琴台诗三首 一', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["宓子昔爲政，鳴琴登此臺。","琴和人亦閑，千載稱其才。","臨眺忽悽愴，人琴安在哉？","悠悠此天壤，唯有頌聲來。"]', '["宓子昔爲政，鳴琴登此台。","琴和人亦闲，千載稱其才。","臨眺忽悽愴，人琴安在哉？","悠悠此天壤，唯有頌声来。"]', '诗', 'shi', '', NULL, '宓公琴臺詩三首 一 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('320af109-788d-45f4-8792-1e014aeda653', '宓公琴臺詩三首 二', '宓公琴台诗三首 二', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["邦伯感遺事，慨然建琴堂。","乃知靜者心，千載猶相望。","入室想其人，出門何茫茫。","唯見白雲合，東臨鄒魯鄉。"]', '["邦伯感遺事，慨然建琴堂。","乃知静者心，千載猶相望。","入室想其人，出门何茫茫。","唯见白云合，东臨鄒魯乡。"]', '诗', 'shi', '', NULL, '宓公琴臺詩三首 二 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8793edad-baed-4834-9411-199ca140b5c7', '宓公琴臺詩三首 三', '宓公琴台诗三首 三', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["皤皤邑中老，自誇邑中理。","何必升君堂，然後知君美。","開門無犬吠，早臥常晏起。","昔人不忍欺，今我還復爾。"]', '["皤皤邑中老，自誇邑中理。","何必升君堂，然後知君美。","开门無犬吠，早臥常晏起。","昔人不忍欺，今我還复爾。"]', '诗', 'shi', '', NULL, '宓公琴臺詩三首 三 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d8d3ee1-81f4-4938-8797-5dcd5be1f720', '李雲南征蠻詩', '李云南征蠻诗', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["聖人赫斯怒，詔伐西南戎。","肅穆廟堂上，深沈節制雄。","遂令感激士，得建非常功。","料死不料敵，顧恩寧顧終。","鼓行天海外，轉戰蠻夷中。","梯巘近高鳥，穿林經毒蟲。","鬼門無歸客，北戶多南風。","蜂蠆隔萬里，雲雷隨九攻。","長驅大浪破，急擊羣山空。","餉道忽已遠，懸軍垂欲窮。","精誠動白日，憤薄連蒼穹。","野食掘田鼠，晡餐兼僰僮。","收兵列亭堠，拓地彌西東。","臨事耻苟免，履危能飭躬。","將星獨照耀，邊色何溟濛。","瀘水夜可涉，交州今始通。","歸來長安道，召見甘泉宮。","廉藺若未死，孫吳知暗同。","相逢論意氣，慷慨謝深衷。"]', '["聖人赫斯怒，詔伐西南戎。","肅穆廟堂上，深沈節制雄。","遂令感激士，得建非常功。","料死不料敵，顧恩寧顧終。","鼓行天海外，轉戰蠻夷中。","梯巘近高鸟，穿林經毒蟲。","鬼门無归客，北戶多南风。","蜂蠆隔万里，云雷隨九攻。","长驱大浪破，急擊羣山空。","餉道忽已远，懸軍垂欲窮。","精誠动白日，憤薄連蒼穹。","野食掘田鼠，晡餐兼僰僮。","收兵列亭堠，拓地彌西东。","臨事耻苟免，履危能飭躬。","將星独照耀，邊色何溟濛。","瀘水夜可涉，交州今始通。","归来长安道，召见甘泉宮。","廉藺若未死，孫吳知暗同。","相逢論意氣，慷慨謝深衷。"]', '诗', 'shi', '', NULL, '李雲南征蠻詩 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d44f2dfd-d7d4-4bab-80eb-de60e198953f', '題尉遲將軍新廟', '題尉遲將軍新廟', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["周室既板蕩，賊臣立嬰兒。","將軍獨激昂，誓欲酬恩私。","孤城日無援，高節終可悲。","家國共淪亡，精魂空在斯。","沈沈積冤氣，寂寂無人知。","良牧懷深仁，與君建明祠。","父子俱血食，軒車每逶迤。","我來薦蘋蘩，感歎興此詞。","晨光上階闥，殺氣翻旌旗。","明明幽冥理，至誠信莫欺。","唯夫二千石，多慶方自茲。"]', '["周室既板蕩，賊臣立嬰兒。","將軍独激昂，誓欲酬恩私。","孤城日無援，高節終可悲。","家国共淪亡，精魂空在斯。","沈沈積冤氣，寂寂無人知。","良牧懷深仁，與君建明祠。","父子俱血食，軒车每逶迤。","我来薦蘋蘩，感歎兴此词。","晨光上階闥，殺氣翻旌旗。","明明幽冥理，至誠信莫欺。","唯夫二千石，多慶方自茲。"]', '诗', 'shi', '', NULL, '題尉遲將軍新廟 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('326cb4cd-2658-4a7a-a51d-d99ef1fc58f3', '觀李九少府翥樹宓子賤神祠碑', '观李九少府翥樹宓子賤神祠碑', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["吾友吏茲邑，亦嘗懷宓公。","安知夢寐間，忽與精靈通。","一見興永歎，再來激深衷。","賓從何逶迤，二十四老翁。","於焉建層碑，突兀長林東。","作者無愧色，行人感遺風。","坐令高岸盡，獨對秋山空。","片石勿謂輕，斯言固難窮。","龍盤色絲外，鵲顧偃波中。","形勝駐羣目，堅貞指蒼穹。","我非王仲宣，去矣徒發蒙。"]', '["吾友吏茲邑，亦嘗懷宓公。","安知梦寐间，忽與精靈通。","一见兴永歎，再来激深衷。","賓從何逶迤，二十四老翁。","於焉建層碑，突兀长林东。","作者無愧色，行人感遺风。","坐令高岸尽，独对秋山空。","片石勿謂轻，斯言固难窮。","龙盤色絲外，鵲顧偃波中。","形勝駐羣目，堅貞指蒼穹。","我非王仲宣，去矣徒發蒙。"]', '诗', 'shi', '', NULL, '觀李九少府翥樹宓子賤神祠碑 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2409c579-a1d8-4ea2-8fa5-790b0b45247e', '同觀陳十六史興碑', '同观陳十六史兴碑', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["荆衡氣偏秀，江漢流不歇。","此地多精靈，有時生才傑。","伊人今獨步，逸思能間發。","永懷掩風騷，千載常矻矻。","新碑亦崔嵬，佳句懸日月。","則是刊石經，終然繼檮杌。","我來觀雅製，慷慨變毛髮。","季主盡荒淫，前王徒貽厥。","東周既削弱，兩漢更淪沒。","西晉何披猖，五胡相唐突。","作歌乃彰善，比物仍惡訐。","感歎將謂誰，對之空咄咄。"]', '["荆衡氣偏秀，江漢流不歇。","此地多精靈，有时生才傑。","伊人今独步，逸思能间發。","永懷掩风騷，千載常矻矻。","新碑亦崔嵬，佳句懸日月。","則是刊石經，終然繼檮杌。","我来观雅製，慷慨变毛髮。","季主尽荒淫，前王徒貽厥。","东周既削弱，兩漢更淪沒。","西晉何披猖，五胡相唐突。","作歌乃彰善，比物仍惡訐。","感歎將謂誰，对之空咄咄。"]', '诗', 'shi', '', NULL, '同觀陳十六史興碑 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1cb1f76-9344-4712-a551-eac9457e519c', '宋中十首 一', '宋中十首 一', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["梁王昔全盛，賓客復多才。","悠悠一千年，陳跡唯高臺。","寂寞向秋草，悲風千里來。"]', '["梁王昔全盛，賓客复多才。","悠悠一千年，陳跡唯高台。","寂寞向秋草，悲风千里来。"]', '诗', 'shi', '', NULL, '宋中十首 一 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1082dfa9-28dd-4dfe-9e5e-e8baa0bea8ad', '宋中十首 二', '宋中十首 二', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["朝臨孟諸上，忽見芒碭間。","赤帝終已矣，白雲長不還。","時清更何有，禾黍徧空山。"]', '["朝臨孟諸上，忽见芒碭间。","赤帝終已矣，白云长不還。","时清更何有，禾黍徧空山。"]', '诗', 'shi', '', NULL, '宋中十首 二 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8edbfa08-16c6-4b38-9958-40c4cefa520a', '宋中十首 三', '宋中十首 三', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["景公德何廣，臨變莫能欺。","三請皆不忍，妖星終自移。","君心本如此，天道豈無知。"]', '["景公德何廣，臨变莫能欺。","三請皆不忍，妖星終自移。","君心本如此，天道豈無知。"]', '诗', 'shi', '', NULL, '宋中十首 三 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89a6c133-8b77-4365-960f-79e7c3991f49', '宋中十首 四', '宋中十首 四', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["梁苑白日暮，梁山秋草時。","君王不可見，脩竹令人悲。","九月桑葉盡，寒風鳴樹枝。"]', '["梁苑白日暮，梁山秋草时。","君王不可见，脩竹令人悲。","九月桑葉尽，寒风鳴樹枝。"]', '诗', 'shi', '', NULL, '宋中十首 四 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3530235e-e711-41d8-b30a-4a238a3d9ed4', '宋中十首 五', '宋中十首 五', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["登高臨舊國，懷古對窮秋。","落日鴻雁度，寒城砧杵愁。","昔賢不復有，行矣莫淹留。"]', '["登高臨旧国，懷古对窮秋。","落日鴻雁度，寒城砧杵愁。","昔賢不复有，行矣莫淹留。"]', '诗', 'shi', '', NULL, '宋中十首 五 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f57d743-cd54-4c89-bcd1-79192dc2d495', '宋中十首 六', '宋中十首 六', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["出門望終古，獨立悲且歌。","憶昔魯仲尼，悽悽此經過。","衆人不可向，伐樹將如何。"]', '["出门望終古，独立悲且歌。","憶昔魯仲尼，悽悽此經過。","衆人不可向，伐樹將如何。"]', '诗', 'shi', '', NULL, '宋中十首 六 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9ac2959-1f77-492f-9079-30c25f8af521', '宋中十首 七', '宋中十首 七', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["逍遙漆園吏，冥沒不知年。","世事浮雲外，閑居大道邊。","古來同一馬，今我亦忘筌。"]', '["逍遙漆园吏，冥沒不知年。","世事浮云外，闲居大道邊。","古来同一马，今我亦忘筌。"]', '诗', 'shi', '', NULL, '宋中十首 七 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88b7713b-419a-4972-9174-3418204f1e09', '宋中十首 八', '宋中十首 八', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["五霸遞征伐，宋人無戰功。","解圍幸奇說，易子傷吾衷。","唯見盧門外，蕭條多轉蓬。"]', '["五霸遞征伐，宋人無戰功。","解圍幸奇说，易子傷吾衷。","唯见盧门外，蕭條多轉蓬。"]', '诗', 'shi', '', NULL, '宋中十首 八 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6675460-3613-4c43-a435-5bd2f44c5e5f', '宋中十首 九', '宋中十首 九', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["常愛宓子賤，鳴琴能自親。","邑中靜無事，豈不由其身。","何意千年後，寂寞無此人。"]', '["常愛宓子賤，鳴琴能自親。","邑中静無事，豈不由其身。","何意千年後，寂寞無此人。"]', '诗', 'shi', '', NULL, '宋中十首 九 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3d18a80-f7b2-42d8-a910-ab4e51270e3a', '宋中十首 十', '宋中十首 十', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["閼伯去已久，高丘臨道傍。","人皆有兄弟，爾獨爲參商。","終古猶如此，而今安可量。"]', '["閼伯去已久，高丘臨道傍。","人皆有兄弟，爾独爲參商。","終古猶如此，而今安可量。"]', '诗', 'shi', '', NULL, '宋中十首 十 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fb95f8c-bd7b-45d7-a0f9-c61746b7cbb7', '薊中作', '薊中作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["策馬自沙漠，長驅登塞垣。","邊城何蕭條，白日黃雲昏。","一到征戰處，每愁胡虜翻。","豈無安邊書，諸將已承恩。","惆悵孫吳事，歸來獨閉門。"]', '["策马自沙漠，长驱登塞垣。","邊城何蕭條，白日黄云昏。","一到征戰处，每愁胡虜翻。","豈無安邊书，諸將已承恩。","惆悵孫吳事，归来独閉门。"]', '诗', 'shi', '', NULL, '薊中作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02feeee3-8ca8-43eb-9e53-507cd7b9a960', '自淇涉黃河途中作十三首 一', '自淇涉黄河途中作十三首 一', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["川上常極目，世情今已閑。","去帆帶落日，征路隨長山。","親友若雲霄，可望不可攀。","於茲任所愜，浩蕩風波間。"]', '["川上常極目，世情今已闲。","去帆带落日，征路隨长山。","親友若云霄，可望不可攀。","於茲任所愜，浩蕩风波间。"]', '诗', 'shi', '', NULL, '自淇涉黃河途中作十三首 一 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ec03821-1ece-4cdc-97cb-c7b976ac47b1', '自淇涉黃河途中作十三首 二', '自淇涉黄河途中作十三首 二', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["清晨泛中流，羽族滿汀渚。","黃鵠何處來，昂藏寡儔侶。","飛鳴無人見，飲啄豈得所。","雲漢爾固知，胡爲不輕舉。"]', '["清晨泛中流，羽族满汀渚。","黄鵠何处来，昂藏寡儔侶。","飞鳴無人见，饮啄豈得所。","云漢爾固知，胡爲不轻舉。"]', '诗', 'shi', '', NULL, '自淇涉黃河途中作十三首 二 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dceb62b-832f-40d9-8055-2d12282d781c', '自淇涉黃河途中作十三首 三', '自淇涉黄河途中作十三首 三', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["野人頭盡白，與我忽相訪。","手持青竹竿，日暮淇水上。","雖老美容色，雖貧亦閑放。","釣魚三十年，中心無所向。"]', '["野人头尽白，與我忽相訪。","手持青竹竿，日暮淇水上。","雖老美容色，雖貧亦闲放。","釣鱼三十年，中心無所向。"]', '诗', 'shi', '', NULL, '自淇涉黃河途中作十三首 三 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89150285-38e4-480d-87d6-95db4cb9a4ed', '自淇涉黃河途中作十三首 四', '自淇涉黄河途中作十三首 四', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["南登滑臺上，却望河淇間。","竹樹夾流水，孤城對遠山。","念茲川路闊，羨爾沙鷗閑。","長想別離處，猶無音信還。"]', '["南登滑台上，却望河淇间。","竹樹夾流水，孤城对远山。","念茲川路闊，羨爾沙鷗闲。","长想別離处，猶無音信還。"]', '诗', 'shi', '', NULL, '自淇涉黃河途中作十三首 四 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62492dd9-477c-4ce8-af80-cf9f9f895a3f', '自淇涉黃河途中作十三首 五', '自淇涉黄河途中作十三首 五', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["東入黃河水，茫茫汎紆直。","北望太行山，峨峨半天色。","山河相暎帶，深淺未可測。","自昔有賢才，相逢不相識。"]', '["东入黄河水，茫茫汎紆直。","北望太行山，峨峨半天色。","山河相暎带，深淺未可測。","自昔有賢才，相逢不相識。"]', '诗', 'shi', '', NULL, '自淇涉黃河途中作十三首 五 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbe30e55-8238-495c-bcf9-8144fe363439', '自淇涉黃河途中作十三首 六', '自淇涉黄河途中作十三首 六', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["秋日登滑臺，臺高秋已暮。","獨行既未愜，懷土悵無趣。","晉宋何蕭條，羌胡散馳騖。","當時無戰略，此地即邊戍。","兵革徒自勤，山河孰云固。","乘閑喜臨眺，感物傷遊寓。","惆悵落日前，飄颻遠帆處。","北風吹萬里，南雁不知數。","歸意方浩然，雲沙更廻互。"]', '["秋日登滑台，台高秋已暮。","独行既未愜，懷土悵無趣。","晉宋何蕭條，羌胡散驰騖。","當时無戰略，此地即邊戍。","兵革徒自勤，山河孰云固。","乘闲喜臨眺，感物傷游寓。","惆悵落日前，飄颻远帆处。","北风吹万里，南雁不知數。","归意方浩然，云沙更廻互。"]', '诗', 'shi', '', NULL, '自淇涉黃河途中作十三首 六 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0e51eac-3f11-473d-b3de-f2e9bdc1e74f', '自淇涉黃河途中作十三首 七', '自淇涉黄河途中作十三首 七', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["亂流自茲遠，倚檝時一望。","遙見楚漢城，崔嵬高山上。","天道昔未測，人心無所向。","屠釣稱侯王，龍蛇爭霸王。","緬懷多殺戮，顧此生慘愴。","聖代休甲兵，吾其得閑放。"]', '["亂流自茲远，倚檝时一望。","遙见楚漢城，崔嵬高山上。","天道昔未測，人心無所向。","屠釣稱侯王，龙蛇爭霸王。","緬懷多殺戮，顧此生慘愴。","聖代休甲兵，吾其得闲放。"]', '诗', 'shi', '', NULL, '自淇涉黃河途中作十三首 七 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45e93c66-046f-44aa-9752-7e4246ad6c43', '自淇涉黃河途中作十三首 八', '自淇涉黄河途中作十三首 八', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["茲川方悠邈，雲沙無前後。","古堰對河壖，長林出淇口。","獨行非吾意，東向日已久。","憂來誰得知，且酌尊中酒。"]', '["茲川方悠邈，云沙無前後。","古堰对河壖，长林出淇口。","独行非吾意，东向日已久。","憂来誰得知，且酌尊中酒。"]', '诗', 'shi', '', NULL, '自淇涉黃河途中作十三首 八 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb5a52a2-c14b-4302-b5b1-ab18d92348ab', '自淇涉黃河途中作十三首 九', '自淇涉黄河途中作十三首 九', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["朝從北岸來，泊船南河滸。","試共野人言，深覺農夫苦。","去秋雖薄熟，今夏猶未雨。","耕耘日勤勞，租稅兼舃鹵。","園蔬空寥落，產業不足數。","尚有獻芹心，無因見明主。"]', '["朝從北岸来，泊船南河滸。","試共野人言，深覺農夫苦。","去秋雖薄熟，今夏猶未雨。","耕耘日勤勞，租稅兼舃鹵。","园蔬空寥落，產業不足數。","尚有獻芹心，無因见明主。"]', '诗', 'shi', '', NULL, '自淇涉黃河途中作十三首 九 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cea51298-9d8e-468f-a075-8e843c97e018', '自淇涉黃河途中作十三首 十', '自淇涉黄河途中作十三首 十', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["茫茫濁河注，懷古臨河濱。","禹功本豁達，漢跡方因循。","坎德昔滂沱，馮夷胡不仁。","激潏陵堤防，東郡多悲辛。","天子忽驚悼，從官皆負薪。","畚築豈無謀，祈禱如有神。","宣房今安在，高岸空嶙峋。"]', '["茫茫濁河注，懷古臨河濱。","禹功本豁達，漢跡方因循。","坎德昔滂沱，馮夷胡不仁。","激潏陵堤防，东郡多悲辛。","天子忽驚悼，從官皆負薪。","畚築豈無謀，祈禱如有神。","宣房今安在，高岸空嶙峋。"]', '诗', 'shi', '', NULL, '自淇涉黃河途中作十三首 十 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c501f17a-230a-49b5-833c-5889a4e9bc85', '自淇涉黃河途中作十三首 十一', '自淇涉黄河途中作十三首 十一', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["我行倦風湍，輟棹將問津。","空傳歌瓠子，感慨獨愁人。","孟夏桑葉肥，穠陰夾長津。","蠶農有時節，田野無閑人。","臨水狎漁樵，望山懷隱淪。","誰能去京洛，顦顇對風塵。"]', '["我行倦风湍，輟棹將问津。","空傳歌瓠子，感慨独愁人。","孟夏桑葉肥，穠陰夾长津。","蠶農有时節，田野無闲人。","臨水狎漁樵，望山懷隐淪。","誰能去京洛，顦顇对风塵。"]', '诗', 'shi', '', NULL, '自淇涉黃河途中作十三首 十一 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9811b91-7522-46d2-ae55-63d63968adca', '自淇涉黃河途中作十三首 十二', '自淇涉黄河途中作十三首 十二', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["朝景入平川，川長復垂柳。","遙看魏公墓，突兀前山後。","憶昔大業時，羣雄角奔走。","伊人何電邁，獨立風塵首。","傳檄舉敖倉，擁兵屯洛口。","連營一百萬，六合如可有。","方項終比肩，亂隋將假手。","力爭固難恃，驕戰曷能久。","若使學蕭曹，功名當不朽。"]', '["朝景入平川，川长复垂柳。","遙看魏公墓，突兀前山後。","憶昔大業时，羣雄角奔走。","伊人何電邁，独立风塵首。","傳檄舉敖倉，擁兵屯洛口。","連營一百万，六合如可有。","方項終比肩，亂隋將假手。","力爭固难恃，驕戰曷能久。","若使学蕭曹，功名當不朽。"]', '诗', 'shi', '', NULL, '自淇涉黃河途中作十三首 十二 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef119060-f85f-444a-a103-4a07a56d1202', '自淇涉黃河途中作十三首 十三', '自淇涉黄河途中作十三首 十三', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["皤皤河濱叟，相遇似有耻。","輟榜聊問之，荅言盡終結。","一生雖貧賤，九十年未死。","且喜對兒孫，彌慙遠城市。","結廬黃河曲，垂釣長河裏。","漫漫望雲沙，蕭條聽風水。","所思強飯食，永願在鄉里。","萬事吾不知，其心只如此。"]', '["皤皤河濱叟，相遇似有耻。","輟榜聊问之，荅言尽終結。","一生雖貧賤，九十年未死。","且喜对兒孫，彌慙远城市。","結廬黄河曲，垂釣长河裏。","漫漫望云沙，蕭條听风水。","所思強飯食，永願在乡里。","万事吾不知，其心只如此。"]', '诗', 'shi', '', NULL, '自淇涉黃河途中作十三首 十三 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efb2f4fe-cbfc-424a-9980-7015cd556941', '宋中遇陳二', '宋中遇陳二', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["常忝鮑叔義，所期王佐才。","如何守苦節，獨此無良媒。","離別十年外，飄颻千里來。","安知罷官後，惟見柴門開。","窮巷隱東郭，高堂詠南陔。","籬根長花草，井上生莓苔。","伊昔望霄漢，於今倦蒿萊。","男兒命未達，且盡手中桮。"]', '["常忝鲍叔義，所期王佐才。","如何守苦節，独此無良媒。","離別十年外，飄颻千里来。","安知罷官後，惟见柴门开。","窮巷隐东郭，高堂詠南陔。","籬根长花草，井上生莓苔。","伊昔望霄漢，於今倦蒿萊。","男兒命未達，且尽手中桮。"]', '诗', 'shi', '', NULL, '宋中遇陳二 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd99fae2-e492-43a5-991d-5febb80ba51d', '宋中遇劉書記有別', '宋中遇劉书記有別', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["何代無秀士，高門生此才。","森然覩毛髮，若見河山來。","幾載困常調，一朝時運催。","白身謁明主，待詔登雲臺。","相逢梁宋間，與我醉蒿萊。","寒楚眇千里，雪天晝不開。","末路終離別，不能強悲哀。","男兒爭富貴，勸爾莫遲廻。"]', '["何代無秀士，高门生此才。","森然覩毛髮，若见河山来。","幾載困常調，一朝时運催。","白身謁明主，待詔登云台。","相逢梁宋间，與我醉蒿萊。","寒楚眇千里，雪天晝不开。","末路終離別，不能強悲哀。","男兒爭富貴，勸爾莫遲廻。"]', '诗', 'shi', '', NULL, '宋中遇劉書記有別 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50d96cb2-de4f-4cbe-bf62-3159b077d2f6', '魯郡途中遇徐十八錄事', '魯郡途中遇徐十八錄事', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["誰謂嵩潁客，遂經鄒魯鄉。","前臨少昊墟，始覺東蒙長。","獨行豈吾心，懷古激中腸。","聖人久已矣，游夏遙相望。","裴回野澤間，左右多悲傷。","日出見闕里，川平知汶陽。","弱冠負高節，十年思自強。","終然不得意，去去任行藏。"]', '["誰謂嵩潁客，遂經鄒魯乡。","前臨少昊墟，始覺东蒙长。","独行豈吾心，懷古激中腸。","聖人久已矣，游夏遙相望。","裴回野澤间，左右多悲傷。","日出见闕里，川平知汶陽。","弱冠負高節，十年思自強。","終然不得意，去去任行藏。"]', '诗', 'shi', '', NULL, '魯郡途中遇徐十八錄事 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ca1c436-1a66-4274-94b3-12c87aae8f73', '遇沖和先生', '遇沖和先生', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["沖和生何代，或謂遊東溟。","三命謁金殿，一言拜銀青。","自云多方術，往往通神靈。","萬乘親問道，六宮無敢聽。","昔去限霄漢，今來覩儀形。","頭戴鶡鳥冠，手遙白鶴翎。","終日飲醇酒，不醉復不醒。","常憶雞鳴山，每誦西昇經。","拊背念離別，依然出戶庭。","莫見今如此，曾爲一客星。"]', '["沖和生何代，或謂游东溟。","三命謁金殿，一言拜銀青。","自云多方術，往往通神靈。","万乘親问道，六宮無敢听。","昔去限霄漢，今来覩儀形。","头戴鶡鸟冠，手遙白鹤翎。","終日饮醇酒，不醉复不醒。","常憶雞鳴山，每誦西昇經。","拊背念離別，依然出戶庭。","莫见今如此，曾爲一客星。"]', '诗', 'shi', '', NULL, '遇沖和先生 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d533a0a3-9b2f-4242-be08-532ac4eb526d', '魯西至東平', '魯西至东平', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["沙岸拍不定，石橋水橫流。","問津見魯俗，懷古傷家丘。","寥落千載後，空傳褒聖侯。"]', '["沙岸拍不定，石橋水橫流。","问津见魯俗，懷古傷家丘。","寥落千載後，空傳褒聖侯。"]', '诗', 'shi', '', NULL, '魯西至東平 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('781223c9-12d7-42f1-8a53-273d4a032a11', '東平路作三首 一', '东平路作三首 一', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["南圖適不就，東走豈吾心。","索索涼風動，行行秋水深。","蟬鳴木葉落，茲夕更愁霖。"]', '["南圖適不就，东走豈吾心。","索索涼风动，行行秋水深。","蟬鳴木葉落，茲夕更愁霖。"]', '诗', 'shi', '', NULL, '東平路作三首 一 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a01fffef-b801-4397-958b-8435953a1802', '東平路作三首 二', '东平路作三首 二', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["明時好畫策，動欲干王公。","今日無成事，依依親老農。","扁舟向何處？吾愛汶陽中。"]', '["明时好畫策，动欲干王公。","今日無成事，依依親老農。","扁舟向何处？吾愛汶陽中。"]', '诗', 'shi', '', NULL, '東平路作三首 二 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5249aa5-2cf7-4e8f-b031-c4796e6b246c', '東平路作三首 三', '东平路作三首 三', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["清曠涼夜月，裴回孤客舟。","渺然風波上，獨愛前山秋。","秋至復搖落，空令行者愁。"]', '["清曠涼夜月，裴回孤客舟。","渺然风波上，独愛前山秋。","秋至复搖落，空令行者愁。"]', '诗', 'shi', '', NULL, '東平路作三首 三 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('760090ec-525e-4d37-bc53-fd01dd495681', '東平路中遇大水', '东平路中遇大水', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["天災自古有，昏墊彌今秋。","霖霪溢川原，澒洞涵田疇。","指途適汶陽，挂席經蘆洲。","永望齊魯郊，白雲何悠悠。","傍沿鉅野澤，大水縱橫流。","蟲蛇擁獨樹，麋鹿奔行舟。","稼穡隨波瀾，西成不可求。","室居相枕藉，蛙黽聲啾啾。","仍憐穴蟻漂，益羨雲禽游。","農夫無倚着，野老生殷憂。","聖主當深仁，廟堂運良籌。","倉廩終爾給，田租應罷收。","我心胡鬱陶，征旅亦悲愁。","縱懷濟時策，誰肯論吾謀。"]', '["天災自古有，昏墊彌今秋。","霖霪溢川原，澒洞涵田疇。","指途適汶陽，挂席經蘆洲。","永望齊魯郊，白云何悠悠。","傍沿鉅野澤，大水縱橫流。","蟲蛇擁独樹，麋鹿奔行舟。","稼穡隨波瀾，西成不可求。","室居相枕藉，蛙黽声啾啾。","仍怜穴蟻漂，益羨云禽游。","農夫無倚着，野老生殷憂。","聖主當深仁，廟堂運良籌。","倉廩終爾給，田租應罷收。","我心胡鬱陶，征旅亦悲愁。","縱懷濟时策，誰肯論吾謀。"]', '诗', 'shi', '', NULL, '東平路中遇大水 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcccde71-c438-4fa8-ac7a-a9ac53638a7c', '登壠', '登壠', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["壠頭遠行客，壠上分流水。","流水無盡期，行人未云已。","淺才登一命，孤劒通萬里。","豈不思故鄉，從來感知己。"]', '["壠头远行客，壠上分流水。","流水無尽期，行人未云已。","淺才登一命，孤劒通万里。","豈不思故乡，從来感知己。"]', '诗', 'shi', '', NULL, '登壠 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e598395-2064-42df-ae7a-16bf591c0695', '苦雪四首 一', '苦雪四首 一', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["二月猶北風，天陰雪冥冥。","寥落一室中，悵然慙百齡。","苦愁正如此，門柳復青青。"]', '["二月猶北风，天陰雪冥冥。","寥落一室中，悵然慙百齡。","苦愁正如此，门柳复青青。"]', '诗', 'shi', '', NULL, '苦雪四首 一 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4941ee70-92db-47bc-87d7-ba11b212025f', '苦雪四首 二', '苦雪四首 二', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["惠連發清興，袁安念高臥。","余故非斯人，爲性兼懶惰。","賴茲尊中酒，終日聊自過。"]', '["惠連發清兴，袁安念高臥。","余故非斯人，爲性兼懶惰。","賴茲尊中酒，終日聊自過。"]', '诗', 'shi', '', NULL, '苦雪四首 二 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23aa1422-258b-4783-a800-1f28dc71facd', '苦雪四首 三', '苦雪四首 三', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["濛濛灑平陸，淅瀝至幽居。","且喜潤羣物，焉能悲斗儲。","故交久不見，鳥雀投吾廬。"]', '["濛濛灑平陸，淅瀝至幽居。","且喜潤羣物，焉能悲斗儲。","故交久不见，鸟雀投吾廬。"]', '诗', 'shi', '', NULL, '苦雪四首 三 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('359bc72a-6f60-4c69-a4cd-9d579e22fc8e', '苦雪四首 四', '苦雪四首 四', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["孰云久閑曠，本自保知寡。","窮巷獨無成，春條秪盈把。","安能羨鵬舉，且欲歌牛下。","乃知古時人，亦有如我者。"]', '["孰云久闲曠，本自保知寡。","窮巷独無成，春條秪盈把。","安能羨鵬舉，且欲歌牛下。","乃知古时人，亦有如我者。"]', '诗', 'shi', '', NULL, '苦雪四首 四 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e953a74d-4075-48bb-928f-114d0cd1a9eb', '哭單父梁九少府', '哭單父梁九少府', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["開篋淚沾臆，見君前日書。","夜臺今寂寞，獨是子雲居。","疇昔探雲奇，登臨賦山水。","同舟南浦下，望月西江裏。","契闊多別離，綢繆到生死。","九原即何處，萬事皆如此。","晉山徒峨峨，斯人已冥冥。","常時祿且薄，歿後家復貧。","妻子在遠道，弟兄無一人。","十上多苦辛，一官恆自哂。","青雲將可致，白日忽先盡。","唯有身後名，空留無遠近。"]', '["开篋泪沾臆，见君前日书。","夜台今寂寞，独是子云居。","疇昔探云奇，登臨賦山水。","同舟南浦下，望月西江裏。","契闊多別離，綢繆到生死。","九原即何处，万事皆如此。","晉山徒峨峨，斯人已冥冥。","常时祿且薄，歿後家复貧。","妻子在远道，弟兄無一人。","十上多苦辛，一官恆自哂。","青云將可致，白日忽先尽。","唯有身後名，空留無远近。"]', '诗', 'shi', '', NULL, '哭單父梁九少府 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d669feeb-edbb-433a-b46f-9c302e3e7516', '哭裴少府', '哭裴少府', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["世人誰不死，嗟君非生慮。","扶病適到官，田園在何處？","公才羣吏感，葬事他人助。","余亦未識君，深悲哭君去。"]', '["世人誰不死，嗟君非生慮。","扶病適到官，田园在何处？","公才羣吏感，葬事他人助。","余亦未識君，深悲哭君去。"]', '诗', 'shi', '', NULL, '哭裴少府 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed2b4826-b408-4aec-9fbc-1d69b9f58e6d', '行路難二首 一', '行路难二首 一', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["長安少年不少錢，能騎駿馬鳴金鞭。","五侯相逢大道邊，美人弦管爭留連。","黃金如斗不敢惜，片言如山莫棄捐。","安知顦顇讀書者，暮宿靈臺私自憐。"]', '["长安少年不少錢，能騎駿马鳴金鞭。","五侯相逢大道邊，美人弦管爭留連。","黄金如斗不敢惜，片言如山莫棄捐。","安知顦顇读书者，暮宿靈台私自怜。"]', '诗', 'shi', '', NULL, '行路難二首 一 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b8079ae-910c-4680-883a-6f747712ce0d', '行路難二首 二', '行路难二首 二', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["君不見富家翁，舊時貧賤誰比數。","一朝金多結豪貴，萬事勝人健如虎。","子孫成行滿眼前，妻能管絃妾能舞。","自矜一身忽如此，却笑傍人獨愁苦。","東鄰少年安所如，席門窮巷出無車。","有才不肯學干謁，何用年年空讀書。"]', '["君不见富家翁，旧时貧賤誰比數。","一朝金多結豪貴，万事勝人健如虎。","子孫成行满眼前，妻能管絃妾能舞。","自矜一身忽如此，却笑傍人独愁苦。","东鄰少年安所如，席门窮巷出無车。","有才不肯学干謁，何用年年空读书。"]', '诗', 'shi', '', NULL, '行路難二首 二 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cb15c8b-c714-4e8c-84eb-3658b637d12e', '秋胡行', '秋胡行', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["妾本邯鄲未嫁時，容華倚翠人未知。","一朝結髮從君子，將妾迢迢東魯陲。","時逢大道無艱阻，君方遊宦從陳汝。","蕙樓獨臥頻度春，彩閣辭君幾徂暑。","三月垂楊蠶未眠，攜籠結侶南陌邊。","道逢行子不相識，贈妾黃金買少年。","妾家夫壻經離久，寸心誓與長相守。","願言行路莫多情，道妾貞心在人口。","日暮蠶飢相命歸，攜籠端飾來庭闈。","勞心苦力終無恨，所冀君恩即可依。","聞說行人已歸止，乃是向來贈金子。","相看顏色不復言，相顧懷慙有何已。","從來自隱無疑背，直爲君情也相會。","如何咫尺仍有情，況復迢迢千里外。","誓將顧恩不顧身，念君此日赴河津。","莫道向來不得意，故欲留規誡後人。"]', '["妾本邯鄲未嫁时，容华倚翠人未知。","一朝結髮從君子，將妾迢迢东魯陲。","时逢大道無艱阻，君方游宦從陳汝。","蕙楼独臥頻度春，彩閣辞君幾徂暑。","三月垂楊蠶未眠，携籠結侶南陌邊。","道逢行子不相識，贈妾黄金買少年。","妾家夫壻經離久，寸心誓與长相守。","願言行路莫多情，道妾貞心在人口。","日暮蠶飢相命归，携籠端飾来庭闈。","勞心苦力終無恨，所冀君恩即可依。","闻说行人已归止，乃是向来贈金子。","相看顏色不复言，相顧懷慙有何已。","從来自隐無疑背，直爲君情也相會。","如何咫尺仍有情，況复迢迢千里外。","誓將顧恩不顧身，念君此日赴河津。","莫道向来不得意，故欲留規誡後人。"]', '诗', 'shi', '', NULL, '秋胡行 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e31820a-bcc7-4bb7-b173-ab69e432e45c', '古大梁行', '古大梁行', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["古城莽蒼饒荆榛，驅馬荒城愁殺人。","魏王宮觀盡禾黍，信陵賓客隨灰塵。","憶昨雄都舊朝市，軒車照耀歌鐘起。","軍容帶甲三十萬，國步連營一千里。","全盛須臾那可論，高臺曲池無復存。","遺墟但見狐狸迹，古地空餘草木根。","暮天搖落傷懷抱，倚劒悲歌對秋草。","俠客猶傳朱亥名，行人尚識夷門道。","白璧黃金萬戶侯，寶刀駿馬填山丘。","年代淒涼不可問，往來唯有水東流。"]', '["古城莽蒼饒荆榛，驱马荒城愁殺人。","魏王宮观尽禾黍，信陵賓客隨灰塵。","憶昨雄都旧朝市，軒车照耀歌鐘起。","軍容带甲三十万，国步連營一千里。","全盛須臾那可論，高台曲池無复存。","遺墟但见狐狸迹，古地空餘草木根。","暮天搖落傷懷抱，倚劒悲歌对秋草。","俠客猶傳朱亥名，行人尚識夷门道。","白璧黄金万戶侯，寶刀駿马填山丘。","年代淒涼不可问，往来唯有水东流。"]', '诗', 'shi', '', NULL, '古大梁行 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0639b4d-1c8e-40a7-a3d8-1275bec19b03', '邯鄲少年行', '邯鄲少年行', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["邯鄲城南游俠子，自矜生長邯鄲裏。","千塲縱博家仍富，幾度報讐身不死。","宅中歌笑日紛紛，門外車馬常如雲。","未知肝膽向誰是，令人却憶平原君。","君不見今人交態薄，黃金用盡還疎索。","以茲感歎辭舊遊，更於時事無所求。","且與少年飲美酒，往來射獵西山頭。"]', '["邯鄲城南游俠子，自矜生长邯鄲裏。","千塲縱博家仍富，幾度報讐身不死。","宅中歌笑日紛紛，门外车马常如云。","未知肝膽向誰是，令人却憶平原君。","君不见今人交態薄，黄金用尽還疎索。","以茲感歎辞旧游，更於时事無所求。","且與少年饮美酒，往来射獵西山头。"]', '诗', 'shi', '', NULL, '邯鄲少年行 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e34f74b5-69ff-4136-927a-80d42eaeef6d', '燕歌行', '燕歌行', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["漢家煙塵在東北，漢將辭家破殘賊。","男兒本自重橫行，天子非常賜顏色。","摐金伐鼓下榆關，旌斾逶迤碣石間。","校尉羽書飛瀚海，單于獵火照狼山。","山川蕭條極邊土，胡騎憑陵雜風雨。","戰士軍前半死生，美人帳下猶歌舞。","大漠窮秋塞草腓，孤城落日鬬兵稀。","身當恩遇恆輕敵，力盡關山未解圍。","鐵衣遠戍辛勤久，玉筯應啼別離後。","少婦城南欲斷腸，征人薊北空回首。","邊庭飄颻那可度，絕域蒼茫更何有。","殺氣三時作陣雲，寒聲一夜傳刁斗。","相看白刃血紛紛，死節從來豈顧勳。","君不見沙場征戰苦，至今猶憶李將軍。"]', '["漢家煙塵在东北，漢將辞家破殘賊。","男兒本自重橫行，天子非常賜顏色。","摐金伐鼓下榆关，旌斾逶迤碣石间。","校尉羽书飞瀚海，單于獵火照狼山。","山川蕭條極邊土，胡騎憑陵杂风雨。","戰士軍前半死生，美人帳下猶歌舞。","大漠窮秋塞草腓，孤城落日鬬兵稀。","身當恩遇恆轻敵，力尽关山未解圍。","鐵衣远戍辛勤久，玉筯應啼別離後。","少婦城南欲斷腸，征人薊北空回首。","邊庭飄颻那可度，絕域蒼茫更何有。","殺氣三时作陣云，寒声一夜傳刁斗。","相看白刃血紛紛，死節從来豈顧勳。","君不见沙場征戰苦，至今猶憶李將軍。"]', '诗', 'shi', '', NULL, '燕歌行 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32ade105-6639-4a2d-8ba5-afb25200c6b3', '古歌行', '古歌行', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["君不見漢家三葉從代至，高皇舊臣多富貴。","天子垂衣方晏如，廟堂拱手無餘議。","蒼生偃臥休征戰，露臺百金以爲費。","田舍老翁不出門，洛陽少年莫論事。"]', '["君不见漢家三葉從代至，高皇旧臣多富貴。","天子垂衣方晏如，廟堂拱手無餘議。","蒼生偃臥休征戰，露台百金以爲費。","田舍老翁不出门，洛陽少年莫論事。"]', '诗', 'shi', '', NULL, '古歌行 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7318ace-183f-44e8-9704-3fceabe908be', '人日寄杜二拾遺', '人日寄杜二拾遺', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["人日題詩寄草堂，遙憐故人思故鄉。","柳條弄色不忍見，梅花滿枝空斷腸。","身在遠藩無所預，心懷百憂復千慮。","今年人日空相憶，明年人日知何處。","一臥東山三十春，豈知書劒老風塵。","龍鐘還忝二千石，愧爾東西南北人。"]', '["人日題诗寄草堂，遙怜故人思故乡。","柳條弄色不忍见，梅花满枝空斷腸。","身在远藩無所預，心懷百憂复千慮。","今年人日空相憶，明年人日知何处。","一臥东山三十春，豈知书劒老风塵。","龙鐘還忝二千石，愧爾东西南北人。"]', '诗', 'shi', '', NULL, '人日寄杜二拾遺 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b65b2f9-0c0d-4b94-92ad-af22334582cf', '九日酬顏少府', '九日酬顏少府', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["簷前白日應可惜，籬下黃花爲誰有。","行子迎霜未授衣，主人得錢始沽酒。","蘇秦顦顇人多厭，蔡澤棲遲世看醜。","縱使登高只斷腸，不如獨坐空搔首。"]', '["簷前白日應可惜，籬下黄花爲誰有。","行子迎霜未授衣，主人得錢始沽酒。","蘇秦顦顇人多厭，蔡澤棲遲世看醜。","縱使登高只斷腸，不如独坐空搔首。"]', '诗', 'shi', '', NULL, '九日酬顏少府 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b541e528-83cc-4c89-9990-94fda479abdb', '留別鄭三韋九兼洛下諸公', '留別鄭三韋九兼洛下諸公', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["憶昨相逢論久要，顧君哂我輕常調。","羈旅雖同白社遊，詩書已作青雲料。","蹇質蹉跎竟不成，年過四十尚躬耕。","長歌達者桮中物，大笑前人身後名。","幸逢明盛多招隱，高山大澤徵求盡。","此時亦得辭漁樵，青袍裹身荷聖朝。","犂牛釣竿不復見，縣人邑吏來相邀。","遠路鳴蟬秋興發，華堂美酒離憂銷。","不知何日更攜手，應念茲晨去折腰。"]', '["憶昨相逢論久要，顧君哂我轻常調。","羈旅雖同白社游，诗书已作青云料。","蹇質蹉跎竟不成，年過四十尚躬耕。","长歌達者桮中物，大笑前人身後名。","幸逢明盛多招隐，高山大澤徵求尽。","此时亦得辞漁樵，青袍裹身荷聖朝。","犂牛釣竿不复见，縣人邑吏来相邀。","远路鳴蟬秋兴發，华堂美酒離憂銷。","不知何日更携手，應念茲晨去折腰。"]', '诗', 'shi', '', NULL, '留別鄭三韋九兼洛下諸公 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('420a25fa-1c7e-4684-9919-838c96d1c61a', '送楊山人歸嵩陽', '送楊山人归嵩陽', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["不到嵩陽動十年，舊時心事已徒然。","一二故人不復見，三十六峰猶眼前。","夷門二月柳條色，流鶯數聲淚沾臆。","鑿井耕田不我招，知君以此忘帝力。","山人好去嵩陽路，惟余眷眷長相憶。"]', '["不到嵩陽动十年，旧时心事已徒然。","一二故人不复见，三十六峰猶眼前。","夷门二月柳條色，流鶯數声泪沾臆。","鑿井耕田不我招，知君以此忘帝力。","山人好去嵩陽路，惟余眷眷长相憶。"]', '诗', 'shi', '', NULL, '送楊山人歸嵩陽 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86467334-de4e-4df6-a218-51630701b941', '送別', '送別', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["昨夜離心正鬱陶，三更白露西風高。","螢飛木落何淅瀝，此時夢見西歸客。","曙鐘寥亮三四聲，東鄰嘶馬使人驚。","攬衣出戶一相送，唯見歸雲縱復橫。"]', '["昨夜離心正鬱陶，三更白露西风高。","螢飞木落何淅瀝，此时梦见西归客。","曙鐘寥亮三四声，东鄰嘶马使人驚。","攬衣出戶一相送，唯见归云縱复橫。"]', '诗', 'shi', '', NULL, '送別 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5d52c7f-9cd4-4805-8b40-47771a17af7b', '贈別晉三處士', '贈別晉三处士', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["有人家住清河源，渡河問我游梁園。","手持道經注已畢，心知內篇口不言。","盧門十年見秋草，此心惆悵誰能道。","知己從來不易知，慕君爲人與君好。","別時九月桑葉疎，出門千里無行車。","愛君且欲君先達，今上求賢早上書。"]', '["有人家住清河源，渡河问我游梁园。","手持道經注已畢，心知內篇口不言。","盧门十年见秋草，此心惆悵誰能道。","知己從来不易知，慕君爲人與君好。","別时九月桑葉疎，出门千里無行车。","愛君且欲君先達，今上求賢早上书。"]', '诗', 'shi', '', NULL, '贈別晉三處士 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('344df1ed-e20f-4fb2-8f39-4f9634effe80', '送渾將軍出塞', '送渾將軍出塞', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["將軍族貴兵且強，漢家已是渾邪王。","子孫相承在朝野，至今部曲燕支下。","控弦盡用陰山兒，登陣常騎大宛馬。","銀鞍玉勒繡蝥弧，每逐嫖姚破骨都。","李廣從來先將士，衛青未肯學孫吳。","傳有沙場千萬騎，昨日邊庭羽書至。","城頭畫角三四聲，匣裏寶刀晝夜鳴。","意氣能甘萬里去，辛勤判作一年行。","黃雲白草無前後，朝建旌旄夕刁斗。","塞下應多俠少年，關西不見春楊柳。","從軍借問所從誰，擊劒酣歌當此時。","遠別無輕繞朝策，平戎早寄仲宣詩。"]', '["將軍族貴兵且強，漢家已是渾邪王。","子孫相承在朝野，至今部曲燕支下。","控弦尽用陰山兒，登陣常騎大宛马。","銀鞍玉勒繡蝥弧，每逐嫖姚破骨都。","李廣從来先將士，衛青未肯学孫吳。","傳有沙場千万騎，昨日邊庭羽书至。","城头畫角三四声，匣裏寶刀晝夜鳴。","意氣能甘万里去，辛勤判作一年行。","黄云白草無前後，朝建旌旄夕刁斗。","塞下應多俠少年，关西不见春楊柳。","從軍借问所從誰，擊劒酣歌當此时。","远別無轻繞朝策，平戎早寄仲宣诗。"]', '诗', 'shi', '', NULL, '送渾將軍出塞 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a09444a-363a-4ca9-9537-2c6a91683de4', '送蔡山人', '送蔡山人', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["東山布衣明古今，自言獨未逢知音。","識者閱見一生事，到處豁然千里心。","看書學劒長辛苦，近日方思謁明主。","斗酒相留醉復醒，悲歌數年淚如雨。","丈夫遭遇不可知，買臣主父皆如斯。","我今蹭蹬無所似，看爾崩騰何若爲。"]', '["东山布衣明古今，自言独未逢知音。","識者閱见一生事，到处豁然千里心。","看书学劒长辛苦，近日方思謁明主。","斗酒相留醉复醒，悲歌數年泪如雨。","丈夫遭遇不可知，買臣主父皆如斯。","我今蹭蹬無所似，看爾崩腾何若爲。"]', '诗', 'shi', '', NULL, '送蔡山人 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('371ccd3f-c864-4c88-b53e-4feab2f090c0', '封丘作', '封丘作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["我本漁樵孟諸野，一生自是悠悠者。","乍可狂歌草澤中，寧堪作吏風塵下。","秪言小邑無所爲，公門百事皆有期。","拜迎官長心欲碎，鞭撻黎庶令人悲。","歸來向家問妻子，舉家盡笑今如此。","生事應須南畝田，世情付與東流水。","夢想舊山安在哉，爲銜君命且遲廻。","乃知梅福徒爲爾，轉憶陶潛歸去來。"]', '["我本漁樵孟諸野，一生自是悠悠者。","乍可狂歌草澤中，寧堪作吏风塵下。","秪言小邑無所爲，公门百事皆有期。","拜迎官长心欲碎，鞭撻黎庶令人悲。","归来向家问妻子，舉家尽笑今如此。","生事應須南畝田，世情付與东流水。","梦想旧山安在哉，爲銜君命且遲廻。","乃知梅福徒爲爾，轉憶陶潛归去来。"]', '诗', 'shi', '', NULL, '封丘作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('febfce55-5c76-4c97-b44d-e4b97fe13b29', '題李別駕壁', '題李別駕壁', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["去鄉不遠逢知己，握手相歡得如此。","禮樂遙傳魯伯禽，賓客爭過魏公子。","酒筵暮散明月上，櫪馬長鳴春風起。","一生稱意能幾人，今日從君問終始。"]', '["去乡不远逢知己，握手相歡得如此。","禮乐遙傳魯伯禽，賓客爭過魏公子。","酒筵暮散明月上，櫪马长鳴春风起。","一生稱意能幾人，今日從君问終始。"]', '诗', 'shi', '', NULL, '題李別駕壁 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('784b5bc3-05d5-425d-8935-49c42bf2cccc', '寄宿田家', '寄宿田家', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["田家老翁住東陂，說道平生隱在茲。","鬢白未曾記日月，山青每到識春時。","門前種柳深成巷，野谷流泉添入池。","牛壯日耕十畝地，人閑常掃一茅茨。","客來滿酌清尊酒，感興平吟才子詩。","巖際窟中藏鼴鼠，潭邊竹裏隱鸕鶿。","村墟日落行人少，醉後無心怯路岐。","今夜只應還寄宿，明朝拂曙與君辭。"]', '["田家老翁住东陂，说道平生隐在茲。","鬢白未曾記日月，山青每到識春时。","门前種柳深成巷，野谷流泉添入池。","牛壯日耕十畝地，人闲常掃一茅茨。","客来满酌清尊酒，感兴平吟才子诗。","巖際窟中藏鼴鼠，潭邊竹裏隐鸕鶿。","村墟日落行人少，醉後無心怯路岐。","今夜只應還寄宿，明朝拂曙與君辞。"]', '诗', 'shi', '', NULL, '寄宿田家 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a03c0482-ee78-47d7-9762-18a156b751af', '別韋參軍', '別韋參軍', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["二十解書劒，西遊長安城。","舉頭望君門，屈指取公卿。","國風沖融邁三五，朝廷歡樂彌寰宇。","白璧皆言賜近臣，布衣不得干明主。","歸來洛陽無負郭，東過梁宋非吾土。","兔苑爲農歲不登，雁池垂釣心長苦。","世人遇我同衆人，唯君於我最相親。","且喜百年有交態，未嘗一日辭家貧。","彈棊擊筑白日晚，縱酒高歌楊柳春。","歡娛未盡分散去，使我惆悵驚心神。","丈夫不作兒女別，臨岐涕淚沾衣巾。"]', '["二十解书劒，西游长安城。","舉头望君门，屈指取公卿。","国风沖融邁三五，朝廷歡乐彌寰宇。","白璧皆言賜近臣，布衣不得干明主。","归来洛陽無負郭，东過梁宋非吾土。","兔苑爲農歲不登，雁池垂釣心长苦。","世人遇我同衆人，唯君於我最相親。","且喜百年有交態，未嘗一日辞家貧。","彈棊擊筑白日晚，縱酒高歌楊柳春。","歡娛未尽分散去，使我惆悵驚心神。","丈夫不作兒女別，臨岐涕泪沾衣巾。"]', '诗', 'shi', '', NULL, '別韋參軍 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e169041-882d-475c-bb60-8df9ecc9ac19', '送田少府貶蒼梧', '送田少府貶蒼梧', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["沈吟對遷客，惆悵西南天。","昔爲一官未得意，今向萬里令人憐。","念茲斗酒成暌間，停舟歎君日將晏。","遠樹應憐北地春，行人却羨南歸雁。","丈夫窮達未可知，看君不合長數奇。","江山到處堪乘興，楊柳青青那足悲。"]', '["沈吟对遷客，惆悵西南天。","昔爲一官未得意，今向万里令人怜。","念茲斗酒成暌间，停舟歎君日將晏。","远樹應怜北地春，行人却羨南归雁。","丈夫窮達未可知，看君不合长數奇。","江山到处堪乘兴，楊柳青青那足悲。"]', '诗', 'shi', '', NULL, '送田少府貶蒼梧 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('203b10c7-2886-4ae6-870f-6eb1ec9ff558', '平臺夜遇李景參有別', '平台夜遇李景參有別', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["離心忽悵然，策馬對秋天。","孟諸薄暮涼風起，歸客相逢渡睢水。","昨時攜手已十年，今日分途各千里。","歲物蕭條滿路岐，此行浩蕩令人悲。","家貧羨爾有微祿，欲往從之何所之。"]', '["離心忽悵然，策马对秋天。","孟諸薄暮涼风起，归客相逢渡睢水。","昨时携手已十年，今日分途各千里。","歲物蕭條满路岐，此行浩蕩令人悲。","家貧羨爾有微祿，欲往從之何所之。"]', '诗', 'shi', '', NULL, '平臺夜遇李景參有別 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb790ed4-04db-48f5-9b55-6f7d2b0a2042', '送郭處士往萊蕪兼寄茍山人', '送郭处士往萊蕪兼寄茍山人', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["君爲東蒙客，往來東蒙畔。","雲臥臨嶧陽，山行窮日觀。","少年詞賦皆可聽，秀眉白面風清泠。","身上未曾染名利，口中猶未知膻腥。","今日還山意無極，豈辭世路多相識。","歸見萊蕪九十翁，爲論別後長相憶。"]', '["君爲东蒙客，往来东蒙畔。","云臥臨嶧陽，山行窮日观。","少年词賦皆可听，秀眉白面风清泠。","身上未曾染名利，口中猶未知膻腥。","今日還山意無極，豈辞世路多相識。","归见萊蕪九十翁，爲論別後长相憶。"]', '诗', 'shi', '', NULL, '送郭處士往萊蕪兼寄茍山人 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03ca699d-7447-498d-8251-cf9f85deae11', '賦得還山吟送沈四山人', '賦得還山吟送沈四山人', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["還山吟，天高日暮寒山深。","送君還山識君心，人生老大須恣意。","看君解作一生事，山間偃仰無不至。","石泉淙淙若風雨，桂花松子常滿地。","賣藥囊中應有錢，還山服藥又長年。","白雲勸盡桮中物，明月相隨何處眠。","眠時憶問醒時事，夢魂可以相周旋。"]', '["還山吟，天高日暮寒山深。","送君還山識君心，人生老大須恣意。","看君解作一生事，山间偃仰無不至。","石泉淙淙若风雨，桂花松子常满地。","賣藥囊中應有錢，還山服藥又长年。","白云勸尽桮中物，明月相隨何处眠。","眠时憶问醒时事，梦魂可以相周旋。"]', '诗', 'shi', '', NULL, '賦得還山吟送沈四山人 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2656cc2f-8178-477d-88b4-13bb0d73a634', '崔司錄宅燕大理李卿', '崔司錄宅燕大理李卿', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["多雨殊未已，秋雲更沈沈。","洛陽故人初解印，山東小吏來相尋。","上卿才大名不朽，早朝至尊暮求友。","豁達常推海內賢，殷勤但酌尊中酒。","飲醉欲言歸剡溪，門前駟馬光照衣。","路傍觀者徒唧唧，我公不以爲是非。"]', '["多雨殊未已，秋云更沈沈。","洛陽故人初解印，山东小吏来相尋。","上卿才大名不朽，早朝至尊暮求友。","豁達常推海內賢，殷勤但酌尊中酒。","饮醉欲言归剡溪，门前駟马光照衣。","路傍观者徒唧唧，我公不以爲是非。"]', '诗', 'shi', '', NULL, '崔司錄宅燕大理李卿 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b563103-d593-41f9-96a4-b65155ccbde4', '同鮮于洛陽於畢員外宅觀畫馬歌', '同鲜于洛陽於畢員外宅观畫马歌', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["知君愛鳴琴，仍好千里馬。","永日恆思單父中，有時心到宛城下。","遇客丹青天下才，白生胡雛控龍媒。","主人娛賓畫障開，只言騏驥西極來。","半壁䟃𧽼勢不住，滿堂風飄颯然度。","家僮愕視欲先鞭，櫪馬驚嘶還屢顧。","始知物妙皆可憐，燕昭市駿豈徒然。","縱令剪拂無所用，猶勝駑駘在眼前。"]', '["知君愛鳴琴，仍好千里马。","永日恆思單父中，有时心到宛城下。","遇客丹青天下才，白生胡雛控龙媒。","主人娛賓畫障开，只言騏驥西極来。","半壁䟃𧽼勢不住，满堂风飄颯然度。","家僮愕視欲先鞭，櫪马驚嘶還屢顧。","始知物妙皆可怜，燕昭市駿豈徒然。","縱令剪拂無所用，猶勝駑駘在眼前。"]', '诗', 'shi', '', NULL, '同鮮于洛陽於畢員外宅觀畫馬歌 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('399d7586-1d9c-491f-b854-2f7b61b27980', '同河南李少尹畢員外宅夜飲時洛陽告捷遂作春酒歌', '同河南李少尹畢員外宅夜饮时洛陽告捷遂作春酒歌', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["故人美酒勝濁醪，故人清詞合風騷。","長歌滿酌惟吾曹，高談正可揮麈毛。","半醉忽然持蟹螯，洛陽告捷傾前後。","武侯腰間印如斗，郎官無事時飲酒。","桮中綠蟻吹轉來，甕上飛花拂還有。","前年持節將楚兵，去年留司在東京。","今年復拜二千石，盛夏五月西南行。","彭門劒門蜀山裏，昨逢軍人刦奪我。","到家但見妻與子，賴得飲君春酒數十桮，不然令我愁欲死。"]', '["故人美酒勝濁醪，故人清词合风騷。","长歌满酌惟吾曹，高談正可揮麈毛。","半醉忽然持蟹螯，洛陽告捷傾前後。","武侯腰间印如斗，郎官無事时饮酒。","桮中綠蟻吹轉来，甕上飞花拂還有。","前年持節將楚兵，去年留司在东京。","今年复拜二千石，盛夏五月西南行。","彭门劒门蜀山裏，昨逢軍人刦奪我。","到家但见妻與子，賴得饮君春酒數十桮，不然令我愁欲死。"]', '诗', 'shi', '', NULL, '同河南李少尹畢員外宅夜飲時洛陽告捷遂作春酒歌 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('101844bd-db52-4b7b-a097-c45162545c77', '同李九士曹觀壁畫雲作', '同李九士曹观壁畫云作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["始知帝鄉客，能畫蒼梧雲。","秋天萬里一片色，只疑飛盡猶氛氳。"]', '["始知帝乡客，能畫蒼梧云。","秋天万里一片色，只疑飞尽猶氛氳。"]', '诗', 'shi', '', NULL, '同李九士曹觀壁畫雲作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17c901f7-75d0-48ce-ac16-95724c21dad9', '見薛大臂鷹作', '见薛大臂鷹作', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["寒楚十二月，蒼鷹八九毛。","寄言燕雀莫相啅，自有雲霄萬里高。"]', '["寒楚十二月，蒼鷹八九毛。","寄言燕雀莫相啅，自有云霄万里高。"]', '诗', 'shi', '', NULL, '見薛大臂鷹作 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e94f7b4c-7e68-4d8b-81b3-053539a689d8', '畫馬篇', '畫马篇', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["君侯櫪上驄，貌在丹青中。","馬毛連錢蹄鐵色，圖畫光輝驕玉勒。","馬行不動勢若來，權奇蹴踏無塵埃。","感茲絕代稱妙手，遂令談者不容口。","麒麟獨步自可珍，駑駘萬匹知何有，終未如他櫪上驄。","載華轂，聘飛鴻，荷君剪拂與君用，一日千里如旋風。"]', '["君侯櫪上驄，貌在丹青中。","马毛連錢蹄鐵色，圖畫光輝驕玉勒。","马行不动勢若来，權奇蹴踏無塵埃。","感茲絕代稱妙手，遂令談者不容口。","麒麟独步自可珍，駑駘万匹知何有，終未如他櫪上驄。","載华轂，聘飞鴻，荷君剪拂與君用，一日千里如旋风。"]', '诗', 'shi', '', NULL, '畫馬篇 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7c8a7fe-7ad4-44fe-9b71-3c085eb5e999', '詠馬鞭', '詠马鞭', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["龍竹養根凡幾年，工人截之爲長鞭。","一節一目皆天然，珠重重，星連連。","繞指柔，純金堅，繩不直，規不圓。","把向空中捎一聲，良馬有心日馳千。"]', '["龙竹養根凡幾年，工人截之爲长鞭。","一節一目皆天然，珠重重，星連連。","繞指柔，純金堅，繩不直，規不圓。","把向空中捎一声，良马有心日驰千。"]', '诗', 'shi', '', NULL, '詠馬鞭 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ba275a5-93d8-4d90-9367-7192e01dae10', '塞下曲', '塞下曲', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["君不見芳樹枝，春花落盡蜂不窺。","君不見梁上泥，秋風始高燕不棲。","蕩子從軍事征戰，蛾眉嬋娟守空閨。","獨宿自然堪下淚，況復時聞鳥夜啼。"]', '["君不见芳樹枝，春花落尽蜂不窺。","君不见梁上泥，秋风始高燕不棲。","蕩子從軍事征戰，蛾眉嬋娟守空閨。","独宿自然堪下泪，況复时闻鸟夜啼。"]', '诗', 'shi', '', NULL, '塞下曲 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0be9008f-d175-47f6-aa53-87fce8d020fa', '漁父歌', '漁父歌', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["曲岸深潭一山叟，駐眼看鈎不移手。","世人欲得知姓名，良久問他不開口。","笋皮笠子荷葉衣，心無所營守釣磯。","料得孤舟無定止，日暮持竿何處歸。"]', '["曲岸深潭一山叟，駐眼看鈎不移手。","世人欲得知姓名，良久问他不开口。","笋皮笠子荷葉衣，心無所營守釣磯。","料得孤舟無定止，日暮持竿何处归。"]', '诗', 'shi', '', NULL, '漁父歌 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e16715ca-dc77-4e04-b442-8e0c41c74ec5', '部落曲', '部落曲', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["蕃軍傍塞遊，代馬噴風秋。","老將垂金甲，閼支着錦裘。","琱戈蒙豹尾，紅斾插狼頭。","日暮天山下，鳴笳漢使愁。"]', '["蕃軍傍塞游，代马噴风秋。","老將垂金甲，閼支着錦裘。","琱戈蒙豹尾，紅斾插狼头。","日暮天山下，鳴笳漢使愁。"]', '诗', 'shi', '', NULL, '部落曲 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31bcaea7-a3c1-47a0-a1d3-eb91a703d1fb', '贈杜二拾遺', '贈杜二拾遺', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["傳道招[提]客，詩書自討論。","佛香時入院，僧飯屢過門。","聽法還應難，尋經剩欲翻。","草玄今已畢，此外復何言。"]', '["傳道招[提]客，诗书自討論。","佛香时入院，僧飯屢過门。","听法還應难，尋經剩欲翻。","草玄今已畢，此外复何言。"]', '诗', 'shi', '', NULL, '贈杜二拾遺 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8ad2060-b409-46e5-b499-a4cd17a9803b', '醉後贈張九旭', '醉後贈張九旭', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["世上謾相識，此翁殊不然。","興來書自聖，醉後語尤顛。","白髮老閑事，青雲在目前。","牀頭一壺酒，能更幾回眠。"]', '["世上謾相識，此翁殊不然。","兴来书自聖，醉後語尤顛。","白髮老闲事，青云在目前。","牀头一壺酒，能更幾回眠。"]', '诗', 'shi', '', NULL, '醉後贈張九旭 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70c1e034-056a-445d-bff6-9afa97a32ef0', '途中寄徐錄事', '途中寄徐錄事', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["落日風雨至，秋天鴻雁初。","離憂不堪比，旅館復何如。","君又幾時去，我知音信疎。","空多篋中贈，長見右軍書。"]', '["落日风雨至，秋天鴻雁初。","離憂不堪比，旅館复何如。","君又幾时去，我知音信疎。","空多篋中贈，长见右軍书。"]', '诗', 'shi', '', NULL, '途中寄徐錄事 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7166837-c70d-4cfd-bf45-baf6930473bf', '酬衛八雪中見寄', '酬衛八雪中见寄', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["季冬憶淇上，落日歸山樊。","舊宅帶流水，平田臨古村。","雪中望來信，醉裏開衡門。","果得希代寶，緘之那可論。"]', '["季冬憶淇上，落日归山樊。","旧宅带流水，平田臨古村。","雪中望来信，醉裏开衡门。","果得希代寶，緘之那可論。"]', '诗', 'shi', '', NULL, '酬衛八雪中見寄 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1b6a20a-bcbf-4886-bc42-3843d99b2368', '送白少府送兵之隴右', '送白少府送兵之隴右', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["踐更登隴首，遠別指臨洮。","爲問關山事，何如州縣勞。","軍容隨赤羽，樹色引青袍。","誰斷單于臂，今年太白高。"]', '["踐更登隴首，远別指臨洮。","爲问关山事，何如州縣勞。","軍容隨赤羽，樹色引青袍。","誰斷單于臂，今年太白高。"]', '诗', 'shi', '', NULL, '送白少府送兵之隴右 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a0b788a-0d41-477a-8361-29f7c9157c41', '河西送李十七', '河西送李十七', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["邊城多遠別，此去莫徒然。","問禮知才子，登科及少年。","出門看落日，驅馬向秋天。","高價人爭重，行當早着鞭。"]', '["邊城多远別，此去莫徒然。","问禮知才子，登科及少年。","出门看落日，驱马向秋天。","高價人爭重，行當早着鞭。"]', '诗', 'shi', '', NULL, '河西送李十七 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5627d9fa-e648-4151-9a60-08cff928d305', '送張瑤貶五谿尉', '送張瑤貶五谿尉', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["他日維楨幹，明時懸鏌鋣。","江山遙去國，妻子獨還家。","離別無嫌遠，沈浮勿強嗟。","南登有詞賦，知爾弔長沙。"]', '["他日維楨幹，明时懸鏌鋣。","江山遙去国，妻子独還家。","離別無嫌远，沈浮勿強嗟。","南登有词賦，知爾弔长沙。"]', '诗', 'shi', '', NULL, '送張瑤貶五谿尉 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49e8d65c-a254-42eb-9bb6-152ba3d3986e', '別韋五', '別韋五', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["徒然酌桮酒，不覺散人愁。","相識仍遠別，欲歸翻旅遊。","夏雲滿郊甸，明月照河洲。","莫恨征途遠，東看漳水流。"]', '["徒然酌桮酒，不覺散人愁。","相識仍远別，欲归翻旅游。","夏云满郊甸，明月照河洲。","莫恨征途远，东看漳水流。"]', '诗', 'shi', '', NULL, '別韋五 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0547256-859d-4caf-aa4b-41684052f2c6', '別劉大校書', '別劉大校书', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["昔日京華去，知君才望新。","應猶作賦好，莫歎在官貧。","且復傷遠別，不然愁此身。","清風幾萬里，江上一歸人。"]', '["昔日京华去，知君才望新。","應猶作賦好，莫歎在官貧。","且复傷远別，不然愁此身。","清风幾万里，江上一归人。"]', '诗', 'shi', '', NULL, '別劉大校書 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e50286c-3f34-407e-95d7-3015902c044f', '宋中別司功叔各賦一物得商丘', '宋中別司功叔各賦一物得商丘', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["商丘試一望，隱隱帶秋天。","地與辰星在，城將大路遷。","干戈悲昔事，墟落對窮年。","即此傷離緒，悽悽賦酒筵。"]', '["商丘試一望，隐隐带秋天。","地與辰星在，城將大路遷。","干戈悲昔事，墟落对窮年。","即此傷離緒，悽悽賦酒筵。"]', '诗', 'shi', '', NULL, '宋中別司功叔各賦一物得商丘 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a98af493-3392-4ac3-b648-cb48118bff10', '送蔡十二之海上', '送蔡十二之海上', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["黯然何所爲，相對但悲酸。","季弟念離別，賢兄救急難。","河流冰處盡，海路雪中寒。","尚有南飛雁，知君不忍看。"]', '["黯然何所爲，相对但悲酸。","季弟念離別，賢兄救急难。","河流冰处尽，海路雪中寒。","尚有南飞雁，知君不忍看。"]', '诗', 'shi', '', NULL, '送蔡十二之海上 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b34cd445-5b1c-4877-84bd-a5cab8f1ed64', '別韋兵曹', '別韋兵曹', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["離別長千里，相逢數十年。","此心應不變，他事已徒然。","惆悵春光裏，蹉跎柳色前。","逢時當自取，看爾欲先鞭。"]', '["離別长千里，相逢數十年。","此心應不变，他事已徒然。","惆悵春光裏，蹉跎柳色前。","逢时當自取，看爾欲先鞭。"]', '诗', 'shi', '', NULL, '別韋兵曹 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c065521-b184-4042-a21f-6d433fa32f36', '獨孤判官部送兵', '独孤判官部送兵', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["餞君嗟遠別，爲客念周旋。","征路今如此，前軍猶眇然。","出關逢漢壁，登隴望胡天。","亦是封侯地，期君早着鞭。"]', '["餞君嗟远別，爲客念周旋。","征路今如此，前軍猶眇然。","出关逢漢壁，登隴望胡天。","亦是封侯地，期君早着鞭。"]', '诗', 'shi', '', NULL, '獨孤判官部送兵 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88fe33c7-2174-4ecd-bfda-c6c637d0182e', '別從甥萬盈', '別從甥万盈', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["諸生曰萬盈，四十乃知名。","宅相予偏重，家丘人莫輕。","美才應自料，苦節豈無成。","莫以山田薄，今春又不耕。"]', '["諸生曰万盈，四十乃知名。","宅相予偏重，家丘人莫轻。","美才應自料，苦節豈無成。","莫以山田薄，今春又不耕。"]', '诗', 'shi', '', NULL, '別從甥萬盈 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6b86ec1-0218-4426-96a9-ee66e88cd449', '別崔少府', '別崔少府', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["知君少得意，汶上掩柴扉。","寒食仍留火，春風未授衣。","皆言黃綬屈，早向青雲飛。","借問他鄉事，今年歸不歸。"]', '["知君少得意，汶上掩柴扉。","寒食仍留火，春风未授衣。","皆言黄綬屈，早向青云飞。","借问他乡事，今年归不归。"]', '诗', 'shi', '', NULL, '別崔少府 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7ce2e16-a019-4b91-aa72-ed498d1aebe3', '別馮判官', '別馮判官', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["碣石遼西地，漁陽薊北天。","關山唯一道，雨雪盡三邊。","才子方爲客，將軍正渴賢。","遙知幕府下，書記日翩翩。"]', '["碣石遼西地，漁陽薊北天。","关山唯一道，雨雪尽三邊。","才子方爲客，將軍正渴賢。","遙知幕府下，书記日翩翩。"]', '诗', 'shi', '', NULL, '別馮判官 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca7c9d91-140d-440e-90c8-67421ab0d987', '淇上送韋司倉往滑臺', '淇上送韋司倉往滑台', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["飲酒莫辭醉，醉多適不愁。","孰知非遠別，終念對窮秋。","滑臺門外見，淇水眼前流。","君去應回首，風波滿渡頭。"]', '["饮酒莫辞醉，醉多適不愁。","孰知非远別，終念对窮秋。","滑台门外见，淇水眼前流。","君去應回首，风波满渡头。"]', '诗', 'shi', '', NULL, '淇上送韋司倉往滑臺 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d03fbb08-dc93-465e-bca1-471cef5e55ee', '送崔功曹赴越', '送崔功曹赴越', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["傳有東南別，題詩報客居。","江山知不厭，州縣復何如。","莫恨吳歈曲，嘗看越絕書。","今朝欲乘興，隨爾食鱸魚。"]', '["傳有东南別，題诗報客居。","江山知不厭，州縣复何如。","莫恨吳歈曲，嘗看越絕书。","今朝欲乘兴，隨爾食鱸鱼。"]', '诗', 'shi', '', NULL, '送崔功曹赴越 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('976de84b-f21a-4d7a-8a63-9ee51c307921', '送蹇秀才赴臨洮', '送蹇秀才赴臨洮', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["悵望日千里，如何今二毛。","猶思陽谷去，莫厭隴山高。","倚馬見雄筆，隨身唯寶刀。","料君終自致，勳業在臨洮。"]', '["悵望日千里，如何今二毛。","猶思陽谷去，莫厭隴山高。","倚马见雄笔，隨身唯寶刀。","料君終自致，勳業在臨洮。"]', '诗', 'shi', '', NULL, '送蹇秀才赴臨洮 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('517f960a-ac39-402d-982a-118f9d845fbc', '廣陵別鄭處士', '廣陵別鄭处士', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["落日知分手，春風莫斷腸。","興來無不愜，才在亦何傷。","溪水堪垂釣，江田耐插秧。","人生只爲此，亦足傲羲皇。"]', '["落日知分手，春风莫斷腸。","兴来無不愜，才在亦何傷。","溪水堪垂釣，江田耐插秧。","人生只爲此，亦足傲羲皇。"]', '诗', 'shi', '', NULL, '廣陵別鄭處士 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e65c105-017c-4b5c-b899-6ace25d18507', '別孫訢', '別孫訢', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["離人去復留，白馬黑貂裘。","屈指論前事，停鞭惜舊遊。","帝鄉那可忘，旅館日堪愁。","誰念無知己，年年睢水流。"]', '["離人去复留，白马黑貂裘。","屈指論前事，停鞭惜旧游。","帝乡那可忘，旅館日堪愁。","誰念無知己，年年睢水流。"]', '诗', 'shi', '', NULL, '別孫訢 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b42b8d7b-3d04-46ed-ba87-11478e25d391', '送劉評事充朔方判官賦得征馬嘶', '送劉評事充朔方判官賦得征马嘶', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["征馬向邊州，蕭蕭嘶不休。","思深應帶別，聲斷爲兼秋。","岐路風將遠，關山月共愁。","贈君從此去，何日大刀頭。"]', '["征马向邊州，蕭蕭嘶不休。","思深應带別，声斷爲兼秋。","岐路风將远，关山月共愁。","贈君從此去，何日大刀头。"]', '诗', 'shi', '', NULL, '送劉評事充朔方判官賦得征馬嘶 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16b8caaa-e64d-4ad8-839f-8627c0a40f62', '送魏八', '送魏八', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["更沽淇上酒，還泛驛前舟。","爲惜故人去，復憐嘶馬愁。","雲山行處合，風雨興中秋。","此路無知己，明珠莫暗投。"]', '["更沽淇上酒，還泛驛前舟。","爲惜故人去，复怜嘶马愁。","云山行处合，风雨兴中秋。","此路無知己，明珠莫暗投。"]', '诗', 'shi', '', NULL, '送魏八 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('054f613f-675f-4387-aa4d-428b8a6c601e', '贈別褚山人', '贈別褚山人', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["攜手贈將行，山人道姓名。","光陰薊子訓，才術褚先生。","牆上梨花白，尊中桂酒清。","洛陽無二價，猶是慕風聲。"]', '["携手贈將行，山人道姓名。","光陰薊子訓，才術褚先生。","牆上梨花白，尊中桂酒清。","洛陽無二價，猶是慕风声。"]', '诗', 'shi', '', NULL, '贈別褚山人 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('384a5a42-d76b-4e09-92f3-3aaec0e9b838', '別王八', '別王八', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["征馬嘶長路，離人挹佩刀。","客來東道遠，歸去北風高。","時候何蕭索，鄉心正鬱陶。","傳君遇知己，行日有綈袍。"]', '["征马嘶长路，離人挹佩刀。","客来东道远，归去北风高。","时候何蕭索，乡心正鬱陶。","傳君遇知己，行日有綈袍。"]', '诗', 'shi', '', NULL, '別王八 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38eb0617-79f7-467d-bc5f-892f6921dc4b', '送董判官', '送董判官', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["逢君說行邁，倚劒別交親。","幕府爲才子，將軍作主人。","近關多雨雪，出塞有風塵。","長策須當用，男兒莫顧身。"]', '["逢君说行邁，倚劒別交親。","幕府爲才子，將軍作主人。","近关多雨雪，出塞有风塵。","长策須當用，男兒莫顧身。"]', '诗', 'shi', '', NULL, '送董判官 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3898eb6d-95df-4b2e-b6d2-348e3f013d5a', '送鄭侍御謫閩中', '送鄭侍御謫閩中', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["謫去君無恨，閩中我舊過。","大都秋雁少，只是夜猿多。","東路雲山合，南天瘴癘和。","自當逢雨露，行矣慎風波。"]', '["謫去君無恨，閩中我旧過。","大都秋雁少，只是夜猿多。","东路云山合，南天瘴癘和。","自當逢雨露，行矣慎风波。"]', '诗', 'shi', '', NULL, '送鄭侍御謫閩中 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c46a848d-86bf-4e2e-9ffc-442759ddfa7a', '送李侍御赴安西', '送李侍御赴安西', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["行子對飛蓬，金鞭指鐵驄。","功名萬里外，心事一桮中。","虜障燕支北，秦城太白東。","離魂莫惆悵，看取寶刀雄。"]', '["行子对飞蓬，金鞭指鐵驄。","功名万里外，心事一桮中。","虜障燕支北，秦城太白东。","離魂莫惆悵，看取寶刀雄。"]', '诗', 'shi', '', NULL, '送李侍御赴安西 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57bb1245-317d-4fd3-955f-74370298f685', '送裴別將之安西', '送裴別將之安西', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["絕域眇難躋，悠然信馬蹄。","風塵經跋涉，搖落怨暌攜。","地出流沙外，天長甲子西。","少年無不可，行矣莫悽悽。"]', '["絕域眇难躋，悠然信马蹄。","风塵經跋涉，搖落怨暌携。","地出流沙外，天长甲子西。","少年無不可，行矣莫悽悽。"]', '诗', 'shi', '', NULL, '送裴別將之安西 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3c44130-3588-40ef-88a7-4e0e504743ca', '宴郭校書因之有別', '宴郭校书因之有別', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["綵服趨庭訓，分交載酒過。","芸香名早著，蓬轉事仍多。","苦戰知機息，窮愁奈別何。","雲霄莫相待，年鬢已蹉跎。"]', '["綵服趨庭訓，分交載酒過。","芸香名早著，蓬轉事仍多。","苦戰知機息，窮愁奈別何。","云霄莫相待，年鬢已蹉跎。"]', '诗', 'shi', '', NULL, '宴郭校書因之有別 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67e52566-31d7-40e8-8ee5-8cb5bbb057f3', '同李太守北池泛舟宴高平鄭太守', '同李太守北池泛舟宴高平鄭太守', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["每揖龔黃事，還陪李郭舟。","雲從四岳起，水向百城流。","幽意隨登陟，嘉言即獻酬。","乃知縫掖貴，今日對諸侯。"]', '["每揖龔黄事，還陪李郭舟。","云從四岳起，水向百城流。","幽意隨登陟，嘉言即獻酬。","乃知縫掖貴，今日对諸侯。"]', '诗', 'shi', '', NULL, '同李太守北池泛舟宴高平鄭太守 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16115ead-7f11-404c-b6c5-1ea87057291a', '同崔員外綦毋拾遺九日宴京兆府李士曹', '同崔員外綦毋拾遺九日宴京兆府李士曹', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["今日好相見，羣賢仍廢曹。","晚晴催翰墨，秋興引風騷。","絳葉擁虛砌，黃花隨濁醪。","閉門無不可，何事更登高。"]', '["今日好相见，羣賢仍廢曹。","晚晴催翰墨，秋兴引风騷。","絳葉擁虛砌，黄花隨濁醪。","閉门無不可，何事更登高。"]', '诗', 'shi', '', NULL, '同崔員外綦毋拾遺九日宴京兆府李士曹 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c607713-fd86-49a7-9e98-6d5858d24e51', '同羣公十月朝宴李太守宅', '同羣公十月朝宴李太守宅', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["良牧徵高賞，褰帷問考槃。","歲時當正月，甲子入初寒。","已聽甘棠頌，欣陪旨酒歡。","仍憐門下客，不作布衣看。"]', '["良牧徵高賞，褰帷问考槃。","歲时當正月，甲子入初寒。","已听甘棠頌，欣陪旨酒歡。","仍怜门下客，不作布衣看。"]', '诗', 'shi', '', NULL, '同羣公十月朝宴李太守宅 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('655ae29b-c115-4b27-a0b8-caa7e01d1808', '武威同諸公過楊七山人得藤字', '武威同諸公過楊七山人得藤字', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["幕府日多暇，田家歲復登。","相知恨不早，乘興乃無恆。","窮巷在喬木，深齋垂古藤。","邊城唯有醉，此外更何能。"]', '["幕府日多暇，田家歲复登。","相知恨不早，乘兴乃無恆。","窮巷在喬木，深斋垂古藤。","邊城唯有醉，此外更何能。"]', '诗', 'shi', '', NULL, '武威同諸公過楊七山人得藤字 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31b9d9c3-3b67-428f-8b53-3019cb4a0b67', '同羣公登濮陽聖佛寺閣', '同羣公登濮陽聖佛寺閣', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["落日登臨處，悠然意不窮。","佛因初地識，人覺四天空。","來雁清霜後，孤帆遠樹中。","裴回傷寓目，蕭索對寒風。"]', '["落日登臨处，悠然意不窮。","佛因初地識，人覺四天空。","来雁清霜後，孤帆远樹中。","裴回傷寓目，蕭索对寒风。"]', '诗', 'shi', '', NULL, '同羣公登濮陽聖佛寺閣 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1f1cc1d-4eff-438e-8aea-60cb69174965', '同衛八題陸少府書齋', '同衛八題陸少府书斋', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["知君薄州縣，好靜無冬春。","散帙至棲鳥，明燈留故人。","深房臘酒熟，高院梅花新。","若是周旋地，當令風義親。"]', '["知君薄州縣，好静無冬春。","散帙至棲鸟，明灯留故人。","深房臘酒熟，高院梅花新。","若是周旋地，當令风義親。"]', '诗', 'shi', '', NULL, '同衛八題陸少府書齋 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e82c724f-b32f-4454-9051-0a6b94580869', '淇上別業', '淇上別業', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["依依西山下，別業桑林邊。","庭鴨喜多雨，鄰雞知暮天。","野人種秋菜，古老開原田。","且向世情遠，吾今聊自然。"]', '["依依西山下，別業桑林邊。","庭鴨喜多雨，鄰雞知暮天。","野人種秋菜，古老开原田。","且向世情远，吾今聊自然。"]', '诗', 'shi', '', NULL, '淇上別業 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('248e2198-070c-47f8-96a2-33e8952d1938', '入昌松東界山行', '入昌松东界山行', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["鳥道幾登頓，馬蹄無暫閑。","崎嶇出長坂，合沓猶前山。","石激水流處，天寒松色間。","王程應未盡，且莫顧刀環。"]', '["鸟道幾登頓，马蹄無暫闲。","崎嶇出长坂，合沓猶前山。","石激水流处，天寒松色间。","王程應未尽，且莫顧刀环。"]', '诗', 'shi', '', NULL, '入昌松東界山行 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f1a7ed4-5873-4cf1-9b28-3a454c54215a', '使青夷軍入居庸三首 一', '使青夷軍入居庸三首 一', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["匹馬行將久，征途去轉難。","不知邊地別，秪訝客衣單。","谿冷泉聲苦，山空木葉乾。","莫言關塞極，雲雪尚漫漫。"]', '["匹马行將久，征途去轉难。","不知邊地別，秪訝客衣單。","谿冷泉声苦，山空木葉乾。","莫言关塞極，云雪尚漫漫。"]', '诗', 'shi', '', NULL, '使青夷軍入居庸三首 一 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80a539fd-75f1-4590-83b2-5c7bf5c0c34c', '使青夷軍入居庸三首 二', '使青夷軍入居庸三首 二', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["古鎮青山口，寒風落日時。","巖巒鳥不過，冰雪馬堪遲。","出塞應無策，還家賴有期。","東山足松桂，歸去結茅茨。"]', '["古鎮青山口，寒风落日时。","巖巒鸟不過，冰雪马堪遲。","出塞應無策，還家賴有期。","东山足松桂，归去結茅茨。"]', '诗', 'shi', '', NULL, '使青夷軍入居庸三首 二 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3e12b3f-588f-4a2b-a256-a52942c6ab8f', '使青夷軍入居庸三首 三', '使青夷軍入居庸三首 三', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["登頓驅征騎，棲遲愧寶刀。","遠行今若此，微祿果徒勞。","絕坂水連下，羣峰雲共高。","自堪成白首，何事一青袍。"]', '["登頓驱征騎，棲遲愧寶刀。","远行今若此，微祿果徒勞。","絕坂水連下，羣峰云共高。","自堪成白首，何事一青袍。"]', '诗', 'shi', '', NULL, '使青夷軍入居庸三首 三 高適 shi');
